const selectedPlanStorageKey = "buildflow.selectedPlan";
const selectedProductsStorageKey = "buildflow.selectedProducts";

// Used when a user finishes onboarding via the additional-products path without
// having picked a business type (e.g. returning here from the HUD recovery
// screen). Keeps plan + program selection sufficient to open BuildFlow.
