function isBusinessTypeId(value: string): value is BusinessTypeId {
  return businessTypeOptions.includes(value as BusinessTypeId);
}

function isProductPlanId(value: string): value is ProductPlanId {
  return productPlans.some((plan) => plan.id === value);
}

function isOnboardingProductId(value: string): value is OnboardingProductId {
  return onboardingProductOptions.some((product) => product.id === value);
}

function readStoredBusinessType(): BusinessTypeId | "" {
  if (typeof window === "undefined") return "";
  const stored = window.localStorage.getItem(businessTypeStorageKey) ?? "";
  return isBusinessTypeId(stored) ? stored : "";
}

function readStoredPlan(): ProductPlanId | "" {
  if (typeof window === "undefined") return "";
  const stored = window.localStorage.getItem(selectedPlanStorageKey) ?? "";
  return isProductPlanId(stored) ? stored : "";
}

function readStoredProducts(): OnboardingProductId[] {
  if (typeof window === "undefined") return [];
  try {
    const parsed = JSON.parse(window.localStorage.getItem(selectedProductsStorageKey) ?? "[]") as unknown;
    if (!Array.isArray(parsed)) return [];
    return Array.from(new Set(parsed.filter((item): item is OnboardingProductId => typeof item === "string" && isOnboardingProductId(item))));
  } catch {
    return [];
  }
}

