function programPages(productId: OnboardingProductId) {
  const program = programRegistry[productId];
  return [program.primaryPage, ...program.relatedActions.map((action) => action.page)];
}

const permanentHudProgramIds: OnboardingProductId[] = ["map-field-ops"];

function selectedProductLabels(selectedProductIds: OnboardingProductId[]) {
  return selectedProductIds.flatMap((productId) => {
    const label = onboardingProductOptions.find((product) => product.id === productId)?.label;
    return label ? [label] : [];
  });
}

