type TutorialStatus = "idle" | "active" | "skipped" | "completed";
type TutorialValidation = "none" | "crewDialogOpen" | "crewCreated" | "jobDialogOpen" | "jobScheduled";
type TutorialTargetId =
  | "dashboard-setup-banner"
  | "dashboard-production-context"
  | "crew-add-button"
  | "crew-dialog"
  | "schedule-board"
  | "schedule-filters-button"
  | "schedule-alerts"
  | "schedule-add-job-button"
  | "schedule-job-dialog"
  | "schedule-job-submit"
  | "map-page-title"
  | "field-page-title"
  | "delayIQs-page-title"
  | "reports-page-title"
  | "materials-page-title"
  | "equipment-page-title"
  | "tutorial-restart-button";

type TutorialStep = {
  id: string;
  title: string;
  shortTitle: string;
  body: string;
  page?: Page;
  targetId?: TutorialTargetId;
  validation?: TutorialValidation;
  requirement?: string;
};

type TutorialSpotlightRect = {
  top: number;
  left: number;
  width: number;
  height: number;
};

type TutorialPanelPosition = {
  top: number;
  left: number;
};

function clampTutorialValue(value: number, min: number, max: number) {
  if (max < min) return min;
  return Math.min(Math.max(value, min), max);
}

function chooseTutorialPanelPosition(targetRect: DOMRect, panelRect: DOMRect | undefined, viewportWidth: number, viewportHeight: number) {
  const margin = 18;
  const panelWidth = Math.min(panelRect?.width ?? 430, viewportWidth - margin * 2);
  const panelHeight = Math.min(panelRect?.height ?? 360, viewportHeight - margin * 2);
  const maxLeft = viewportWidth - panelWidth - margin;
  const maxTop = viewportHeight - panelHeight - margin;
  const centerTargetVertically = clampTutorialValue(
    targetRect.top + targetRect.height / 2 - panelHeight / 2,
    margin,
    maxTop
  );
  const alignWithTarget = clampTutorialValue(targetRect.left, margin, maxLeft);
  const leftOfTarget = {
    left: targetRect.left - panelWidth - margin,
    top: centerTargetVertically
  };
  const rightOfTarget = {
    left: targetRect.right + margin,
    top: centerTargetVertically
  };
  const belowTarget = {
    left: alignWithTarget,
    top: targetRect.bottom + margin
  };
  const aboveTarget = {
    left: alignWithTarget,
    top: targetRect.top - panelHeight - margin
  };
  const sideCandidates =
    targetRect.left + targetRect.width / 2 > viewportWidth / 2
      ? [leftOfTarget, rightOfTarget, belowTarget, aboveTarget]
      : [rightOfTarget, leftOfTarget, belowTarget, aboveTarget];
  const fallback = { left: maxLeft, top: margin };
  const candidates = [...sideCandidates, fallback];

  return candidates.find(
    (candidate) =>
      candidate.left >= margin &&
      candidate.top >= margin &&
      candidate.left + panelWidth <= viewportWidth - margin &&
      candidate.top + panelHeight <= viewportHeight - margin
  ) ?? {
    left: clampTutorialValue(fallback.left, margin, maxLeft),
    top: clampTutorialValue(fallback.top, margin, maxTop)
  };
}

const tutorialStoragePrefix = "buildflow.tutorial.status";

function tutorialKeyPart(value: string) {
  return value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "none";
}

function createTutorialSetupKey({
  businessType,
  selectedPlan,
  selectedProducts
}: {
  businessType: BusinessTypeId | "";
  selectedPlan: ProductPlanId | "";
  selectedProducts: OnboardingProductId[];
}) {
  const productKey = [...selectedProducts].sort().map(tutorialKeyPart).join("+") || "core";
  return [
    tutorialKeyPart(businessType || "buildflow"),
    tutorialKeyPart(selectedPlan || "workspace"),
    productKey
  ].join("--");
}

function tutorialStorageKey(setupKey: string) {
  return `${tutorialStoragePrefix}:${setupKey}`;
}

function readStoredTutorialStatus(setupKey: string): Extract<TutorialStatus, "skipped" | "completed"> | null {
  if (typeof window === "undefined") return null;
  const stored = window.localStorage.getItem(tutorialStorageKey(setupKey));
  return stored === "skipped" || stored === "completed" ? stored : null;
}

function writeStoredTutorialStatus(setupKey: string, status: Extract<TutorialStatus, "skipped" | "completed">) {
  if (typeof window === "undefined") return;
  window.localStorage.setItem(tutorialStorageKey(setupKey), status);
}

function buildTutorialSteps({
  selectedBusinessType,
  selectedPlanId,
  selectedProductIds
}: {
  selectedBusinessType: BusinessTypeId | "";
  selectedPlanId: ProductPlanId | "";
  selectedProductIds: OnboardingProductId[];
}): TutorialStep[] {
  const selectedPlanName = selectedPlanId ? planById[selectedPlanId].name : "selected";
  const selectedProductsText = selectedProductLabels(selectedProductIds).join(", ") || "your selected tools";
  const businessLabel = selectedBusinessType || "your business";
  const coreSteps: TutorialStep[] = [
    {
      id: "intro",
      title: "Your BuildFlow workspace is ready",
      shortTitle: "Intro",
      body: `BuildFlow is set up for ${businessLabel} on the ${selectedPlanName} plan with ${selectedProductsText}. This tutorial will walk through the first real actions.`
    },
    {
      id: "dashboard-context",
      title: "Read your workspace context",
      shortTitle: "Dashboard",
      body: "Start on the dashboard to see the selected setup, weekly production schedule, KPIs, and active production context.",
      page: "dashboard",
      targetId: "dashboard-setup-banner"
    },
    {
      id: "open-crew-form",
      title: "Create a crew",
      shortTitle: "Create crew",
      body: "Open Add Crew. Use a sample like Tutorial Crew 1, Training, Jordan Lee, then set the labor and operator mix.",
      page: "crews",
      targetId: "crew-add-button",
      validation: "crewDialogOpen",
      requirement: "Open the Add Crew form to continue."
    },
    {
      id: "submit-crew",
      title: "Save the new crew",
      shortTitle: "Save crew",
      body: "Complete the crew form and submit it. BuildFlow will save the crew as a real demo workspace record.",
      page: "crews",
      targetId: "crew-dialog",
      validation: "crewCreated",
      requirement: "Create a crew to unlock the next step."
    },
    {
      id: "schedule-overview",
      title: "Read the schedule board",
      shortTitle: "Schedule",
      body: "The schedule board shows crews by row, days by column, assigned job cards, and the right-side queue of unassigned jobs.",
      page: "schedule",
      targetId: "schedule-board"
    },
    {
      id: "open-job-form",
      title: "Add a job to the schedule",
      shortTitle: "Add job",
      body: "Use an Add job button in a schedule cell to create a new job directly on the selected crew and day.",
      page: "schedule",
      targetId: "schedule-add-job-button",
      validation: "jobDialogOpen",
      requirement: "Open the Add job to schedule form to continue."
    },
    {
      id: "submit-job",
      title: "Create and schedule the job",
      shortTitle: "Schedule job",
      body: "Fill in the custom job fields, then create and schedule it. The job and assignment are saved together.",
      page: "schedule",
      targetId: "schedule-job-dialog",
      validation: "jobScheduled",
      requirement: "Create and schedule a job to continue."
    }
  ];

  const productSteps: Record<OnboardingProductId, TutorialStep[]> = {
    "crew-scheduling": [
      {
        id: "product-crew-scheduling",
        title: "Crew Scheduling lesson",
        shortTitle: "Crew Scheduling lesson",
        body: "Use filters, views, and alert shortcuts to focus the schedule by crew type, status, week, or alert.",
        page: "schedule",
        targetId: "schedule-filters-button"
      }
    ],
    "schedule-ai": [
      {
        id: "product-schedule-ai",
        title: "Schedule AI lesson",
        shortTitle: "Schedule AI lesson",
        body: "Scheduling Alerts surface conflicts, material blockers, and work that needs planner review before the day is published.",
        page: "schedule",
        targetId: "schedule-alerts"
      }
    ],
    "map-field-ops": [
      {
        id: "product-map-field-ops",
        title: "Map & Field Ops lesson",
        shortTitle: "Map & Field Ops lesson",
        body: "Review route context, live crew tracking, map filters, and active jobs from the Map & Field Ops workspace.",
        page: "mapProgram",
        targetId: "map-page-title"
      }
    ],
    "field-updates-delayIQs": [
      {
        id: "product-field-updates",
        title: "Field Updates lesson",
        shortTitle: "Field Updates lesson",
        body: "Field Updates collect daily progress, jobsite notes, photos, and status changes from crews and managers.",
        page: "field",
        targetId: "field-page-title"
      },
      {
        id: "product-delayIQs",
        title: "DelayIQ Management lesson",
        shortTitle: "DelayIQ Management lesson",
        body: "DelayIQ Management turns weather, site, labor, material, and inspection issues into visible schedule impact.",
        page: "delayIQs",
        targetId: "delayIQs-page-title"
      }
    ],
    "production-reports": [
      {
        id: "product-reports",
        title: "Production Reports lesson",
        shortTitle: "Production Reports lesson",
        body: "Reports summarize schedule variance, crew utilization, backlog, equipment utilization, and production trends.",
        page: "reports",
        targetId: "reports-page-title"
      }
    ],
    "materials-readiness": [
      {
        id: "product-materials",
        title: "Materials Readiness lesson",
        shortTitle: "Materials Readiness lesson",
        body: "Materials shows what is ready, ordered, waiting, or missing before a job lands on the daily plan.",
        page: "materials",
        targetId: "materials-page-title"
      }
    ],
    "equipment-tracking": [
      {
        id: "product-equipment",
        title: "Equipment Tracking lesson",
        shortTitle: "Equipment Tracking lesson",
        body: "Equipment shows fleet availability, current assignments, maintenance, and assets already committed to work.",
        page: "equipment",
        targetId: "equipment-page-title"
      }
    ]
  };

  const selectedProductSteps = selectedProductIds.flatMap((productId) => productSteps[productId]);
  const uniqueProductSteps = selectedProductSteps.filter(
    (step, index, steps) => steps.findIndex((item) => item.id === step.id) === index
  );

  return [
    ...coreSteps,
    ...uniqueProductSteps,
    {
      id: "wrap-up",
      title: "Tutorial complete",
      shortTitle: "Wrap-up",
      body: "You can restart this walkthrough any time from the Tutorial button in the top bar.",
      page: "dashboard",
      targetId: "tutorial-restart-button"
    }
  ];
}

function targetExists(targetId: TutorialTargetId) {
  if (typeof document === "undefined") return false;
  return Boolean(document.querySelector(`[data-tutorial-id="${targetId}"]`));
}

function tutorialStepIsSatisfied(
  step: TutorialStep,
  data: BootstrapPayload,
  baseline: { crews: number; jobs: number; assignments: number }
) {
  switch (step.validation) {
    case "crewDialogOpen":
      return targetExists("crew-dialog");
    case "crewCreated":
      return data.crews.length > baseline.crews;
    case "jobDialogOpen":
      return targetExists("schedule-job-dialog");
    case "jobScheduled":
      return data.jobs.length > baseline.jobs && data.assignments.length > baseline.assignments;
    default:
      return true;
  }
}

