    { strong: "Pull framing forward", detail: "Uses Crew 2 capacity", badge: "STEP 2", tone: "ready", icon: CheckCircle2 },
    { strong: "Flag milestone risk", detail: "Notify PM · 1 day at stake", badge: "REVIEW", tone: "wait", icon: ShieldAlert }
