/* ═══════════════════════════════════════════════════════════════════════════
   WAITLIST PAGE — removable pre-launch feature (welcome hash #waitlist).
   Captures emails for the pre-launch waitlist (pre-marketing hype). Designed to
   be deleted at any time: this whole block, the six `waitlist`-tagged wiring
   lines elsewhere in this file (grep -n waitlist src/App.tsx), the waitlist.css
   file, and its import in main.tsx. Emails are stored only in localStorage
   ("buildflow.waitlist") — no backend, no other dependencies.
   ═══════════════════════════════════════════════════════════════════════════ */
const WAITLIST_STORAGE_KEY = "buildflow.waitlist";
const WAITLIST_BASE_COUNT = 2137;

// waitlist (removable feature): target launch date — the single source of truth
// for the "Launching …" eyebrows + waitlist hero. Change this one line to move
// the date. (Month is 0-indexed, so 8 = September.)
const LAUNCH_DATE = new Date(2026, 8, 21);
const LAUNCH_DATE_LABEL = (() => {
  const month = LAUNCH_DATE.toLocaleDateString("en-US", { month: "long" });
  const day = LAUNCH_DATE.getDate();
  const ord =
    day % 10 === 1 && day !== 11 ? "st" :
    day % 10 === 2 && day !== 12 ? "nd" :
    day % 10 === 3 && day !== 13 ? "rd" : "th";
  return `${month} ${day}${ord}`; // e.g. "September 21st"
})();

function readWaitlistEmails(): string[] {
  if (typeof window === "undefined") return [];
  try {
    const parsed = JSON.parse(window.localStorage.getItem(WAITLIST_STORAGE_KEY) ?? "[]") as unknown;
    return Array.isArray(parsed) ? parsed.filter((item): item is string => typeof item === "string") : [];
  } catch {
    return [];
  }
}

// waitlist (removable feature): animated live countdown to LAUNCH_DATE. Re-renders
// every second; each unit's number is re-keyed on change so the CSS roll animation
// (wl-cd-roll in waitlist.css) replays on every tick. role="timer" carries the
// state for screen readers (implicit aria-live=off, so no per-second spam); the
// digits themselves are aria-hidden.
function WaitlistCountdown() {
  const msLeft = () => Math.max(0, LAUNCH_DATE.getTime() - Date.now());
  const [remaining, setRemaining] = useState(msLeft);

  useEffect(() => {
    const id = window.setInterval(() => setRemaining(msLeft()), 1000);
    return () => window.clearInterval(id);
  }, []);

  if (remaining <= 0) {
    return (
      <div className="wl-countdown wl-countdown-live" role="status">
        <span className="wl-cd-livemsg">We&rsquo;re live &mdash; early access is open 🚀</span>
      </div>
    );
  }

  const totalSeconds = Math.floor(remaining / 1000);
  const days = Math.floor(totalSeconds / 86400);
  const hours = Math.floor((totalSeconds % 86400) / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;
  const pad = (n: number) => String(n).padStart(2, "0");
  const units = [
    { label: "Days", value: String(days) },
    { label: "Hours", value: pad(hours) },
    { label: "Minutes", value: pad(minutes) },
    { label: "Seconds", value: pad(seconds) }
  ];

  return (
    <div
      className="wl-countdown"
      role="timer"
      aria-label={`${days} days, ${hours} hours, ${minutes} minutes until BuildFlow launches on ${LAUNCH_DATE_LABEL}`}
    >
      {units.map((unit) => (
        <div className="wl-cd-unit" key={unit.label} aria-hidden="true">
          <div className="wl-cd-box">
            <span className="wl-cd-num" key={unit.value}>{unit.value}</span>
          </div>
          <span className="wl-cd-label">{unit.label}</span>
        </div>
      ))}
    </div>
  );
}

function WelcomeWaitlistPage({ onBack }: { onBack: () => void }) {
  const rootRef = useRef<HTMLElement>(null);
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [joined, setJoined] = useState(false);
  const [count, setCount] = useState(() => WAITLIST_BASE_COUNT + readWaitlistEmails().length);
  const [position, setPosition] = useState(0);
  const [submittedEmail, setSubmittedEmail] = useState("");
  const [submitting, setSubmitting] = useState(false);

  // Pointer-reactive auroras — same tween the welcome home uses.
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    let raf = 0;
    const handleMove = (event: PointerEvent) => {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => {
        const nx = event.clientX / window.innerWidth;
        const ny = event.clientY / window.innerHeight;
        root.style.setProperty("--mx", `${event.clientX}px`);
        root.style.setProperty("--my", `${event.clientY}px`);
        root.style.setProperty("--px", `${(nx - 0.5) * 2}`);
        root.style.setProperty("--py", `${(ny - 0.5) * 2}`);
      });
    };
    window.addEventListener("pointermove", handleMove);
    return () => {
      window.removeEventListener("pointermove", handleMove);
      cancelAnimationFrame(raf);
    };
  }, []);

  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const value = email.trim().toLowerCase();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) {
      setError("Please enter a valid email address.");
      return;
    }
    setError("");
    setSubmitting(true);
    // Keep a local copy too — powers the count offline and is a graceful
    // fallback if the backend is unreachable.
    const list = readWaitlistEmails();
    if (!list.includes(value)) list.push(value);
    try {
      window.localStorage.setItem(WAITLIST_STORAGE_KEY, JSON.stringify(list));
    } catch {
      // ignore storage failures — the confirmation still shows
    }
    let total = WAITLIST_BASE_COUNT + list.length;
    try {
      // POST to the backend, which saves the signup and sends the confirmation email.
      const response = await fetch("/api/waitlist", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: value })
      });
      if (response.status === 400) {
        setError("Please enter a valid email address.");
        setSubmitting(false);
        return;
      }
      if (response.ok) {
        const data = (await response.json().catch(() => null)) as { count?: number } | null;
        if (data && typeof data.count === "number") total = WAITLIST_BASE_COUNT + data.count;
      }
    } catch {
      // Backend unreachable — fall back to the local success state.
    }
    setSubmittedEmail(value);
    setPosition(total);
    setCount(total);
    setSubmitting(false);
    setJoined(true);
    track(EVENTS.waitlistSignup, { position: total }); // primary pre-launch conversion
  };

  return (
    <main id="waitlist" ref={rootRef}>
      <BackgroundBeams />

      {joined ? (
        <div className="wl-content">
          <span className="wl-brand"><BuildFlowLogoMark /> BuildFlow</span>
          <span className="wl-check"><CheckCircle2 size={30} /></span>
          <h1 className="wl-title">You&rsquo;re on the list.</h1>
          <p className="wl-sub">
            Thanks for signing up. We&rsquo;ll email <strong style={{ color: "#1c1c1a" }}>{submittedEmail}</strong> the
            moment early access opens &mdash; keep an eye on your inbox.
          </p>
          <div className="wl-position">You&rsquo;re builder <b>#{position.toLocaleString()}</b> in line</div>
          {/* waitlist (removable feature): same live launch countdown on the confirmation screen */}
          <WaitlistCountdown />
          <a className="wl-back" onClick={onBack} role="button" tabIndex={0}>&larr; Back to home</a>
        </div>
      ) : (
        <div className="wl-content">
          <span className="wl-brand"><BuildFlowLogoMark /> BuildFlow</span>
          <div><span className="wl-badge"><span className="wl-live" /> Launching {LAUNCH_DATE_LABEL}</span></div>
          <h1 className="wl-title"><WxTypewriter normal="Join the " em="waitlist" /></h1>
          <p className="wl-sub">
            BuildFlow is the command center for construction crews, schedules, and materials &mdash; launching {LAUNCH_DATE_LABEL}.
            Get on the list for early access before launch, founding-member pricing, and a heads-up the day we go live.
          </p>
          {/* waitlist (removable feature): animated live countdown to launch */}
          <WaitlistCountdown />
          <form className="wl-form" onSubmit={submit} noValidate>
            <div className="wl-field">
              <input
                className={`wl-input${error ? " err" : ""}`}
                type="email"
                inputMode="email"
                autoComplete="email"
                placeholder="you@company.com"
                value={email}
                onChange={(event) => {
                  setEmail(event.target.value);
                  if (error) setError("");
                }}
                aria-label="Email address"
                aria-invalid={error ? true : undefined}
              />
            </div>
            <button type="submit" className="wl-submit" disabled={email.trim().length === 0 || submitting}>
              {submitting ? "Joining…" : <>Join the waitlist <ArrowRight size={17} /></>}
            </button>
          </form>
          {error && <p className="wl-error" role="alert">{error}</p>}
          <div className="wl-proof">
            <div className="wl-avatars" aria-hidden="true"><i>MJ</i><i>TR</i><i>LS</i><i>+</i></div>
            <span><b>{count.toLocaleString()}</b> builders already in line</span>
          </div>
          <a className="wl-back" onClick={onBack} role="button" tabIndex={0}>&larr; Back to home</a>
        </div>
      )}
    </main>
  );
}
/* ════════════════════════ END WAITLIST PAGE (removable) ════════════════════ */

function WelcomeContactSalesPage({
  onBack,
  onGetStarted,
  onOpenPlans
}: {
  onBack: () => void;
  onGetStarted: () => void;
  onOpenPlans: () => void;
}) {
  const rootRef = useRef<HTMLElement>(null);
  const formRef = useRef<HTMLFormElement>(null);
  const [sent, setSent] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");
  const [form, setForm] = useState({
    name: "",
    email: "",
    phone: "",
    company: "",
    teamSize: "11–50",
    interest: "Enterprise plan",
    message: ""
  });

  // Pointer-reactive auroras / cursor — same tween the welcome home uses.
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    let raf = 0;
    const handleMove = (event: PointerEvent) => {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => {
        const nx = event.clientX / window.innerWidth;
        const ny = event.clientY / window.innerHeight;
        root.style.setProperty("--mx", `${event.clientX}px`);
        root.style.setProperty("--my", `${event.clientY}px`);
        root.style.setProperty("--px", `${(nx - 0.5) * 2}`);
        root.style.setProperty("--py", `${(ny - 0.5) * 2}`);
      });
    };
    window.addEventListener("pointermove", handleMove);
    return () => {
      window.removeEventListener("pointermove", handleMove);
      cancelAnimationFrame(raf);
    };
  }, []);

  // Reveal-on-scroll tweens (IntersectionObserver adds .in).
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const targets = root.querySelectorAll("[data-reveal]");
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add("in");
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.12, rootMargin: "0px 0px -6% 0px" }
    );
    targets.forEach((el) => observer.observe(el));
    return () => observer.disconnect();
  }, []);

  const update =
    (key: keyof typeof form) =>
    (event: ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) =>
      setForm((prev) => ({ ...prev, [key]: event.target.value }));

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (submitting) return;
    setSubmitting(true);
    setError("");
    try {
      const res = await fetch("/api/contact-sales", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form)
      });
      if (!res.ok) throw new Error("Request failed");
      setSent(true);
      track(EVENTS.contactSales, { source: "contact_sales_page" }); // no PII sent to analytics
    } catch {
      setError("Something went wrong sending your message. Please try again.");
    } finally {
      setSubmitting(false);
    }
  };

  const enterpriseIncludes: Array<{ icon: typeof Grid2X2; title: string; text: string }> = [
    { icon: Building2, title: "Everything in Business", text: "Cross-project dispatch, advanced field permissions, and route & equipment coordination." },
    { icon: Wrench, title: "Custom features & workflows", text: "We shape scheduling, statuses, and reports around how your crews actually run." },
    { icon: LineChart, title: "Executive schedule-health", text: "Roll-up visibility across every project, division, and region in one view." },
    { icon: ShieldAlert, title: "Priority support & security review", text: "A named contact, guided onboarding, and a security review for your team." }
  ];

  const nextSteps: Array<{ n: string; title: string; text: string }> = [
    { n: "01", title: "Tell us your setup", text: "Share your team size and what you want BuildFlow to do." },
    { n: "02", title: "See a tailored walkthrough", text: "We map the Enterprise plan and any custom features to your operation." },
    { n: "03", title: "Roll it out", text: "Guided onboarding gets your crews and managers live in days." }
  ];

  const teamSizes = ["1–10", "11–50", "51–200", "201–500", "500+"];
  const interests = ["Enterprise plan", "Custom features", "Both", "Not sure yet"];
  const firstName = form.name.trim().split(" ")[0];

  return (
    <main className="cs-page csx-page" id="contact-sales" ref={rootRef}>
      <div className="wx-bg" aria-hidden="true">
        <div className="wx-aurora wx-aurora-1" />
        <div className="wx-aurora wx-aurora-2" />
        <div className="wx-aurora wx-aurora-3" />
      </div>
      <div className="wx-cursor" aria-hidden="true" />

      {/* Hero */}
      <section className="cmp-hero csx-hero" data-reveal>
        <span className="wx-eyebrow"><span className="wx-dot" /> Contact sales</span>
        <h1 className="cmp-title">
          <WxTypewriter normal="Let's build your " em="Enterprise plan." />
        </h1>
        <p className="cmp-sub">
          Talk to our team about the Enterprise tier &mdash; or custom features built around how your crews run.
          Tell us what you need and we&rsquo;ll map it to BuildFlow, then follow up within one business day.
        </p>
      </section>

      {/* Info + form */}
      <section className="csx-grid">
        <div className="csx-info" data-reveal>
          <h2 className="csx-info-title">What you get with Enterprise</h2>
          <ul className="csx-includes">
            {enterpriseIncludes.map((item, index) => {
              const Icon = item.icon;
              return (
                <li className="csx-include" data-reveal style={{ "--i": index } as CSSProperties} key={item.title}>
                  <span className="csx-include-ic"><Icon size={18} /></span>
                  <div>
                    <strong>{item.title}</strong>
                    <p>{item.text}</p>
                  </div>
                </li>
              );
            })}
          </ul>
          <div className="csx-trust">
            <span className="csx-trust-item"><MessageCircle size={15} /> Talk to a real person</span>
            <span className="csx-trust-item"><ShieldAlert size={15} /> Security review included</span>
            <span className="csx-trust-item"><Users size={15} /> Dedicated onboarding</span>
          </div>
        </div>

        <div className="csx-form-wrap" data-reveal style={{ "--i": 1 } as CSSProperties}>
          <WxTilt className="csx-form-tilt" max={3} restRx={0} restRy={0}>
            <article className="csx-form-card">
              {sent ? (
                <div className="csx-success">
                  <span className="csx-success-ic"><CheckCircle2 size={30} /></span>
                  <h3>Thanks{firstName ? `, ${firstName}` : ""}!</h3>
                  <p>
                    Your request is in — we&rsquo;ve emailed a confirmation to <strong>{form.email}</strong> and
                    notified our sales team. A BuildFlow specialist will reach out within one business day.
                  </p>
                  <div className="csx-success-actions">
                    <WxMagnetic className="wx-btn wx-btn-line" onClick={() => { setSent(false); setError(""); }} ariaLabel="Send another message">
                      Send another
                    </WxMagnetic>
                    <WxMagnetic className="wx-btn wx-btn-ink" onClick={onGetStarted} ariaLabel="Try the free demo">
                      Try the demo <ArrowRight size={16} />
                    </WxMagnetic>
                  </div>
                </div>
              ) : (
                <>
                  <h2 className="csx-form-title">Tell us about your team</h2>
                  <p className="csx-form-sub">We&rsquo;ll tailor the plan to your operation.</p>
                  <form ref={formRef} className="csx-form" onSubmit={handleSubmit}>
                    <label className="csx-field">
                      <span>Full name</span>
                      <input type="text" required value={form.name} onChange={update("name")} placeholder="Jordan Reyes" autoComplete="name" />
                    </label>
                    <label className="csx-field">
                      <span>Work email</span>
                      <input type="email" required value={form.email} onChange={update("email")} placeholder="jordan@company.com" autoComplete="email" />
                    </label>
                    <label className="csx-field">
                      <span>Phone number <span className="csx-optional">(optional)</span></span>
                      <input type="tel" value={form.phone} onChange={update("phone")} placeholder="(555) 123-4567" autoComplete="tel" />
                    </label>
                    <label className="csx-field">
                      <span>Company</span>
                      <input type="text" required value={form.company} onChange={update("company")} placeholder="Reyes Construction" autoComplete="organization" />
                    </label>
                    <div className="csx-field-row">
                      <label className="csx-field">
                        <span>Team size</span>
                        <select value={form.teamSize} onChange={update("teamSize")}>
                          {teamSizes.map((size) => <option key={size} value={size}>{size} people</option>)}
                        </select>
                      </label>
                      <label className="csx-field">
                        <span>I&rsquo;m interested in</span>
                        <select value={form.interest} onChange={update("interest")}>
                          {interests.map((opt) => <option key={opt} value={opt}>{opt}</option>)}
                        </select>
                      </label>
                    </div>
                    <label className="csx-field">
                      <span>What would you like to build?</span>
                      <textarea rows={4} value={form.message} onChange={update("message")} placeholder="Tell us about the custom features or Enterprise needs you have in mind…" />
                    </label>
                    {error && <p className="csx-form-error" role="alert">{error}</p>}
                    <WxMagnetic className="wx-btn wx-btn-ink csx-submit" onClick={() => formRef.current?.requestSubmit()} ariaLabel="Talk to sales" disabled={submitting}>
                      {submitting ? "Sending…" : <>Talk to sales <ArrowRight size={17} /></>}
                    </WxMagnetic>
                    <p className="csx-form-fine">By submitting, you agree to be contacted about BuildFlow. No spam — just a real conversation.</p>
                  </form>
                </>
              )}
            </article>
          </WxTilt>
        </div>
      </section>

      {/* What happens next */}
      <section className="csx-steps-sec" data-reveal>
        <div className="csx-steps-head">
          <span className="wx-eyebrow-2">What happens next</span>
          <h2>From first message to live crews.</h2>
        </div>
        <div className="csx-steps">
          {nextSteps.map((step, index) => (
            <article className="csx-step" data-reveal style={{ "--i": index } as CSSProperties} key={step.n}>
              <span className="csx-step-n">{step.n}</span>
              <strong>{step.title}</strong>
              <p>{step.text}</p>
            </article>
          ))}
        </div>
      </section>

      {/* CTA — same animated globe closer as the compare page */}
      <section className="cs-cta cs-cta-globe" data-reveal>
        <div className="cs-cta-field" aria-hidden="true" />
        <div className="cs-cta-copy">
          <span className="wx-eyebrow"><span className="wx-dot" /> Not ready to talk?</span>
          <h2>Explore BuildFlow free while you decide.</h2>
          <p>Open the same production board every plan runs on. Try it with your own week, then come back when you want the Enterprise conversation.</p>
          <div className="cs-cta-actions">
            <WxMagnetic className="wx-btn wx-btn-paper" onClick={onGetStarted} ariaLabel="Start free">
              Start free <ArrowRight size={17} />
            </WxMagnetic>
            <WxMagnetic className="wx-btn wx-btn-ghostline" onClick={onOpenPlans} ariaLabel="Compare plans">
              Compare plans
            </WxMagnetic>
          </div>
        </div>
        <div className="cs-cta-globe-stage" aria-hidden="true">
          <GlobePulse className="cs-cta-globe-el" markers={ctaGlobeMarkers} />
        </div>
      </section>

      {/* Footer */}
      <footer className="wx-footer">
        <div className="wx-footer-top">
          <p className="wx-footer-tagline">Keep crews, materials, and schedules moving together.</p>
          <nav className="wx-footer-links" aria-label="Footer">
            <div>
              <h3>Plans</h3>
              <a href="#free-plan">Free</a>
              <a href="#pro-plan">Pro</a>
              <a href="#business-plan">Business</a>
              <a href="#enterprise-plan">Enterprise</a>
            </div>
            <div>
              <h3>Resources</h3>
              <a href="#updates">Updates</a>
              <a href="#help-center">Help center</a>
              <a href="#templates">Templates</a>
              <a href="#partners">Partner programs</a>
              <a href="#integrations">Integrations</a>
            </div>
            <div>
              <h3>Company</h3>
              <a href="#about">About us</a>
              <a href="#customers">Customers</a>
              <a href="#careers">Careers</a>
              <a onClick={onBack} role="button" tabIndex={0}>Contact sales</a>
            </div>
          </nav>
        </div>

        <div className="wx-footer-word" aria-hidden="true">
          {"BuildFlow".split("").map((letter, index) => (
            <span key={index} style={{ "--i": index } as CSSProperties}>
              {letter}
            </span>
          ))}
        </div>

        <div className="wx-footer-legal">
          <div className="wx-footer-brand">
            <BuildFlowLogoMark />
            <strong>BuildFlow</strong>
          </div>
          <div className="wx-footer-legal-links">
            <a onClick={onBack} role="button" tabIndex={0}>Back to home</a>
            <a href="#privacy">Privacy</a>
            <a href="#terms">Terms</a>
            <a href="#security">Security</a>
          </div>
        </div>
      </footer>
    </main>
  );
}

// ── Legal pages (Privacy / Terms / Security) ─────────────────────────────────
// Content is plain template copy for launch prep — have counsel review before
// relying on it. Editing lives entirely in `legalDocs` below; the page renders
// any doc via the shared `.cs-page` welcome system (see legal-redesign.css).
//
// GUARDRAIL — draft status. While LEGAL_DRAFT is true, every legal page renders
// an unmissable amber "draft — not yet binding" banner (always visible, never
// gated behind scroll reveal) and the effective-date line reads "Draft — not yet
// in effect", so this template language can't be mistaken for a live, binding
// policy. Flip LEGAL_DRAFT to false ONLY after counsel has reviewed and approved
// the final copy (then set each doc's real `updated` effective date below).
const LEGAL_DRAFT = true;

type LegalDocId = "privacy" | "terms" | "security";
type LegalBlock = string | { list: string[] };
type LegalSection = { id: string; title: string; body: LegalBlock[] };
type LegalDocConfig = {
  icon: typeof FileText;
  eyebrow: string;
  titleNormal: string;
  titleEm: string;
  summary: string;
  updated: string;
  sections: LegalSection[];
};

