function WelcomeLegalPage({
  doc,
  onBack,
  onGetStarted,
  onContactSales
}: {
  doc: LegalDocId;
  onBack: () => void;
  onGetStarted: () => void;
  onContactSales: () => void;
}) {
  const rootRef = useRef<HTMLElement>(null);
  const config = legalDocs[doc];
  const NoteIcon = config.icon;

  // Pointer-reactive auroras / cursor — same tween the welcome home uses.
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    let raf = 0;
    const handleMove = (event: PointerEvent) => {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => {
        const nx = event.clientX / window.innerWidth;
        const ny = event.clientY / window.innerHeight;
        root.style.setProperty("--mx", `${event.clientX}px`);
        root.style.setProperty("--my", `${event.clientY}px`);
        root.style.setProperty("--px", `${(nx - 0.5) * 2}`);
        root.style.setProperty("--py", `${(ny - 0.5) * 2}`);
      });
    };
    window.addEventListener("pointermove", handleMove);
    return () => {
      window.removeEventListener("pointermove", handleMove);
      cancelAnimationFrame(raf);
    };
  }, []);

  // Reveal-on-scroll tweens (IntersectionObserver adds .in).
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const targets = root.querySelectorAll("[data-reveal]");
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add("in");
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.12, rootMargin: "0px 0px -6% 0px" }
    );
    targets.forEach((el) => observer.observe(el));
    return () => observer.disconnect();
  }, []);

  const scrollToSection = (sectionId: string) => {
    const el = rootRef.current?.querySelector(`#${doc}-${sectionId}`) as HTMLElement | null;
    if (el && typeof el.scrollIntoView === "function") {
      try {
        el.scrollIntoView({ behavior: "smooth", block: "start" });
      } catch {
        /* ignore environments without smooth scrolling */
      }
    }
  };

  return (
    <main className="cs-page lgx-page" id={doc} ref={rootRef}>
      <div className="wx-bg" aria-hidden="true">
        <div className="wx-aurora wx-aurora-1" />
        <div className="wx-aurora wx-aurora-2" />
        <div className="wx-aurora wx-aurora-3" />
      </div>
      <div className="wx-cursor" aria-hidden="true" />

      {/* Hero */}
      <section className="cmp-hero lgx-hero" data-reveal>
        <span className="wx-eyebrow"><span className="wx-dot" /> {config.eyebrow}</span>
        <h1 className="cmp-title">
          <WxTypewriter normal={config.titleNormal} em={config.titleEm} />
        </h1>
        <p className="cmp-sub">{config.summary}</p>
        <p className="lgx-updated">
          <Clock size={14} /> {LEGAL_DRAFT ? "Draft — not yet in effect" : config.updated}
        </p>
      </section>

      {/* Draft guardrail — non-binding notice while LEGAL_DRAFT is true. Deliberately
          NOT [data-reveal]: a legal status notice must never depend on scroll to appear. */}
      {LEGAL_DRAFT && (
        <aside className="lgx-draft" role="note" aria-label="Draft notice — not legally binding">
          <span className="lgx-draft-ic" aria-hidden="true"><AlertTriangle size={20} /></span>
          <div>
            <strong className="lgx-draft-title">Draft for review — not yet binding</strong>
            <p>
              This document is placeholder template language shared for review. It is{" "}
              <b>not yet in effect and is not a binding agreement</b>, and will apply only once
              BuildFlow&rsquo;s legal counsel has reviewed and published the final version.{" "}
              <a role="button" tabIndex={0} onClick={onContactSales}>Contact our team</a> with any questions.
            </p>
          </div>
        </aside>
      )}

      {/* Body: sticky TOC + article */}
      <section className="lgx-body">
        <aside className="lgx-toc" data-reveal>
          <span className="lgx-toc-label">On this page</span>
          <nav>
            {config.sections.map((section) => (
              <a
                key={section.id}
                role="button"
                tabIndex={0}
                onClick={() => scrollToSection(section.id)}
                onKeyDown={(event) => {
                  if (event.key === "Enter" || event.key === " ") {
                    event.preventDefault();
                    scrollToSection(section.id);
                  }
                }}
              >
                {section.title}
              </a>
            ))}
          </nav>
          <div className="lgx-switch">
            <span className="lgx-toc-label">BuildFlow legal</span>
            {legalDocOrder.map((id) => {
              const Icon = legalDocs[id].icon;
              return (
                <a key={id} href={legalDocHashes[id]} className={id === doc ? "is-active" : ""}>
                  <Icon size={15} /> {legalDocLabels[id]}
                </a>
              );
            })}
          </div>
        </aside>

        <article className="lgx-doc">
          {config.sections.map((section, index) => (
            <section className="lgx-section" id={`${doc}-${section.id}`} data-reveal key={section.id}>
              <h2>
                <span className="lgx-num">{String(index + 1).padStart(2, "0")}</span>
                {section.title}
              </h2>
              {section.body.map((block, blockIndex) =>
                typeof block === "string" ? (
                  <p key={blockIndex}>{block}</p>
                ) : (
                  <ul key={blockIndex}>
                    {block.list.map((item, itemIndex) => (
                      <li key={itemIndex}>{item}</li>
                    ))}
                  </ul>
                )
              )}
            </section>
          ))}

          <div className="lgx-note" data-reveal>
            <span className="lgx-note-ic"><NoteIcon size={20} /></span>
            <div>
              <h3>Questions about our {config.eyebrow.toLowerCase()}?</h3>
              <p>
                We&rsquo;re happy to walk your team through how BuildFlow handles your data.{" "}
                <a role="button" tabIndex={0} onClick={onContactSales}>Contact our team</a> and we&rsquo;ll follow up.
              </p>
            </div>
          </div>
        </article>
      </section>

      {/* Footer */}
      <footer className="wx-footer">
        <div className="wx-footer-top">
          <p className="wx-footer-tagline">Keep crews, materials, and schedules moving together.</p>
          <nav className="wx-footer-links" aria-label="Footer">
            <div>
              <h3>Plans</h3>
              <a onClick={onGetStarted} role="button" tabIndex={0}>Free</a>
              <a onClick={onGetStarted} role="button" tabIndex={0}>Pro</a>
              <a onClick={onGetStarted} role="button" tabIndex={0}>Business</a>
              <a onClick={onContactSales} role="button" tabIndex={0}>Enterprise</a>
            </div>
            <div>
              <h3>Resources</h3>
              <a href="#updates">Updates</a>
              <a href="#help-center">Help center</a>
              <a href="#templates">Templates</a>
              <a href="#partners">Partner programs</a>
              <a href="#integrations">Integrations</a>
            </div>
            <div>
              <h3>Company</h3>
              <a href="#about">About us</a>
              <a href="#customers">Customers</a>
              <a href="#careers">Careers</a>
              <a href="#contact-sales">Contact sales</a>
            </div>
          </nav>
        </div>

        <div className="wx-footer-word" aria-hidden="true">
          {"BuildFlow".split("").map((letter, index) => (
            <span key={index} style={{ "--i": index } as CSSProperties}>
              {letter}
            </span>
          ))}
        </div>

        <div className="wx-footer-legal">
          <div className="wx-footer-brand">
            <BuildFlowLogoMark />
            <strong>BuildFlow</strong>
          </div>
          <div className="wx-footer-legal-links">
            <a onClick={onBack} role="button" tabIndex={0}>Back to home</a>
            <a href="#privacy">Privacy</a>
            <a href="#terms">Terms</a>
            <a href="#security">Security</a>
          </div>
        </div>
      </footer>
    </main>
  );
}

// ── Templates page (#templates) ──────────────────────────────────────────────
type TemplateCategory = "Projects" | "Scheduling" | "Field & Ops" | "Reporting";
type TemplateItem = { name: string; category: TemplateCategory; meta: string; icon: typeof Building2; desc: string };

const scheduleTemplates: TemplateItem[] = [
  { name: "Commercial Concrete Pour", category: "Projects", meta: "6 phases", icon: Building2, desc: "A multi-day pour sequenced with rebar, forms, inspections, and cure windows built in." },
  { name: "Site Development & Grading", category: "Projects", meta: "8 jobs", icon: Truck, desc: "Earthwork, utilities, and grading staged with locates and weather holds accounted for." },
  { name: "Roofing Project", category: "Projects", meta: "5 phases", icon: Layers, desc: "Tear-off through membrane and flashing, staged by crew and weather risk." },
  { name: "Weekly Crew Schedule", category: "Scheduling", meta: "per week", icon: CalendarDays, desc: "Assign every crew across the week by capacity and readiness in minutes." },
  { name: "Multi-Project Dispatch", category: "Scheduling", meta: "multi-site", icon: Route, desc: "Coordinate crews and trucks across concurrent sites by location and travel time." },
  { name: "Equipment Maintenance Rotation", category: "Field & Ops", meta: "recurring", icon: Wrench, desc: "A preventive-maintenance cadence so machines never block a dispatch." },
  { name: "Materials Readiness Checklist", category: "Field & Ops", meta: "per job", icon: PackageCheck, desc: "Deliveries, permits, and locates tracked so crews only roll to work that can start." },
  { name: "Production Report Pack", category: "Reporting", meta: "CSV / PDF", icon: LineChart, desc: "Weekly production, delayIQs, and utilization — ready to export for the owner." }
];
const templateCategories: Array<TemplateCategory | "All"> = ["All", "Projects", "Scheduling", "Field & Ops", "Reporting"];

function WelcomeTemplatesPage({
  onBack,
  onGetStarted,
  onContactSales
}: {
  onBack: () => void;
  onGetStarted: () => void;
  onContactSales: () => void;
}) {
  const rootRef = useRef<HTMLElement>(null);
  const [category, setCategory] = useState<TemplateCategory | "All">("All");

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    let raf = 0;
    const handleMove = (event: PointerEvent) => {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => {
        const nx = event.clientX / window.innerWidth;
        const ny = event.clientY / window.innerHeight;
        root.style.setProperty("--mx", `${event.clientX}px`);
        root.style.setProperty("--my", `${event.clientY}px`);
        root.style.setProperty("--px", `${(nx - 0.5) * 2}`);
        root.style.setProperty("--py", `${(ny - 0.5) * 2}`);
      });
    };
    window.addEventListener("pointermove", handleMove);
    return () => {
      window.removeEventListener("pointermove", handleMove);
      cancelAnimationFrame(raf);
    };
  }, []);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const targets = root.querySelectorAll("[data-reveal]");
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add("in");
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.12, rootMargin: "0px 0px -6% 0px" }
    );
    targets.forEach((el) => observer.observe(el));
    return () => observer.disconnect();
  }, []);

  const visible = category === "All" ? scheduleTemplates : scheduleTemplates.filter((t) => t.category === category);

  return (
    <main className="cs-page tpx-page" id="templates" ref={rootRef}>
      <div className="wx-bg" aria-hidden="true">
        <div className="wx-aurora wx-aurora-1" />
        <div className="wx-aurora wx-aurora-2" />
        <div className="wx-aurora wx-aurora-3" />
      </div>
      <div className="wx-cursor" aria-hidden="true" />

      <section className="cmp-hero tpx-hero" data-reveal>
        <span className="wx-eyebrow"><span className="wx-dot" /> Templates</span>
        <h1 className="cmp-title">
          <WxTypewriter normal="Start from " em="a proven template." />
        </h1>
        <p className="cmp-sub">
          Skip the blank calendar. Every BuildFlow template is a real construction workflow &mdash; phases, crews,
          materials, and inspections already sequenced &mdash; so your team is scheduling on day one.
        </p>
        <div className="tpx-hero-actions">
          <WxMagnetic className="wx-btn wx-btn-ink" onClick={onGetStarted} ariaLabel="Start free with a template">
            Start free <ArrowRight size={16} />
          </WxMagnetic>
          <WxMagnetic className="wx-btn wx-btn-line" onClick={onContactSales} ariaLabel="Request a custom template">
            Request a custom template
          </WxMagnetic>
        </div>
      </section>

      <section data-reveal>
        <div className="tpx-filter" role="tablist" aria-label="Template categories">
          {templateCategories.map((cat) => (
            <button
              key={cat}
              type="button"
              role="tab"
              aria-selected={category === cat}
              className={`tpx-chip ${category === cat ? "is-active" : ""}`}
              onClick={() => setCategory(cat)}
            >
              {cat}
            </button>
          ))}
        </div>
        <div className="tpx-grid">
          {visible.map((tpl) => {
            const Icon = tpl.icon;
            return (
              <article className="tpx-card" key={tpl.name}>
                <div className="tpx-card-top">
                  <span className="tpx-card-ic"><Icon size={21} /></span>
                  <span className="tpx-tag">{tpl.category}</span>
                </div>
                <h3>{tpl.name}</h3>
                <p>{tpl.desc}</p>
                <div className="tpx-card-foot">
                  <span className="tpx-meta"><Layers size={13} /> {tpl.meta}</span>
                  <button type="button" className="tpx-use" onClick={onGetStarted}>Use template <ArrowRight size={14} /></button>
                </div>
              </article>
            );
          })}
        </div>
      </section>

      <section className="tpx-cta" data-reveal>
        <h2>Don&rsquo;t see your workflow?</h2>
        <p>Start from a blank board and BuildFlow shapes it around your crews &mdash; or tell us what you run and we&rsquo;ll build a template for you.</p>
        <div className="tpx-cta-actions">
          <WxMagnetic className="wx-btn wx-btn-ink" onClick={onGetStarted} ariaLabel="Start from scratch">
            Start from scratch <ArrowRight size={16} />
          </WxMagnetic>
          <WxMagnetic className="wx-btn wx-btn-line" onClick={onContactSales} ariaLabel="Talk to our team">
            Talk to our team
          </WxMagnetic>
        </div>
      </section>

      <WelcomeSharedFooter onBack={onBack} onGetStarted={onGetStarted} onContactSales={onContactSales} />
    </main>
  );
}

