function WelcomeComparePlansPage({ onBack, onGetStarted, onContactSales }: { onBack: () => void; onGetStarted: () => void; onContactSales: () => void }) {
  const rootRef = useRef<HTMLElement>(null);
  const [period, setPeriod] = useState<BillingPeriod>("monthly");
  const SEAT_MIN = 1;
  const SEAT_MAX = 50;
  // team-size scaling — each plan card carries its own slider so every tier prices independently
  const [seats, setSeats] = useState<Record<ProductPlanId, number>>({ free: 10, pro: 10, business: 10, enterprise: 10 });
  const setSeatFor = (id: ProductPlanId, value: number) => setSeats((prev) => ({ ...prev, [id]: value }));

  // Stripe Checkout: outcome notice + which plan is mid-request (for the button label).
  const [checkoutNotice, setCheckoutNotice] = useState<{ tone: "info" | "success" | "error"; message: string } | null>(null);
  const [checkoutBusyPlan, setCheckoutBusyPlan] = useState<ProductPlanId | null>(null);

  // Surface the ?checkout=success|cancelled marker Stripe appends when it redirects back.
  useEffect(() => {
    const ret = readCheckoutReturn();
    if (!ret) return;
    setCheckoutNotice(
      ret.status === "success"
        ? { tone: "success", message: "Payment received — your subscription is active. A receipt is on its way to your email." }
        : { tone: "info", message: "Checkout cancelled — no charge was made. Pick a plan whenever you’re ready." }
    );
  }, []);

  // Route a plan CTA: Free → demo signup, Enterprise → sales, Pro/Business → Stripe Checkout.
  const handlePlanCta = async (plan: ProductPlan) => {
    if (plan.id === "enterprise") return onContactSales();
    if (plan.id === "free" || plan.priceMonthly === null || plan.priceMonthly === 0) return onGetStarted();
    setCheckoutNotice(null);
    setCheckoutBusyPlan(plan.id);
    const outcome = await startPlanCheckout(plan.id as CheckoutPlanId, period, seats[plan.id]);
    setCheckoutBusyPlan(null);
    if (outcome.status === "not_configured") setCheckoutNotice({ tone: "info", message: outcome.message });
    else if (outcome.status === "error") setCheckoutNotice({ tone: "error", message: outcome.message });
    // "redirecting" → the browser is navigating to Stripe; leave the UI as-is.
  };

  // Pointer-reactive auroras / cursor — same tween the welcome home uses.
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    let raf = 0;
    const handleMove = (event: PointerEvent) => {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => {
        const nx = event.clientX / window.innerWidth;
        const ny = event.clientY / window.innerHeight;
        root.style.setProperty("--mx", `${event.clientX}px`);
        root.style.setProperty("--my", `${event.clientY}px`);
        root.style.setProperty("--px", `${(nx - 0.5) * 2}`);
        root.style.setProperty("--py", `${(ny - 0.5) * 2}`);
      });
    };
    window.addEventListener("pointermove", handleMove);
    return () => {
      window.removeEventListener("pointermove", handleMove);
      cancelAnimationFrame(raf);
    };
  }, []);

  // Reveal-on-scroll tweens (IntersectionObserver adds .in).
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const targets = root.querySelectorAll("[data-reveal]");
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add("in");
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.12, rootMargin: "0px 0px -6% 0px" }
    );
    targets.forEach((el) => observer.observe(el));
    return () => observer.disconnect();
  }, []);

  const cardFeats: Record<ProductPlanId, string[]> = {
    free: ["Production calendar & basic scheduling", "5 users included · 14-day trial", "Drag-and-drop work orders", "CSV / PDF export"],
    pro: ["Everything in Free, plus:", "Unlimited crew schedules", "Readiness rules & alerts", "Weekly production reports"],
    business: ["Everything in Pro, plus:", "Cross-project dispatch planning", "Advanced field permissions", "Route & equipment coordination"],
    enterprise: ["Everything in Business, plus:", "Custom onboarding & workflows", "Executive schedule-health views", "Priority support & security review"]
  };
  const bestFor: Record<ProductPlanId, string> = {
    free: "Kicking the tires on the production board.",
    pro: "The everyday planning workspace.",
    business: "Running several projects at once.",
    enterprise: "Custom operations at scale."
  };

  const compareGroups: Array<{ group: string; rows: Array<{ label: string; values: Array<boolean | string> }> }> = [
    {
      group: "Scheduling & production",
      rows: [
        { label: "Production calendar", values: ["Basic", true, true, true] },
        { label: "Job scheduling", values: ["Limited", "Unlimited", "Unlimited", "Unlimited"] },
        { label: "Drag-and-drop scheduling", values: [true, true, true, true] },
        { label: "Work orders", values: ["Basic", true, true, true] },
        { label: "Cross-project dispatch", values: [false, false, true, true] }
      ]
    },
    {
      group: "Team & capacity",
      rows: [
        { label: "Seats included", values: ["5", "Unlimited", "Unlimited", "Custom"] },
        { label: "Crew capacity planning", values: [false, true, true, true] },
        { label: "Advanced field permissions", values: [false, false, true, true] },
        { label: "Route & equipment coordination", values: [false, false, true, true] }
      ]
    },
    {
      group: "Reporting & insights",
      rows: [
        { label: "Production dashboard", values: [true, true, true, true] },
        { label: "Readiness rules & alerts", values: [false, true, true, true] },
        { label: "Weekly production reports", values: [false, true, true, true] },
        { label: "Executive schedule-health views", values: [false, false, false, true] },
        { label: "Data export (CSV / PDF)", values: [true, true, true, true] }
      ]
    },
    {
      group: "Support & onboarding",
      rows: [
        { label: "Support", values: ["Email", "Standard", "Priority", "Priority + security"] },
        { label: "Custom onboarding & workflows", values: [false, false, false, true] },
        { label: "Security review", values: [false, false, false, true] }
      ]
    }
  ];

  const steps: Array<{ id: ProductPlanId; pick: string; text: string; unlock: string }> = [
    { id: "free", pick: "If you're evaluating", text: "Explore the whole production week free for 14 days — no card, no commitment.", unlock: "Try the board risk-free." },
    { id: "pro", pick: "If you plan every day", text: "Publish live weekly schedules with readiness rules and reporting for one team.", unlock: "Unlocks unlimited schedules + weekly reports." },
    { id: "business", pick: "Most teams", text: "Coordinate crews, routes, permissions, and equipment across every active project.", unlock: "Unlocks cross-project dispatch + field permissions." },
    { id: "enterprise", pick: "If you need custom", text: "Shape BuildFlow around your process with executive visibility and priority support.", unlock: "Unlocks custom workflows + security review." }
  ];

  // Seat-scaled price for a plan: per-user rate (respecting the billing period)
  // multiplied by the number of seats picked on the slider.
  const planTotalLabel = (plan: ProductPlan): { big: string; suffix?: string; note: string; save?: string } => {
    if (plan.priceMonthly === null) return { big: "Custom", note: "Volume pricing · talk to sales" };
    if (plan.priceMonthly === 0) return { big: "$0", note: "Free · up to 5 users" };
    const n = seats[plan.id];
    const rate = period === "yearly" ? plan.priceMonthly * (1 - YEARLY_DISCOUNT) : plan.priceMonthly;
    return {
      big: formatPlanUsd(rate * n),
      suffix: "/mo",
      note: `${n} ${n === 1 ? "user" : "users"} · ${formatPlanUsd(rate)}/user${period === "yearly" ? " · billed yearly" : ""}`,
      save: period === "yearly" ? `Save 20% vs ${formatPlanUsd(plan.priceMonthly * n)}/mo` : undefined
    };
  };

  // Transparent entry price for the hero — the cheapest paid per-user rate (respects the billing toggle).
  const startingRates = productPlans.map((p) => p.priceMonthly).filter((v): v is number => v !== null && v > 0);
  const startingMonthly = startingRates.length ? Math.min(...startingRates) : 0;
  const startingDisplay = formatPlanUsd(period === "yearly" ? startingMonthly * (1 - YEARLY_DISCOUNT) : startingMonthly);

  const renderValue = (value: boolean | string) => {
    if (value === true) return <span className="cmp-check"><Check size={17} strokeWidth={3} /></span>;
    if (value === false) return <span className="cmp-dash" />;
    return <span className="cmp-val">{value}</span>;
  };

  return (
    <main className="cs-page" id="compare-plans" ref={rootRef}>
      <div className="wx-bg" aria-hidden="true">
        <div className="wx-aurora wx-aurora-1" />
        <div className="wx-aurora wx-aurora-2" />
        <div className="wx-aurora wx-aurora-3" />
      </div>
      <div className="wx-cursor" aria-hidden="true" />

      {/* Hero */}
      <section className="cmp-hero" data-reveal>
        <span className="wx-eyebrow"><span className="wx-dot" /> Plans</span>
        <h1 className="cmp-title">
          <WxTypewriter normal="Compare every " em="BuildFlow plan." />
        </h1>
        <p className="cmp-sub">
          Every plan runs on the same BuildFlow &mdash; you&rsquo;re only ever adding capability. Here&rsquo;s exactly
          what changes at each tier, and which one most teams should pick.
        </p>
        <div className="cmp-toggle-wrap">
          <BillingToggle value={period} onChange={setPeriod} />
        </div>
        <p className="cmp-starting">
          Simple per-user pricing &mdash; plans start at <strong>{startingDisplay}</strong>/user/mo{period === "yearly" ? ", billed yearly" : ""}. No setup fees &middot; 14-day free trial.
        </p>
        <div className="cmp-hero-cta">
          <span>Want a walkthrough with your own schedule?</span>
          <WxMagnetic className="wx-btn wx-btn-line cmp-demo-btn" onClick={onContactSales} ariaLabel="Book a demo">
            <CalendarDays size={17} /> Book a demo
          </WxMagnetic>
        </div>
        <p className="cmp-seats-hint">Set your team size on any plan below to see its total.</p>
      </section>

      {checkoutNotice && (
        <div
          role="status"
          className="cmp-checkout-notice"
          style={{
            margin: "0 auto clamp(14px, 2.5vh, 26px)",
            maxWidth: 720,
            display: "flex",
            gap: 10,
            alignItems: "flex-start",
            padding: "13px 16px",
            borderRadius: 12,
            border: "1px solid var(--wx-line-soft)",
            background: "var(--wx-card)",
            color: "var(--wx-ink)",
            fontSize: 14,
            lineHeight: 1.55
          }}
        >
          <span aria-hidden="true">{checkoutNotice.tone === "success" ? "✅" : checkoutNotice.tone === "error" ? "⚠️" : "ℹ️"}</span>
          <span>{checkoutNotice.message}</span>
        </div>
      )}

      {/* Plan cards */}
      <section className="cmp-cards" aria-label="Plans">
        {productPlans.map((plan, index) => {
          const Icon = plan.icon;
          const price = planTotalLabel(plan);
          return (
            <div className="cmp-card-reveal" data-reveal style={{ "--i": index } as CSSProperties} key={plan.id}>
              <WxTilt className="cmp-card-tilt" max={4} restRx={0} restRy={0}>
                <article className={`cmp-card tone-${plan.tone}${plan.recommended ? " rec" : ""}`}>
                  <div className="cmp-card-top">
                    <span className="cmp-ic"><Icon size={20} /></span>
                    <span className="cmp-name">{plan.name}</span>
                    {plan.recommended && <span className="cmp-rec-badge">Recommended</span>}
                  </div>
                  <p className="cmp-detail">{plan.detail}</p>
                  <div className="cmp-price">{price.big}{price.suffix && <span className="cmp-price-suffix">{price.suffix}</span>}</div>
                  <p className="cmp-price-note">{price.note}</p>
                  {price.save && <span className="cmp-save">{price.save}</span>}
                  <div className="cmp-card-seats">
                    <div className="cmp-card-seats-head">
                      <span className="cmp-card-seats-label">Team size</span>
                      <span className="cmp-card-seats-val"><strong>{seats[plan.id]}</strong> {seats[plan.id] === 1 ? "person" : "people"}</span>
                    </div>
                    <input
                      className="cmp-seats-range"
                      type="range"
                      min={SEAT_MIN}
                      max={SEAT_MAX}
                      step={1}
                      value={seats[plan.id]}
                      onChange={(event) => setSeatFor(plan.id, Number(event.target.value))}
                      style={{ "--pct": `${((seats[plan.id] - SEAT_MIN) / (SEAT_MAX - SEAT_MIN)) * 100}%` } as CSSProperties}
                      aria-label={`Team size for the ${plan.name} plan`}
                    />
                  </div>
                  <div className="cmp-bestfor"><b>Best for:</b> {bestFor[plan.id]}</div>
                  <ul className="cmp-card-feats">
                    {cardFeats[plan.id].map((feat, j) => {
                      const isHead = feat.endsWith(":");
                      return (
                        <li key={j} style={isHead ? { color: "var(--wx-faint)", fontWeight: 600 } : undefined}>
                          {!isHead && <Check size={14} strokeWidth={3} />} {feat}
                        </li>
                      );
                    })}
                  </ul>
                  <WxMagnetic
                    className={`wx-btn ${plan.recommended ? "wx-btn-ink" : "wx-btn-line"}`}
                    onClick={() => { void handlePlanCta(plan); }}
                    ariaLabel={plan.id === "enterprise" ? "Contact sales" : plan.cta}
                  >
                    {checkoutBusyPlan === plan.id ? "Starting checkout…" : plan.id === "enterprise" ? "Contact sales" : plan.cta}
                  </WxMagnetic>
                </article>
              </WxTilt>
            </div>
          );
        })}
      </section>

      {/* Full comparison table */}
      <section className="cmp-compare" data-reveal>
        <div className="cmp-compare-head">
          <span className="wx-eyebrow-2">Every feature, side by side</span>
          <h2>What changes as you scale.</h2>
          <p>The same production board, with more coordination unlocked at each tier. The recommended plan is highlighted.</p>
        </div>
        <div className="cmp-table-scroll">
          <div className="cmp-table">
            <div className="cmp-th">Compare features</div>
            {productPlans.map((plan) => (
              <div className={`cmp-th${plan.recommended ? " rec" : ""}`} key={plan.id}>
                {plan.name}
                <span className="cmp-th-sub">
                  {planTotalLabel(plan).big}
                  {planTotalLabel(plan).suffix ?? ""}
                </span>
              </div>
            ))}
            {compareGroups.map((group) => (
              <Fragment key={group.group}>
                <div className="cmp-group">{group.group}</div>
                {group.rows.map((row) => (
                  <div className="cmp-row" key={row.label}>
                    <div className="cmp-cell label">{row.label}</div>
                    {row.values.map((value, k) => (
                      <div className={`cmp-cell${productPlans[k].recommended ? " rec" : ""}`} key={k}>
                        {renderValue(value)}
                      </div>
                    ))}
                  </div>
                ))}
              </Fragment>
            ))}
          </div>
        </div>
      </section>

      {/* Which plan / why upgrade */}
      <section className="cmp-why" data-reveal>
        <div className="cmp-why-head">
          <span className="wx-eyebrow-2">Which plan is right?</span>
          <h2>Start free, grow into the tier that fits.</h2>
          <p>
            You&rsquo;re only ever adding capability. Most teams begin on <strong>Pro</strong> for daily planning and
            step up to <strong>Business</strong> once several projects need to be coordinated at once &mdash; which is
            why Business is the one we recommend for a growing field operation.
          </p>
        </div>
        <div className="cmp-steps">
          {steps.map((step, index) => {
            const plan = planById[step.id];
            return (
              <article className={`cmp-step${plan.recommended ? " rec" : ""}`} data-reveal style={{ "--i": index } as CSSProperties} key={step.id}>
                <div className="cmp-step-name"><span className={`cmp-dot tone-${plan.tone}`} /> {plan.name}</div>
                <div className="cmp-step-pick">{step.pick}</div>
                <p>{step.text}</p>
                <p className="cmp-unlock"><b>{step.unlock}</b></p>
              </article>
            );
          })}
        </div>
      </section>

      {/* CTA */}
      <section className="cs-cta cs-cta-globe" data-reveal>
        <div className="cs-cta-field" aria-hidden="true" />
        <div className="cs-cta-copy">
          <span className="wx-eyebrow"><span className="wx-dot" /> Get started</span>
          <h2>Start free — upgrade only when you outgrow it.</h2>
          <p>Every plan opens the same BuildFlow demo workspace. Try the whole production board free, then pick the tier that matches how your team runs the field.</p>
          <div className="cs-cta-actions">
            <WxMagnetic className="wx-btn wx-btn-paper" onClick={onGetStarted} ariaLabel="Start free">
              Start free <ArrowRight size={17} />
            </WxMagnetic>
            <WxMagnetic className="wx-btn wx-btn-ghostline" onClick={onBack} ariaLabel="Back to home">
              Back to home
            </WxMagnetic>
          </div>
        </div>
        <div className="cs-cta-globe-stage" aria-hidden="true">
          <GlobePulse className="cs-cta-globe-el" markers={ctaGlobeMarkers} />
        </div>
      </section>

      {/* Footer */}
      <footer className="wx-footer">
        <div className="wx-footer-top">
          <p className="wx-footer-tagline">Keep crews, materials, and schedules moving together.</p>
          <nav className="wx-footer-links" aria-label="Footer">
            <div>
              <h3>Plans</h3>
              <a href="#free-plan">Free</a>
              <a href="#pro-plan">Pro</a>
              <a href="#business-plan">Business</a>
              <a href="#enterprise-plan">Enterprise</a>
            </div>
            <div>
              <h3>Resources</h3>
              <a href="#updates">Updates</a>
              <a href="#help-center">Help center</a>
              <a href="#templates">Templates</a>
              <a href="#partners">Partner programs</a>
              <a href="#integrations">Integrations</a>
            </div>
            <div>
              <h3>Company</h3>
              <a href="#about">About us</a>
              <a href="#customers">Customers</a>
              <a href="#careers">Careers</a>
              <a href="#contact-sales">Contact sales</a>
            </div>
          </nav>
        </div>

        <div className="wx-footer-word" aria-hidden="true">
          {"BuildFlow".split("").map((letter, index) => (
            <span key={index} style={{ "--i": index } as CSSProperties}>
              {letter}
            </span>
          ))}
        </div>

        <div className="wx-footer-legal">
          <div className="wx-footer-brand">
            <BuildFlowLogoMark />
            <strong>BuildFlow</strong>
          </div>
          <div className="wx-footer-legal-links">
            <a onClick={onBack} role="button" tabIndex={0}>Back to home</a>
            <a href="#privacy">Privacy</a>
            <a href="#terms">Terms</a>
            <a href="#security">Security</a>
          </div>
        </div>
      </footer>
    </main>
  );
}

function WelcomeSolutionPage({
  solution,
  data,
  onBack,
  onOpenDashboard,
  onOpenPage
}: {
  solution: SolutionPageConfig;
  data?: BootstrapPayload;
  onBack: () => void;
  onOpenDashboard: () => void;
  onOpenPage: (page: Page) => void;
}) {
  const metricLines = solution.metricLines(data);
  const DocumentIcon = solution.documentIcon;
  const MiniDocIcon = solution.miniDocIcon;
  const htmlId = solution.hash.slice(1);

  return (
    <main className="solution-schedule-page" id={htmlId}>
      <section className="solution-schedule-hero" aria-labelledby={`${htmlId}-title`}>
        <div className="solution-schedule-breadcrumb">
          <span>BuildFlow</span>
          <ArrowRight size={14} />
          <span>Solutions</span>
        </div>
        <h1 id={`${htmlId}-title`}>{solution.title}</h1>
        <p>{solution.heroCopy}</p>
        <div className="solution-schedule-actions">
          <button type="button" className="welcome-blue-button" onClick={() => onOpenPage(solution.page)}>
            {solution.primaryCta} <ArrowRight size={17} />
          </button>
          <button type="button" className="welcome-soft-button" onClick={onOpenDashboard}>
            Get BuildFlow
          </button>
        </div>

        <div className="solution-schedule-hero-art" aria-hidden="true">
          <span className="solution-spark first"><Sparkles size={24} /></span>
          <span className="solution-spark second"><Route size={24} /></span>
          <div className="solution-schedule-browser">
            <div className="solution-browser-bar">
              <span />
              <span />
              <span />
              <strong>{solution.browserTitle}</strong>
              <em>Share</em>
            </div>
            <div className="solution-schedule-board">
              <aside>
                <BuildFlowLogoMark />
                <strong>{metricLines[0]}</strong>
                <span>{metricLines[1]}</span>
                <span>{metricLines[2]}</span>
              </aside>
              <section>
                <header>
                  <span>{solution.boardDate}</span>
                  <strong>{solution.boardHeading}</strong>
                </header>
                <div className="solution-week-grid">
                  {solution.boardRows.map((row) => (
                    <article key={`${solution.id}-${row.label}-${row.title}`} className={row.tone}>
                      <span>{row.label}</span>
                      <strong>{row.title}</strong>
                      <em>{row.detail}</em>
                    </article>
                  ))}
                </div>
              </section>
            </div>
          </div>
          <div className="solution-schedule-phone">
            <span />
            <strong>{solution.phoneTitle}</strong>
            {solution.phoneItems.map((item) => (
              <p key={item}>{item}</p>
            ))}
          </div>
        </div>
      </section>

      <section className="solution-logo-row" aria-label={`Teams using BuildFlow ${solution.title}`}>
        <span>{solution.logoRowLabel}</span>
        <strong>Riverside</strong>
        <strong>Harborview</strong>
        <strong>Pinecrest</strong>
        <strong>Tech Ridge</strong>
        <strong>Logistics Group</strong>
      </section>

      <section className="solution-schedule-showcase" aria-labelledby={`${htmlId}-showcase-title`}>
        <div className="solution-schedule-copy">
          <span>Key features</span>
          <h2 id={`${htmlId}-showcase-title`}>{solution.showcaseTitle}</h2>
        </div>
        <div className="solution-schedule-document" aria-hidden="true">
          <div className="solution-document-toolbar">
            <span />
            <span />
            <span />
            <strong>BuildFlow {solution.title}</strong>
          </div>
          <div className="solution-document-content">
            <span className="solution-document-icon"><DocumentIcon size={28} /></span>
            <h3>{solution.documentTitle}</h3>
            <div className="solution-document-columns">
              {solution.featureColumns.map((column) => (
                <div key={`${solution.id}-${column.heading}`}>
                  <h4>{column.heading}</h4>
                  {column.items.map((item) => {
                    const FeatureIcon = item.icon;
                    return (
                      <p key={`${column.heading}-${item.label}`}>
                        <FeatureIcon size={15} />
                        {item.label}
                      </p>
                    );
                  })}
                </div>
              ))}
            </div>
          </div>
        </div>
      </section>

      <section className="solution-schedule-quote" aria-labelledby={`${htmlId}-quote-title`}>
        <div className="solution-mini-doc" aria-hidden="true">
          <span><MiniDocIcon size={20} /></span>
          <h3>{solution.miniDocTitle}</h3>
          {solution.miniDocNotes.map((note) => (
            <p key={`${note.name}-${note.text}`}>
              <strong>{note.name}</strong> {note.text}
            </p>
          ))}
        </div>
        <blockquote>
          <h2 id={`${htmlId}-quote-title`}>{solution.quoteTitle}</h2>
          <p>{solution.quoteCopy}</p>
          <cite>{solution.quoteCite}</cite>
        </blockquote>
      </section>

      <section className="solution-schedule-migration" aria-labelledby={`${htmlId}-migration-title`}>
        <div>
          <span>{solution.migrationKicker}</span>
          <h2 id={`${htmlId}-migration-title`}>{solution.migrationTitle}</h2>
          <p>{solution.migrationCopy}</p>
          <button type="button" className="welcome-blue-button" onClick={() => onOpenPage(solution.page)}>
            {solution.primaryCta} <ArrowRight size={17} />
          </button>
        </div>
        <div className="solution-import-panel" aria-hidden="true">
          <header>
            <strong>Import</strong>
            <span>{solution.importStatus}</span>
          </header>
          {solution.importItems.map((item) => {
            const ImportIcon = item.icon;
            return (
              <span key={item.label}>
                <ImportIcon size={17} />
                {item.label}
              </span>
            );
          })}
        </div>
      </section>

      <section className="solution-schedule-final" aria-labelledby={`${htmlId}-final-title`}>
        <div>
          <h2 id={`${htmlId}-final-title`}>{solution.finalTitle}</h2>
          <p>{solution.finalCopy}</p>
        </div>
        <button type="button" className="welcome-soft-button" onClick={onBack}>
          Back to home
        </button>
      </section>
    </main>
  );
}

