function SavingsCalculator({
  ariaLabel,
  defaultTeamSize
}: {
  ariaLabel: string;
  defaultTeamSize: number;
}) {
  const [teamSize, setTeamSize] = useState(defaultTeamSize);
  const [selectedSavingsToolIds, setSelectedSavingsToolIds] = useState<BusinessSizeSavingsToolId[]>(() =>
    businessSizeSavingsTools.map((tool) => tool.id)
  );
  const safeTeamSize = Math.min(500, Math.max(1, teamSize || 1));
  const selectedMonthlySavingsPerUser = businessSizeSavingsTools.reduce(
    (total, tool) => total + (selectedSavingsToolIds.includes(tool.id) ? tool.monthlySavingsPerUser : 0),
    0
  );
  const monthlySavings = safeTeamSize * selectedMonthlySavingsPerUser;
  const annualSavings = monthlySavings * 12;
  const toggleSavingsTool = (toolId: BusinessSizeSavingsToolId) => {
    setSelectedSavingsToolIds((current) =>
      current.includes(toolId) ? current.filter((id) => id !== toolId) : [...current, toolId]
    );
  };

  useEffect(() => {
    setTeamSize(defaultTeamSize);
  }, [defaultTeamSize]);

  return (
    <div className="startup-calculator" aria-label={ariaLabel}>
      <fieldset>
        <legend>Too many tools? Calculate potential savings here.</legend>
        {businessSizeSavingsTools.map((tool) => {
          const isSelected = selectedSavingsToolIds.includes(tool.id);
          const monthlyValue = tool.monthlySavingsPerUser.toLocaleString("en-US", {
            style: "currency",
            currency: "USD",
            maximumFractionDigits: 0
          });
          return (
            <label
              key={tool.id}
              className={`startup-calculator-option${isSelected ? " selected" : ""}`}
            >
              <input
                type="checkbox"
                checked={isSelected}
                onChange={() => toggleSavingsTool(tool.id)}
              />
              <span>{tool.label}</span>
              <em>{monthlyValue}/user</em>
            </label>
          );
        })}
      </fieldset>
      <div className="startup-calculator-results">
        <label>
          Team size
          <input
            min="1"
            max="500"
            type="number"
            value={teamSize}
            onChange={(event) => setTeamSize(Number(event.target.value))}
          />
        </label>
        <strong>
          {monthlySavings.toLocaleString("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 })}
          <span>Monthly savings</span>
        </strong>
        <strong>
          {annualSavings.toLocaleString("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 })}
          <span>Annual savings</span>
        </strong>
      </div>
    </div>
  );
}

