function PlanCard({
  plan,
  featured = false,
  featureLimit,
  actionLabel,
  onSelect,
  period = "monthly"
}: {
  plan: ProductPlan;
  featured?: boolean;
  featureLimit?: number;
  actionLabel: string;
  onSelect?: () => void;
  period?: BillingPeriod;
}) {
  const Icon = plan.icon;
  const visibleFeatures = typeof featureLimit === "number" ? plan.features.slice(0, featureLimit) : plan.features;
  const pricing = planPricing(plan, period);

  return (
    <article className={`plan-card ${featured ? "featured" : ""} ${plan.recommended ? "recommended" : ""}`}>
      <div className="plan-card-heading">
        <span className={`product-menu-icon ${plan.tone}`}>
          <Icon size={22} />
        </span>
        <div>
          <h2>{plan.name}</h2>
          <p>{plan.detail}</p>
        </div>
        {plan.recommended && <em>Recommended</em>}
      </div>
      <div className="plan-card-price">
        <strong><AnimatedPlanPrice plan={plan} period={period} /></strong>
        <span>{pricing.note}</span>
        {pricing.save && <em className="plan-card-save">{pricing.save}</em>}
      </div>
      {onSelect ? (
        <button type="button" className={featured ? "welcome-blue-button" : "welcome-soft-button"} onClick={onSelect}>
          {actionLabel}
        </button>
      ) : (
        <span className="plan-card-static-action">{actionLabel}</span>
      )}
      <ul>
        {visibleFeatures.map((feature) => (
          <li key={feature}>
            <CheckCircle2 size={16} />
            {feature}
          </li>
        ))}
      </ul>
    </article>
  );
}

