function UpdateEntryCard({
  entry,
  onOpenSchedule
}: {
  entry: UpdateEntryData;
  onOpenSchedule: () => void;
}) {
  const [openSections, setOpenSections] = useState<Set<number>>(() => new Set());
  const toggleSection = (index: number) =>
    setOpenSections((prev) => {
      const next = new Set(prev);
      if (next.has(index)) next.delete(index);
      else next.add(index);
      return next;
    });
  return (
    <article className="updates-entry" id={`update-${entry.dateTime}`} data-reveal>
      <UpdateEntryMeta
        dateTime={entry.dateTime}
        dateLabel={entry.dateLabel}
        version={entry.version}
        creator={entry.creator}
        position={entry.position}
      />
      <div className="updates-story">
        <h2>{entry.title}</h2>
        <p className="updates-desc">{entry.description}</p>
        {entry.quote && (
          <blockquote>
            {entry.quote.text}
            {entry.quote.cite && <cite>{entry.quote.cite}</cite>}
          </blockquote>
        )}
        <div className="updates-sections">
          {entry.sections.map((section, index) => {
            const isOpen = openSections.has(index);
            const count = section.items.length;
            const isEmpty = count === 0;
            return (
              <div
                className={`updates-section${isOpen ? " open" : ""}${isEmpty ? " empty" : ""}`}
                key={section.label}
              >
                <button
                  type="button"
                  className="updates-section-head"
                  aria-expanded={isOpen}
                  disabled={isEmpty}
                  onClick={() => !isEmpty && toggleSection(index)}
                >
                  <span className="updates-section-title">
                    {section.label} <em>{count}</em>
                  </span>
                  <ChevronDown size={18} className="updates-section-chevron" aria-hidden="true" />
                </button>
                <div className="updates-section-body">
                  <ul>
                    {section.items.map((item) => (
                      <li key={item}>{item}</li>
                    ))}
                  </ul>
                </div>
              </div>
            );
          })}
        </div>
        <button className="updates-inline-action" onClick={onOpenSchedule}>
          See it in the schedule <ArrowRight size={15} />
        </button>
      </div>
    </article>
  );
}

function WelcomeUpdatesPage({
  onBack,
  onOpenSchedule,
  initialAnchor
}: {
  onBack: () => void;
  onOpenSchedule: () => void;
  initialAnchor?: string | null;
}) {
  const rootRef = useRef<HTMLElement>(null);
  const [year, setYear] = useState<number | null>(null);
  const [month, setMonth] = useState<number | null>(null);

  const years = useMemo(
    () => Array.from(new Set(UPDATE_ENTRIES.map((entry) => entry.year))).sort((a, b) => b - a),
    []
  );
  const months = useMemo(() => {
    const pool = UPDATE_ENTRIES.filter((entry) => year == null || entry.year === year);
    return Array.from(new Set(pool.map((entry) => entry.month))).sort((a, b) => b - a);
  }, [year]);

  const filtered = useMemo(
    () =>
      UPDATE_ENTRIES.filter(
        (entry) => (year == null || entry.year === year) && (month == null || entry.month === month)
      ),
    [year, month]
  );

  useEffect(() => {
    if (month != null && !months.includes(month)) setMonth(null);
  }, [months, month]);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const targets = root.querySelectorAll("[data-reveal]");
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add("in");
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.12, rootMargin: "0px 0px -6% 0px" }
    );
    targets.forEach((el) => observer.observe(el));
    return () => observer.disconnect();
  }, [filtered]);

  // Deep-link: when arriving from a specific "Read update" card, scroll that
  // entry into view and flash it. Guarded so a plain "View all"/#updates lands at the top.
  useEffect(() => {
    if (!initialAnchor) return;
    const el = document.getElementById(initialAnchor);
    if (!el) return;
    el.classList.add("in", "is-target");
    // The updates page keeps re-laying-out for up to ~1s after mount (a dev-only
    // StrictMode remount plus reveal/section settling shifts content above the
    // target by hundreds of px), which strands any single scroll. Re-pin the target
    // to the top with an instant jump every frame (smooth gets cancelled by the same
    // churn) until its layout position holds steady for a few frames, then stop.
    let cancelled = false;
    let lastTop: number | null = null;
    let stableFrames = 0;
    const deadline = performance.now() + 1500;
    const tick = () => {
      if (cancelled) return;
      const node = document.getElementById(initialAnchor);
      if (node) {
        node.scrollIntoView({ behavior: "auto", block: "start" });
        const top = node.offsetTop;
        stableFrames = top === lastTop ? stableFrames + 1 : 0;
        lastTop = top;
        if (stableFrames >= 3) return; // position held steady — settled
      }
      if (performance.now() < deadline) requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
    const flash = window.setTimeout(() => el.classList.remove("is-target"), 2800);
    return () => {
      cancelled = true;
      window.clearTimeout(flash);
    };
  }, [initialAnchor]);

  return (
    <main className="updates-page" id="updates" ref={rootRef}>
      <section className="updates-lede" aria-labelledby="updates-title">
        <div className="updates-lede-copy" data-reveal style={{ "--i": 0 } as CSSProperties}>
          <span>BuildFlow Updates</span>
          <h1 id="updates-title">What is new in production scheduling.</h1>
          <p>
            A running log of schedule, readiness, route, and field coordination improvements for teams that need the
            plan to stay close to the jobsite.
          </p>
        </div>
        <div className="updates-lede-actions" data-reveal style={{ "--i": 1 } as CSSProperties}>
          <button className="welcome-blue-button" onClick={onOpenSchedule}>
            Open schedule <ArrowRight size={17} />
          </button>
          <button className="welcome-soft-button" onClick={onBack}>
            Back to home
          </button>
        </div>
      </section>

      <section
        className="updates-filter"
        data-reveal
        style={{ "--i": 2 } as CSSProperties}
        aria-label="Filter updates by month and year"
      >
        <div className="updates-filter-group">
          <span className="updates-filter-label">Year</span>
          <div className="updates-filter-pills">
            <button
              type="button"
              className={`updates-pill${year == null ? " is-active" : ""}`}
              onClick={() => setYear(null)}
            >
              All
            </button>
            {years.map((value) => (
              <button
                type="button"
                key={value}
                className={`updates-pill${year === value ? " is-active" : ""}`}
                onClick={() => setYear(value)}
              >
                {value}
              </button>
            ))}
          </div>
        </div>
        <div className="updates-filter-group">
          <span className="updates-filter-label">Month</span>
          <div className="updates-filter-pills">
            <button
              type="button"
              className={`updates-pill${month == null ? " is-active" : ""}`}
              onClick={() => setMonth(null)}
            >
              All
            </button>
            {months.map((value) => (
              <button
                type="button"
                key={value}
                className={`updates-pill${month === value ? " is-active" : ""}`}
                onClick={() => setMonth(value)}
              >
                {UPDATE_MONTHS_SHORT[value]}
              </button>
            ))}
          </div>
        </div>
        <span className="updates-filter-count">
          {filtered.length} {filtered.length === 1 ? "update" : "updates"}
        </span>
      </section>

      <section className="updates-timeline" aria-label="BuildFlow product updates">
        {filtered.length === 0 ? (
          <p className="updates-empty" data-reveal>
            No updates match this filter yet.
          </p>
        ) : (
          filtered.map((entry) => (
            <UpdateEntryCard
              key={`${entry.version ?? "v"}-${entry.dateTime}`}
              entry={entry}
              onOpenSchedule={onOpenSchedule}
            />
          ))
        )}
      </section>
    </main>
  );
}

function UpdateEntryMeta({
  dateTime,
  dateLabel,
  version,
  creator = "Liam Santos",
  position = "CEO"
}: {
  dateTime: string;
  dateLabel: string;
  version?: string;
  creator?: string;
  position?: string;
}) {
  return (
    <aside className="updates-date">
      <div className="updates-date-row">
        <time dateTime={dateTime}>{dateLabel}</time>
        {version && <span>{version}</span>}
      </div>
      <div className="updates-author" aria-label={`Created by ${creator}, ${position}`}>
        <span>Created by</span>
        <strong>{creator}</strong>
        <em>{position}</em>
      </div>
    </aside>
  );
}

