function WelcomeCareersPage({
  onBack,
  onOpenSchedule,
  onApply
}: {
  onBack: () => void;
  onOpenSchedule: () => void;
  onApply: (role: CareerRole) => void;
}) {
  const rootRef = useRef<HTMLElement>(null);
  const [activeDept, setActiveDept] = useState<string>("All");

  const visibleRoles = useMemo(
    () => careerRoles.filter((role) => activeDept === "All" || role.dept === activeDept),
    [activeDept]
  );

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const targets = root.querySelectorAll("[data-reveal]");
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add("in");
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.12, rootMargin: "0px 0px -6% 0px" }
    );
    targets.forEach((el) => observer.observe(el));
    return () => observer.disconnect();
  }, [visibleRoles]);

  const scrollToRoles = () => {
    if (typeof document === "undefined") return;
    const section = document.getElementById("open-roles");
    if (!section) return;
    try {
      section.scrollIntoView({ behavior: "smooth", block: "start" });
    } catch {
      section.scrollIntoView();
    }
  };

  return (
    <main className="careers-page" id="careers" ref={rootRef}>
      <section className="crs-hero" aria-labelledby="crs-hero-title" data-reveal>
        <div className="crs-hero-copy">
          <span className="careers-eyebrow">Careers</span>
          <h1 id="crs-hero-title">Come build the tools that build the world.</h1>
          <p className="crs-hero-sub">
            We're a small, remote-first team helping construction crews plan the week, stay ready, and move
            together. Join us and ship work the field feels every single day.
          </p>
          <div className="crs-hero-actions">
            <button type="button" className="welcome-blue-button" onClick={scrollToRoles}>
              View open roles <ArrowRight size={17} />
            </button>
            <button type="button" className="crs-explore" onClick={onOpenSchedule}>
              See the product <ArrowRight size={16} />
            </button>
          </div>
        </div>
        <div className="crs-hero-panel" aria-hidden="true">
          <span className="crs-panel-glow" />
          {careerHeroCards.map((card, index) => (
            <span
              key={card.role}
              className={`crs-float-card tone-${card.tone}`}
              style={{ "--i": index, "--dur": `${6 + (index % 3)}s` } as CSSProperties}
            >
              <span className="crs-float-dot" />
              <span className="crs-float-role">{card.role}</span>
              <span className="crs-float-dept">{card.dept}</span>
            </span>
          ))}
        </div>
      </section>

      <section className="crs-values" aria-labelledby="crs-values-title" data-reveal>
        <div className="crs-section-head">
          <span className="careers-eyebrow">Why you'll love it here</span>
          <h2 id="crs-values-title">Work that reaches the jobsite.</h2>
        </div>
        <div className="crs-values-grid">
          {careerValues.map((value, index) => {
            const ValueIcon = value.icon;
            return (
              <article className="crs-value" key={value.title} data-reveal style={{ "--i": index % 2 } as CSSProperties}>
                <span className="crs-value-ic"><ValueIcon size={20} /></span>
                <h3>{value.title}</h3>
                <p>{value.text}</p>
              </article>
            );
          })}
        </div>
      </section>

      <section className="crs-roles" id="open-roles" aria-labelledby="crs-roles-title" data-reveal>
        <div className="crs-roles-head">
          <div className="crs-section-head crs-section-head-flush">
            <span className="careers-eyebrow">Open roles</span>
            <h2 id="crs-roles-title">Find your seat.</h2>
          </div>
          <div className="crs-tabs" role="tablist" aria-label="Filter roles by team">
            {careerDepartments.map((dept) => (
              <button
                key={dept}
                type="button"
                role="tab"
                aria-selected={activeDept === dept}
                className={`crs-tab${activeDept === dept ? " is-active" : ""}`}
                onClick={() => setActiveDept(dept)}
              >
                {dept}
              </button>
            ))}
          </div>
        </div>
        <div className="crs-role-list">
          {visibleRoles.map((role, index) => (
            <button
              type="button"
              className="crs-role"
              key={`${role.dept}-${role.title}`}
              data-reveal
              style={{ "--i": index % 6 } as CSSProperties}
              onClick={() => onApply(role)}
            >
              <span className="crs-role-main">
                <strong>{role.title}</strong>
                <span className="crs-role-meta">
                  <span className="crs-role-dept">{role.dept}</span>
                  <span><MapPin size={13} /> {role.location}</span>
                  <span>{role.type}</span>
                </span>
              </span>
              <span className="crs-role-apply">Apply <ArrowRight size={16} /></span>
            </button>
          ))}
        </div>
      </section>

      <section className="crs-benefits" aria-labelledby="crs-benefits-title" data-reveal>
        <div className="crs-section-head">
          <span className="careers-eyebrow">Benefits</span>
          <h2 id="crs-benefits-title">Taken care of, so you can build.</h2>
        </div>
        <div className="crs-benefits-grid">
          {careerBenefits.map((benefit, index) => {
            const BenefitIcon = benefit.icon;
            return (
              <div className="crs-benefit" key={benefit.title} data-reveal style={{ "--i": index % 3 } as CSSProperties}>
                <span className="crs-benefit-ic"><BenefitIcon size={18} /></span>
                {benefit.title}
              </div>
            );
          })}
        </div>
      </section>

      <section className="crs-stats" aria-label="Life at BuildFlow by the numbers" data-reveal>
        {careerStats.map((stat, index) => {
          const StatIcon = stat.icon;
          return (
            <div className="crs-stat" key={stat.label} data-reveal style={{ "--i": index } as CSSProperties}>
              <span className="crs-stat-ic"><StatIcon size={18} /></span>
              <strong className="crs-stat-value">{stat.value}</strong>
              <span className="crs-stat-label">{stat.label}</span>
            </div>
          );
        })}
      </section>

      <section className="crs-cta" aria-labelledby="crs-cta-title" data-reveal>
        <span className="careers-eyebrow">Get started</span>
        <h2 id="crs-cta-title">Don't see your role? We still want to meet you.</h2>
        <div className="crs-cta-actions">
          <button type="button" className="welcome-blue-button" onClick={onOpenSchedule}>
            Get in touch <ArrowRight size={17} />
          </button>
          <button type="button" className="welcome-soft-button" onClick={onBack}>
            Back to home
          </button>
        </div>
      </section>

      <footer className="wx-footer">
        <div className="wx-footer-top">
          <p className="wx-footer-tagline">Keep crews, materials, and schedules moving together.</p>
          <nav className="wx-footer-links" aria-label="Footer">
            <div>
              <h3>Product</h3>
              <a href="#overview">Dashboard</a>
              <a href="#crew-scheduling">Schedule</a>
              <a href="#overview">Projects</a>
              <a href="#map-field-ops">Map Ops</a>
              <a href="#production-reports">Reports</a>
            </div>
            <div>
              <h3>Resources</h3>
              <a href="#updates">Updates</a>
              <a href="#help-center">Help center</a>
              <a href="#templates">Templates</a>
              <a href="#partners">Partner programs</a>
              <a href="#integrations">Integrations</a>
            </div>
            <div>
              <h3>Company</h3>
              <a href="#about">About us</a>
              <a href="#customers">Customers</a>
              <a href="#careers">Careers</a>
              <a href="#contact-sales">Contact sales</a>
            </div>
          </nav>
        </div>

        <div className="wx-footer-word" aria-hidden="true">
          {"BuildFlow".split("").map((letter, index) => (
            <span key={index} style={{ "--i": index } as CSSProperties}>
              {letter}
            </span>
          ))}
        </div>

        <div className="wx-footer-legal">
          <div className="wx-footer-brand">
            <BuildFlowLogoMark />
            <strong>BuildFlow</strong>
          </div>
          <div className="wx-footer-legal-links">
            <a href="#about">About BuildFlow</a>
            <a href="#privacy">Privacy</a>
            <a href="#terms">Terms</a>
            <a href="#security">Security</a>
          </div>
        </div>
      </footer>
    </main>
  );
}

function WelcomeApplicationPage({
  role,
  onBack,
  onOpenSchedule
}: {
  role: CareerRole | null;
  onBack: () => void;
  onOpenSchedule: () => void;
}) {
  const rootRef = useRef<HTMLElement>(null);
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [location, setLocation] = useState("");
  const [roleTitle, setRoleTitle] = useState(role?.title ?? "General interest");
  const [link, setLink] = useState("");
  const [resumeName, setResumeName] = useState("");
  const [why, setWhy] = useState("");
  const [errors, setErrors] = useState<{ firstName?: string; email?: string }>({});
  const [submitted, setSubmitted] = useState(false);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const targets = root.querySelectorAll("[data-reveal]");
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add("in");
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.12, rootMargin: "0px 0px -6% 0px" }
    );
    targets.forEach((el) => observer.observe(el));
    return () => observer.disconnect();
  }, [submitted]);

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const next: { firstName?: string; email?: string } = {};
    if (!firstName.trim()) next.firstName = "Enter your first name.";
    if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email.trim())) next.email = "Enter a valid email address.";
    setErrors(next);
    if (Object.keys(next).length > 0) return;
    setSubmitted(true);
    if (typeof window !== "undefined") {
      try {
        window.scrollTo({ top: 0, behavior: "smooth" });
      } catch {
        // Ignore environments without smooth scroll.
      }
    }
  };

  const applyingFor = role?.title ?? roleTitle;

  return (
    <main className="careers-apply-page" id="apply" ref={rootRef}>
      <button type="button" className="apply-back" onClick={onBack}>
        <ChevronLeft size={16} /> Back to open roles
      </button>

      <header className="apply-head" data-reveal>
        <span className="careers-eyebrow">{role ? `Careers · ${role.dept}` : "Careers"}</span>
        <h1>{role ? `Apply: ${role.title}` : "Apply to BuildFlow"}</h1>
        <p>Tell us a bit about you. It takes about three minutes — no account required.</p>
      </header>

      {submitted ? (
        <section className="apply-success" data-reveal aria-live="polite">
          <span className="apply-success-ic"><CheckCircle2 size={30} /></span>
          <h2>Application received.</h2>
          <p>
            Thanks, {firstName || "there"} — your application for <strong>{applyingFor}</strong> is in. Our team
            reviews every submission and will reach out by email if there's a fit.
          </p>
          <div className="apply-success-actions">
            <button type="button" className="welcome-blue-button" onClick={onBack}>
              Back to open roles
            </button>
            <button type="button" className="welcome-soft-button" onClick={onOpenSchedule}>
              Explore the product
            </button>
          </div>
        </section>
      ) : (
        <div className="apply-layout">
          <aside className="apply-summary" data-reveal>
            <span className="apply-summary-label">You're applying for</span>
            <h2>{role ? role.title : "General application"}</h2>
            {role ? (
              <ul className="apply-summary-meta">
                <li><Building2 size={15} /> {role.dept}</li>
                <li><MapPin size={15} /> {role.location}</li>
                <li><Clock size={15} /> {role.type}</li>
              </ul>
            ) : (
              <p className="apply-summary-note">
                Not sure which role fits? Send a general application and tell us what you'd love to work on.
              </p>
            )}
            <div className="apply-summary-perks">
              <p><CheckCircle2 size={15} /> Remote-first, flexible hours</p>
              <p><CheckCircle2 size={15} /> Meaningful equity</p>
              <p><CheckCircle2 size={15} /> Ship to real jobsites</p>
            </div>
          </aside>

          <form className="apply-form" data-reveal style={{ "--i": 1 } as CSSProperties} onSubmit={submit} noValidate>
            <div className="apply-row">
              <div className="apply-field">
                <label htmlFor="apply-first">First name</label>
                <input
                  id="apply-first"
                  value={firstName}
                  onChange={(event) => {
                    setFirstName(event.target.value);
                    if (errors.firstName) setErrors((prev) => ({ ...prev, firstName: undefined }));
                  }}
                  className={errors.firstName ? "has-error" : ""}
                  placeholder="Jordan"
                  aria-invalid={Boolean(errors.firstName)}
                />
                {errors.firstName && <span className="apply-error">{errors.firstName}</span>}
              </div>
              <div className="apply-field">
                <label htmlFor="apply-last">Last name</label>
                <input id="apply-last" value={lastName} onChange={(event) => setLastName(event.target.value)} placeholder="Alvarez" />
              </div>
            </div>

            <div className="apply-row">
              <div className="apply-field">
                <label htmlFor="apply-email">Email</label>
                <input
                  id="apply-email"
                  type="email"
                  value={email}
                  onChange={(event) => {
                    setEmail(event.target.value);
                    if (errors.email) setErrors((prev) => ({ ...prev, email: undefined }));
                  }}
                  className={errors.email ? "has-error" : ""}
                  placeholder="you@email.com"
                  aria-invalid={Boolean(errors.email)}
                />
                {errors.email && <span className="apply-error">{errors.email}</span>}
              </div>
              <div className="apply-field">
                <label htmlFor="apply-phone">Phone <span>(optional)</span></label>
                <input id="apply-phone" type="tel" value={phone} onChange={(event) => setPhone(event.target.value)} placeholder="(555) 000-0000" />
              </div>
            </div>

            <div className="apply-row">
              <div className="apply-field">
                <label htmlFor="apply-location">Where are you based? <span>(optional)</span></label>
                <input id="apply-location" value={location} onChange={(event) => setLocation(event.target.value)} placeholder="City, State" />
              </div>
              <div className="apply-field">
                <label htmlFor="apply-role">Role</label>
                <select id="apply-role" value={roleTitle} onChange={(event) => setRoleTitle(event.target.value)}>
                  {careerRoles.map((careerRole) => (
                    <option key={careerRole.title} value={careerRole.title}>
                      {careerRole.title}
                    </option>
                  ))}
                  <option value="General interest">General interest</option>
                </select>
              </div>
            </div>

            <div className="apply-field">
              <label htmlFor="apply-link">LinkedIn or portfolio <span>(optional)</span></label>
              <input id="apply-link" type="url" value={link} onChange={(event) => setLink(event.target.value)} placeholder="https://" />
            </div>

            <div className="apply-field">
              <label>Resume <span>(optional)</span></label>
              <label className="apply-file">
                <input type="file" accept=".pdf,.doc,.docx" onChange={(event) => setResumeName(event.target.files?.[0]?.name ?? "")} />
                <span className="apply-file-btn"><Paperclip size={15} /> Attach file</span>
                <span className="apply-file-name">{resumeName || "PDF or Word, up to 10MB"}</span>
              </label>
            </div>

            <div className="apply-field">
              <label htmlFor="apply-why">Why BuildFlow? <span>(optional)</span></label>
              <textarea
                id="apply-why"
                rows={4}
                value={why}
                onChange={(event) => setWhy(event.target.value)}
                placeholder="Tell us what you'd love to build with us."
              />
            </div>

            <button type="submit" className="welcome-blue-button large apply-submit">
              Submit application <ArrowRight size={17} />
            </button>
            <p className="apply-fineprint">
              By applying you agree to our privacy policy. We'll only use your details to evaluate your application.
            </p>
          </form>
        </div>
      )}
    </main>
  );
}

