const aiFilmDurations = [2800, 4600, 4800, 3200, 4600, 2800];

function WelcomeAiFilm() {
  const sceneCount = aiFilmDurations.length;
  const [scene, setScene] = useState(0);
  const [paused, setPaused] = useState(false);

  useEffect(() => {
    if (paused || typeof window === "undefined") return;
    if (typeof navigator !== "undefined" && navigator.userAgent.toLowerCase().includes("jsdom")) return;
    const timer = window.setTimeout(() => setScene((s) => (s + 1) % sceneCount), aiFilmDurations[scene]);
    return () => window.clearTimeout(timer);
  }, [scene, paused, sceneCount]);

  return (
    <div
      className={`ai-film${scene === 3 ? " is-dark" : ""}`}
      data-scene={scene}
      role="img"
      aria-label="BuildFlow product tour: ask BuildFlow AI what's at risk, and watch the whole schedule respond."
      onMouseEnter={() => setPaused(true)}
      onMouseLeave={() => setPaused(false)}
    >
      <div className="ai-film-aurora" aria-hidden="true">
        <span className="af-blob b1" />
        <span className="af-blob b2" />
        <span className="af-blob b3" />
        <span className="af-blob b4" />
      </div>

      <div className="ai-film-stage" key={scene}>
        {scene === 0 && (
          <div className="af-scene af-title">
            <span className="af-kicker">BuildFlow AI · Product tour</span>
            <h3 className="af-hero-word">Ask BuildFlow</h3>
            <p className="af-sub">Your entire production plan, one question away.</p>
          </div>
        )}

        {scene === 1 && (
          <div className="af-scene af-stage-win">
            <div className="af-win af-win-tilt">
              <div className="af-win-chrome"><i /><i /><i /><em>BuildFlow HQ · Dashboard</em></div>
              <div className="af-win-inner">
                <aside className="af-win-side">
                  <div className="af-side-brand"><span className="af-side-dot" />BuildFlow</div>
                  <div className="af-side-jobs"><b>9</b> active jobs</div>
                  <nav>{afSideNav.map((n, i) => (<span className={i === 0 ? "on" : ""} key={n}>{n}</span>))}</nav>
                </aside>
                <div className="af-win-main">
                  <div className="af-win-head"><em>Command center</em><h4>Start with the field day</h4></div>
                  <div className="af-dash">
                    {afDashCols.map((c) => (
                      <div className={`af-dash-col tone-${c.tone}`} key={c.label}>
                        <div className="af-dash-col-head"><span>{c.label}</span><b>{c.n}</b></div>
                        {c.jobs.map((j) => (
                          <div className="af-dash-card" key={j.t}><strong>{j.t}</strong><span>{j.s}</span></div>
                        ))}
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
            <div className="af-ask-bar">
              <span className="af-ask-ic"><Sparkles size={16} /></span>
              <span className="af-typed">what&rsquo;s at risk tomorrow?</span>
              <span className="af-caret">&#9615;</span>
              <span className="af-ask-go"><ArrowRight size={15} /></span>
            </div>
          </div>
        )}

        {scene === 2 && (
          <div className="af-scene af-answer">
            <h3 className="af-answer-head">
              {"BuildFlow moved 3 jobs out of the storm".split(" ").map((w, i) => (
                <b style={{ "--i": i } as CSSProperties} key={i}>{w}&nbsp;</b>
              ))}
            </h3>
            <div className="af-answer-card">
              <div className="af-answer-top"><span className="af-answer-ic"><CloudSun size={15} /></span>Friday storms · rescheduled automatically</div>
              {afRisk.map((r, i) => (
                <div className="af-answer-row" style={{ "--i": i } as CSSProperties} key={r.job}>
                  <span className="af-answer-job"><strong>{r.job}</strong><em>{r.crew} · {r.when}</em></span>
                  <span className={`af-flag tone-${r.tone}`}>{r.risk}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        {scene === 3 && (
          <div className="af-scene af-dark">
            <div className="af-dark-eyebrow">One command center</div>
            <div className="af-pill big"><span className="af-pill-ic blue"><Grid2X2 size={18} /></span><b>9</b> active jobs</div>
            <div className="af-pill small p2"><span className="af-pill-ic teal"><PackageCheck size={14} /></span>5 / 7 ready</div>
            <div className="af-pill small p3"><span className="af-pill-ic amber"><AlertTriangle size={14} /></span>3 at risk</div>
            <div className="af-pill small p4"><span className="af-pill-ic purple"><Route size={14} /></span>routes optimized</div>
          </div>
        )}

        {scene === 4 && (
          <div className="af-scene af-stage-win">
            <div className="af-win af-win-tilt af-win-alt">
              <div className="af-win-chrome"><i /><i /><i /><em>BuildFlow HQ · Schedule</em></div>
              <div className="af-win-inner">
                <div className="af-win-main af-win-main-wide">
                  <div className="af-win-head"><em>Week board · Jun 15 – 21</em><h4>The whole week, one screen</h4></div>
                  <div className="af-board2">
                    <div className="af-board2-days"><span />{["Mon", "Tue", "Wed", "Thu", "Fri"].map((d) => (<span key={d}>{d}</span>))}</div>
                    {afBoardRows.map((row) => (
                      <div className={`af-board2-row tone-${row.tone}`} key={row.crew}>
                        <span className="af-board2-crew">{row.crew}</span>
                        {row.cells.map((c, i) => (
                          <span className="af-board2-cell" key={i}>{c ? <em>{c}</em> : null}</span>
                        ))}
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
            <div className="af-mod-strip">
              {afSideNav.map((n) => (<span key={n}>{n}</span>))}
            </div>
          </div>
        )}

        {scene === 5 && (
          <div className="af-scene af-outro">
            <BuildFlowLogoMark />
            <h3 className="af-hero-word small">Run the whole build with AI.</h3>
            <span className="af-outro-cta">Open live schedule <ArrowRight size={15} /></span>
          </div>
        )}
      </div>

      <div className="ai-film-dots" key={`dots-${scene}`} aria-hidden="true">
        {Array.from({ length: sceneCount }).map((_, i) => (
          <span className={`af-dot${i < scene ? " past" : ""}${i === scene ? " on" : ""}`} key={i}>
            <i style={{ "--dur": `${aiFilmDurations[i]}ms` } as CSSProperties} />
          </span>
        ))}
      </div>
    </div>
  );
}

function WelcomeDemoPlayer({ data }: { data?: BootstrapPayload }) {
  const [activeSceneIndex, setActiveSceneIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(true);
  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);
  const activeScene = welcomeDemoScenes[activeSceneIndex];

  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return;
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    setPrefersReducedMotion(media.matches);
    const handleChange = () => setPrefersReducedMotion(media.matches);
    media.addEventListener?.("change", handleChange);
    return () => media.removeEventListener?.("change", handleChange);
  }, []);

  useEffect(() => {
    if (!isPlaying || prefersReducedMotion) return;
    const timer = window.setInterval(() => {
      setActiveSceneIndex((current) => (current + 1) % welcomeDemoScenes.length);
    }, 3600);
    return () => window.clearInterval(timer);
  }, [isPlaying, prefersReducedMotion]);

  const showScene = (index: number) => {
    setActiveSceneIndex(index);
    setIsPlaying(false);
  };

  return (
    <section className="welcome-demo-player" id="dashboard-preview" aria-label="BuildFlow guided demo">
      <div className="welcome-browser-bar">
        <span />
        <span />
        <span />
        <strong>BuildFlow HQ</strong>
        <div className="welcome-browser-actions" aria-hidden="true">
          <span>Share</span>
          <Bell size={16} />
          <Sparkles size={16} />
        </div>
      </div>
      <div className={`welcome-demo-stage ${activeScene.id}`}>
        <aside className="welcome-demo-sidebar">
          <div className="demo-side-brand">
            <BuildFlowLogoMark />
            <strong>BuildFlow</strong>
          </div>
          <div className="demo-side-summary">
            <span>Today</span>
            <strong>{data?.jobs.length ?? 8}</strong>
            <em>active jobs</em>
          </div>
          <nav className="demo-side-nav" aria-label="Demo walkthrough">
            {welcomeDemoScenes.map((scene, index) => (
              <button
                key={scene.id}
                className={index === activeSceneIndex ? "active" : ""}
                onClick={() => showScene(index)}
                aria-label={`Open ${scene.label} demo`}
              >
                {index === 0 && <Grid2X2 size={16} />}
                {index === 1 && <CalendarDays size={16} />}
                {index === 2 && <PackageCheck size={16} />}
                {index === 3 && <ClipboardList size={16} />}
                {index === 4 && <MapPin size={16} />}
                {index === 5 && <LineChart size={16} />}
                {scene.label}
              </button>
            ))}
          </nav>
          <div className="demo-side-agents">
            <span>Field assistants</span>
            <p><Timer size={15} /> Dispatch watcher</p>
            <p><PackageCheck size={15} /> Readiness agent</p>
            <p><Route size={15} /> Route planner</p>
          </div>
        </aside>
        <div className="welcome-demo-screen">
          <div className="demo-app-heading">
            <div>
              <span className="welcome-demo-kicker">{activeScene.label}</span>
              <h2>{activeScene.title}</h2>
              <p>{activeScene.caption}</p>
            </div>
            <button>
              New <ChevronDown size={15} />
            </button>
          </div>
          <div className="demo-app-tabs" aria-hidden="true">
            <span className="active"><Grid2X2 size={15} /> Company tasks</span>
            <span><Users size={15} /> Crews</span>
            <span><Route size={15} /> Routes</span>
            <span><LineChart size={15} /> Timeline</span>
          </div>
          <WelcomeDemoScene key={activeScene.id} sceneId={activeScene.id} data={data} />
          <WelcomeDemoHelpers sceneId={activeScene.id} />
          <div className="welcome-demo-cursor" aria-hidden="true">
            <MousePointer2 size={22} />
          </div>
          <button
            className="welcome-demo-play"
            onClick={() => setIsPlaying((current) => !current)}
            aria-label={isPlaying ? "Pause demo" : "Play demo"}
          >
            <span>{isPlaying ? <PauseCircle size={22} /> : <PlayCircle size={22} />}</span>
            <strong>{isPlaying ? "Pause tour" : "Play tour"}</strong>
            <em>⌘0</em>
          </button>
        </div>
      </div>
      <div className="welcome-demo-controls" aria-label="Demo scenes">
        {welcomeDemoScenes.map((scene, index) => (
          <button
            key={scene.id}
            className={index === activeSceneIndex ? "active" : ""}
            onClick={() => showScene(index)}
            aria-label={`Show ${scene.label} demo`}
            aria-pressed={index === activeSceneIndex}
          >
            <span>{String(index + 1).padStart(2, "0")}</span>
            {scene.label}
          </button>
        ))}
      </div>
    </section>
  );
}

