function Sidebar({
  collapsed,
  onToggleCollapsed,
  page,
  selectedProductIds,
  setPage,
  onOpenSettings
}: {
  collapsed: boolean;
  onToggleCollapsed: () => void;
  page: Page;
  selectedProductIds: OnboardingProductId[];
  setPage: (page: Page) => void;
  onOpenSettings: () => void;
}) {
  const highlightedPages = new Set(selectedProductIds.flatMap(programPages));
  const navRef = useRef<HTMLElement>(null);
  const indicatorRef = useRef<HTMLSpanElement>(null);

  // Slide the "magic" active indicator to the current nav item.
  useEffect(() => {
    const indicator = indicatorRef.current;
    const nav = navRef.current;
    if (!indicator) return;
    const activeButton = collapsed || !nav ? null : nav.querySelector<HTMLElement>(".nav-item.active");
    if (!activeButton) {
      indicator.style.opacity = "0";
      return;
    }
    indicator.style.opacity = "1";
    indicator.style.height = `${activeButton.offsetHeight}px`;
    indicator.style.transform = `translateY(${activeButton.offsetTop}px)`;
  }, [page, collapsed]);

  return (
    <aside
      className={`sidebar sidebar-rx${collapsed ? " collapsed" : ""}`}
      aria-label={collapsed ? "Collapsed category sidebar" : "Category sidebar"}
    >
      <button
        type="button"
        className="sidebar-toggle"
        onClick={onToggleCollapsed}
        aria-label={collapsed ? "Show sidebar" : "Hide sidebar"}
        aria-expanded={!collapsed}
        title={collapsed ? "Show sidebar" : "Hide sidebar"}
      >
        {collapsed ? <ChevronRight size={18} /> : <ChevronLeft size={18} />}
      </button>
      <button className="brand" onClick={() => setPage("dashboard")}>
        <BuildFlowLogoMark />
        <span>
          <strong>BuildFlow</strong>
          <em>Schedule</em>
        </span>
      </button>
      <nav className="nav-list" ref={navRef}>
        <span className="nav-indicator" ref={indicatorRef} aria-hidden="true" />
        {navItems.map((item, index) => {
          const Icon = item.icon;
          return (
            <button
              key={item.page}
              style={{ "--nav-i": index } as CSSProperties}
              className={[
                "nav-item",
                page === item.page ? "active" : "",
                highlightedPages.has(item.page) ? "recommended" : ""
              ]
                .filter(Boolean)
                .join(" ")}
              data-tutorial-id={`nav-${item.page}`}
              onClick={() => setPage(item.page)}
            >
              <Icon size={21} />
              <span>{item.label}</span>
            </button>
          );
        })}
      </nav>
      <button
        type="button"
        className="sidebar-account"
        onClick={onOpenSettings}
        aria-label={`${accountDisplayName} account and settings`}
      >
        <span className="sidebar-account-avatar">{accountDisplayAvatar}</span>
        <span className="sidebar-account-meta">
          <strong>{accountDisplayName}</strong>
          <em>{accountDisplayRole}</em>
        </span>
        <ChevronDown size={18} />
      </button>
    </aside>
  );
}

type NotificationItem = {
  id: string;
  title: string;
  detail: string;
  timestamp: string;
  tone: "blue" | "green" | "amber" | "red" | "violet" | "slate";
  icon: typeof Grid2X2;
};

function buildNotificationItems(data: BootstrapPayload): NotificationItem[] {
  const items: NotificationItem[] = [];

  data.fieldUpdates.forEach((update) => {
    const user = data.users.find((item) => item.id === update.userId) ?? data.activeUser;
    items.push({
      id: `field-${update.id}`,
      title: "Field update posted",
      detail: `${user.name} updated ${projectName(data, update.projectId)}: ${update.message}`,
      timestamp: update.createdAt,
      tone: update.status === "DelayIQed" || update.status === "At Risk" ? "red" : "green",
      icon: ClipboardList
    });
  });

  data.weatherAlerts.forEach((alert) => {
    items.push({
      id: `weather-${alert.id}`,
      title: "Weather alert added",
      detail: `${alert.title} for ${alert.projectId ? projectName(data, alert.projectId) : "all projects"} - ${alert.details}`,
      timestamp: alert.startsAt,
      tone: alert.severity === "High" ? "red" : alert.severity === "Medium" ? "amber" : "blue",
      icon: CloudSun
    });
  });

  data.delayIQs.forEach((delayIQ) => {
    items.push({
      id: `delayIQ-${delayIQ.id}`,
      title: "DelayIQ being tracked",
      detail: `${delayIQ.title} is ${delayIQ.status.toLowerCase()} on ${projectName(data, delayIQ.projectId)} with ${delayIQ.impactDays} day impact.`,
      timestamp: delayIQ.reportedAt,
      tone: delayIQ.severity === "High" ? "red" : delayIQ.severity === "Medium" ? "amber" : "slate",
      icon: ShieldAlert
    });
  });

  data.assignments.forEach((assignment) => {
    const job = data.jobs.find((item) => item.id === assignment.jobId);
    const crew = data.crews.find((item) => item.id === assignment.crewId);
    items.push({
      id: `assignment-${assignment.id}`,
      title: "Schedule assignment updated",
      detail: `${crew?.name ?? "Crew"} is assigned to ${job?.name ?? "scheduled work"} with ${assignment.status.toLowerCase()} status.`,
      timestamp: assignment.date,
      tone: assignment.conflicts.length ? "red" : "blue",
      icon: CalendarDays
    });
  });

  data.inspections.forEach((inspection) => {
    items.push({
      id: `inspection-${inspection.id}`,
      title: "Inspection scheduled",
      detail: `${inspection.title} is ${inspection.status.toLowerCase()} for ${projectName(data, inspection.projectId)}.`,
      timestamp: inspection.scheduledAt,
      tone: inspection.status === "Complete" ? "green" : "violet",
      icon: CheckCircle2
    });
  });

  data.materials.forEach((material) => {
    items.push({
      id: `material-${material.id}`,
      title: "Material status updated",
      detail: `${material.name} is ${material.status.toLowerCase()} for ${projectName(data, material.projectId)}.`,
      timestamp: material.deliveryDate,
      tone: material.status === "Missing" ? "red" : material.status === "Ready" ? "green" : "amber",
      icon: PackageCheck
    });
  });

  data.equipment.forEach((equipment) => {
    const assignedProject = equipment.assignedTo ? projectName(data, equipment.assignedTo) : "the fleet";
    items.push({
      id: `equipment-${equipment.id}`,
      title: "Equipment status updated",
      detail: `${equipment.name} is ${equipment.status.toLowerCase()} for ${assignedProject}.`,
      timestamp: new Date().toISOString(),
      tone: equipment.status === "Maintenance" ? "red" : equipment.status === "In Use" ? "amber" : "green",
      icon: Wrench
    });
  });

  return items
    .sort((first, second) => new Date(second.timestamp).getTime() - new Date(first.timestamp).getTime())
    .slice(0, 7);
}

function TopBar({
  data,
  onOpenHud,
  onOpenSettings,
  onStartTutorial,
  onLogout,
  reportsMode = false
}: {
  data: BootstrapPayload;
  onOpenHud: () => void;
  onOpenSettings: () => void;
  onStartTutorial: () => void;
  onLogout: () => void;
  reportsMode?: boolean;
}) {
  const [isNotificationsOpen, setIsNotificationsOpen] = useState(false);
  const [isAccountMenuOpen, setIsAccountMenuOpen] = useState(false);
  const notificationItems = useMemo(() => buildNotificationItems(data), [data]);
  const notificationCount = notificationItems.length;
  const notificationPanelId = reportsMode ? "reports-notifications-panel" : "notifications-panel";
  const accountMenuId = reportsMode ? "reports-account-menu" : "account-menu";
  const notificationRef = useRef<HTMLDivElement | null>(null);
  const accountMenuRef = useRef<HTMLDivElement | null>(null);
  const topbarClassName = reportsMode ? "topbar reports-topbar" : "topbar";

  useEffect(() => {
    if (!isNotificationsOpen || typeof document === "undefined") return;

    const closeOnOutsideClick = (event: globalThis.MouseEvent) => {
      if (!notificationRef.current?.contains(event.target as Node)) {
        setIsNotificationsOpen(false);
      }
    };

    document.addEventListener("mousedown", closeOnOutsideClick);
    return () => document.removeEventListener("mousedown", closeOnOutsideClick);
  }, [isNotificationsOpen]);

  useEffect(() => {
    if (!isAccountMenuOpen || typeof document === "undefined") return;

    const closeOnOutsideClick = (event: globalThis.MouseEvent) => {
      if (!accountMenuRef.current?.contains(event.target as Node)) {
        setIsAccountMenuOpen(false);
      }
    };

    document.addEventListener("mousedown", closeOnOutsideClick);
    return () => document.removeEventListener("mousedown", closeOnOutsideClick);
  }, [isAccountMenuOpen]);

  return (
    <header className={topbarClassName}>
      <label className="search-box">
        <Search size={18} />
        <input placeholder="Search projects, tasks, crews, or anything..." />
        <kbd>⌘ K</kbd>
      </label>
      <div className="topbar-actions">
        <button
          className="icon-button topbar-hud-button"
          type="button"
          aria-label="Open HUD"
          title="Open HUD"
          onClick={() => {
            setIsNotificationsOpen(false);
            setIsAccountMenuOpen(false);
            onOpenHud();
          }}
        >
          <Grid2X2 size={21} />
        </button>
        <div className="notification-center" ref={notificationRef}>
          <button
            className="icon-button"
            type="button"
            aria-label="Notifications"
            aria-expanded={isNotificationsOpen}
            aria-controls={notificationPanelId}
            onClick={() => {
              setIsAccountMenuOpen(false);
              setIsNotificationsOpen((isOpen) => !isOpen);
            }}
            onKeyDown={(event) => {
              if (event.key === "Escape") {
                setIsNotificationsOpen(false);
              }
            }}
          >
            <Bell size={21} />
            {notificationCount > 0 && <span className="bubble">{notificationCount}</span>}
          </button>
          {isNotificationsOpen && (
            <section className="notifications-panel" id={notificationPanelId} aria-label="Recent BuildFlow activity">
              <header>
                <span>Notifications</span>
                <strong>Recent BuildFlow activity</strong>
              </header>
              <div className="notifications-list">
                {notificationItems.map((item) => {
                  const Icon = item.icon;
                  return (
                    <article key={item.id} className={`notification-item ${item.tone}`}>
                      <span className="notification-icon">
                        <Icon size={17} />
                      </span>
                      <div>
                        <strong>{item.title}</strong>
                        <p>{item.detail}</p>
                        <time>{formatNotificationTimestamp(item.timestamp)}</time>
                      </div>
                    </article>
                  );
                })}
              </div>
            </section>
          )}
        </div>
        <button
          className="icon-button topbar-help-button"
          type="button"
          aria-label="Help and tutorial"
          title="Help &amp; tutorial"
          data-tutorial-id="tutorial-restart-button"
          onClick={() => {
            setIsNotificationsOpen(false);
            setIsAccountMenuOpen(false);
            onStartTutorial();
          }}
        >
          <HelpCircle size={20} />
        </button>
        <div className="reports-account-menu" ref={accountMenuRef}>
          <button
            className="reports-user-button"
            type="button"
            aria-label={`${accountDisplayName} account`}
            aria-haspopup="menu"
            aria-expanded={isAccountMenuOpen}
            aria-controls={accountMenuId}
            onClick={() => {
              setIsNotificationsOpen(false);
              setIsAccountMenuOpen((isOpen) => !isOpen);
            }}
            onKeyDown={(event) => {
              if (event.key === "Escape") {
                setIsAccountMenuOpen(false);
              }
            }}
          >
            <span className="reports-avatar">{accountDisplayAvatar}</span>
            <ChevronDown size={18} />
          </button>
          {isAccountMenuOpen && (
            <div className="user-settings-menu" id={accountMenuId} role="menu" aria-label="Account menu">
              <div className="user-settings-identity">
                <span className="reports-avatar">{accountDisplayAvatar}</span>
                <span>
                  <strong>{accountDisplayName}</strong>
                  <em>{accountDisplayRole}</em>
                </span>
              </div>
              <button
                className="user-settings-button"
                type="button"
                role="menuitem"
                title="Settings"
                onClick={() => {
                  setIsAccountMenuOpen(false);
                  onOpenSettings();
                }}
              >
                <Settings size={18} />
                <span>Settings</span>
              </button>
              <button
                className="user-settings-button"
                type="button"
                role="menuitem"
                title="Log out"
                onClick={() => {
                  setIsAccountMenuOpen(false);
                  onLogout();
                }}
              >
                <LogOut size={18} />
                <span>Log out</span>
              </button>
            </div>
          )}
        </div>
      </div>
    </header>
  );
}

function BuildFlowTutorial({
  data,
  page,
  selectedBusinessType,
  selectedPlanId,
  selectedProductIds,
  onNavigate,
  onSkip,
  onFinish
}: {
  data: BootstrapPayload;
  page: Page;
  selectedBusinessType: BusinessTypeId | "";
  selectedPlanId: ProductPlanId | "";
  selectedProductIds: OnboardingProductId[];
  onNavigate: (page: Page) => void;
  onSkip: () => void;
  onFinish: () => void;
}) {
  const steps = useMemo(
    () => buildTutorialSteps({ selectedBusinessType, selectedPlanId, selectedProductIds }),
    [selectedBusinessType, selectedPlanId, selectedProductIds]
  );
  const [activeIndex, setActiveIndex] = useState(0);
  const [spotlightRect, setSpotlightRect] = useState<TutorialSpotlightRect | null>(null);
  const [panelPosition, setPanelPosition] = useState<TutorialPanelPosition | null>(null);
  const [domVersion, setDomVersion] = useState(0);
  const panelRef = useRef<HTMLElement | null>(null);
  const baselineRef = useRef({
    crews: data.crews.length,
    jobs: data.jobs.length,
    assignments: data.assignments.length
  });
  const activeStep = steps[Math.min(activeIndex, steps.length - 1)];
  const isFinalStep = activeIndex >= steps.length - 1;
  const isStepSatisfied = tutorialStepIsSatisfied(activeStep, data, baselineRef.current);
  const lessonItems = steps.map((step) => step.shortTitle);

  useEffect(() => {
    if (!activeStep.page || activeStep.page === page) return;
    onNavigate(activeStep.page);
  }, [activeStep.page, onNavigate, page]);

  useEffect(() => {
    if (typeof document === "undefined" || typeof MutationObserver === "undefined") return;
    const observer = new MutationObserver(() => setDomVersion((value) => value + 1));
    observer.observe(document.body, { attributes: true, childList: true, subtree: true });
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (typeof document === "undefined" || typeof window === "undefined" || !activeStep.targetId) {
      setSpotlightRect(null);
      setPanelPosition(null);
      return;
    }

    const updateSpotlight = () => {
      const target = document.querySelector<HTMLElement>(`[data-tutorial-id="${activeStep.targetId}"]`);
      if (!target) {
        setSpotlightRect(null);
        setPanelPosition(null);
        return;
      }

      if (typeof target.scrollIntoView === "function") {
        target.scrollIntoView({ block: "center", inline: "center" });
      }

      const rect = target.getBoundingClientRect();
      const nextSpotlightRect = {
        top: Math.max(8, rect.top - 8),
        left: Math.max(8, rect.left - 8),
        width: rect.width + 16,
        height: rect.height + 16
      };
      setSpotlightRect({
        top: nextSpotlightRect.top,
        left: nextSpotlightRect.left,
        width: nextSpotlightRect.width,
        height: nextSpotlightRect.height
      });

      if (window.innerWidth <= 720) {
        setPanelPosition(null);
        return;
      }

      const nextPanelPosition = chooseTutorialPanelPosition(
        rect,
        panelRef.current?.getBoundingClientRect(),
        window.innerWidth,
        window.innerHeight
      );
      setPanelPosition((current) => {
        if (current && Math.abs(current.top - nextPanelPosition.top) < 1 && Math.abs(current.left - nextPanelPosition.left) < 1) {
          return current;
        }
        return nextPanelPosition;
      });
    };

    updateSpotlight();
    window.addEventListener("resize", updateSpotlight);
    window.addEventListener("scroll", updateSpotlight, true);
    return () => {
      window.removeEventListener("resize", updateSpotlight);
      window.removeEventListener("scroll", updateSpotlight, true);
    };
  }, [activeStep.targetId, domVersion, page]);

  const overlayStyle = spotlightRect
    ? ({
        "--tutorial-spotlight-top": `${spotlightRect.top}px`,
        "--tutorial-spotlight-left": `${spotlightRect.left}px`,
        "--tutorial-spotlight-width": `${spotlightRect.width}px`,
        "--tutorial-spotlight-height": `${spotlightRect.height}px`
      } as CSSProperties)
    : undefined;
  const panelStyle = panelPosition
    ? ({
        top: `${panelPosition.top}px`,
        left: `${panelPosition.left}px`,
        right: "auto"
      } as CSSProperties)
    : undefined;

  const goBack = () => setActiveIndex((current) => Math.max(0, current - 1));
  const goNext = () => {
    if (!isStepSatisfied) return;
    if (isFinalStep) {
      onFinish();
      return;
    }
    setActiveIndex((current) => Math.min(steps.length - 1, current + 1));
  };

  return (
    <section className="buildflow-tutorial-overlay" aria-label="BuildFlow tutorial" style={overlayStyle}>
      {spotlightRect && <div className="buildflow-tutorial-spotlight" aria-hidden="true" />}
      <aside
        className="buildflow-tutorial-panel"
        ref={panelRef}
        role="dialog"
        aria-modal="false"
        aria-labelledby="buildflow-tutorial-title"
        style={panelStyle}
      >
        <div className="buildflow-tutorial-progress">
          <span>Step {activeIndex + 1} of {steps.length}</span>
          <strong>{Math.round(((activeIndex + 1) / steps.length) * 100)}%</strong>
        </div>
        <div className="buildflow-tutorial-meter" aria-hidden="true">
          <span style={{ width: `${((activeIndex + 1) / steps.length) * 100}%` }} />
        </div>
        <div className="buildflow-tutorial-copy">
          <h2 id="buildflow-tutorial-title">{activeStep.title}</h2>
          <p>{activeStep.body}</p>
          {activeStep.requirement && !isStepSatisfied && (
            <p className="buildflow-tutorial-requirement" role="status">
              {activeStep.requirement}
            </p>
          )}
        </div>
        <div className="buildflow-tutorial-lessons" aria-label="Tutorial lessons">
          {lessonItems.map((lesson, index) => (
            <span key={`${lesson}-${index}`} className={index === activeIndex ? "active" : index < activeIndex ? "done" : ""}>
              {lesson}
            </span>
          ))}
        </div>
        <div className="buildflow-tutorial-actions">
          <button type="button" className="outline-button" onClick={onSkip}>
            Skip Tutorial
          </button>
          <span>
            <button type="button" className="outline-button" onClick={goBack} disabled={activeIndex === 0}>
              Back
            </button>
            <button type="button" className="primary-button" onClick={goNext} disabled={!isStepSatisfied}>
              {isFinalStep ? "Finish" : "Next"}
            </button>
          </span>
        </div>
      </aside>
    </section>
  );
}

// Billing → "Plans that grow with you": the reference two-card layout, in the
// Command Center light palette, reusing the existing Monthly/Yearly slide +
// price-count tweens (BillingToggle / AnimatedPlanPrice).
const SETTINGS_PLAN_SEGMENTS: Array<{ id: "individual" | "team"; label: string; plans: [ProductPlanId, ProductPlanId] }> = [
  { id: "individual", label: "Individual", plans: ["pro", "business"] },
  { id: "team", label: "Team & Enterprise", plans: ["business", "enterprise"] }
];
const SETTINGS_PLAN_CARDS: Record<ProductPlanId, { tagline: string; featureHead: string; cta: string; toggle: boolean; note?: string; current?: boolean }> = {
  free: { tagline: "Demo of BuildFlow", featureHead: "Includes:", cta: "Start free demo", toggle: false },
  pro: { tagline: "Live crew scheduling, readiness, and reporting", featureHead: "Everything in Free and:", cta: "Downgrade to Pro", toggle: true },
  business: { tagline: "Cross-project dispatch and field control", featureHead: "Everything in Pro, plus:", cta: "Manage plan", toggle: false, note: "No commitment · Cancel anytime", current: true },
  enterprise: { tagline: "Custom workflows and priority support", featureHead: "Everything in Business, plus:", cta: "Contact sales", toggle: false, note: "Tailored onboarding" }
};

function SettingsBillingPlans() {
  const [segment, setSegment] = useState<"individual" | "team">("individual");
  const [billing, setBilling] = useState<BillingPeriod>("yearly");
  const active = SETTINGS_PLAN_SEGMENTS.find((seg) => seg.id === segment) ?? SETTINGS_PLAN_SEGMENTS[0];

  return (
    <div className="sx-plans">
      <h2 className="sx-plans-title">Plans that grow with you</h2>
      <div className="sx-seg" role="tablist" aria-label="Plan audience">
        <span className={`sx-seg-ind sx-seg-ind-${segment}`} aria-hidden="true" />
        {SETTINGS_PLAN_SEGMENTS.map((seg) => (
          <button
            key={seg.id}
            type="button"
            role="tab"
            aria-selected={segment === seg.id}
            className={`sx-seg-opt ${segment === seg.id ? "on" : ""}`}
            onClick={() => setSegment(seg.id)}
          >
            {seg.label}
          </button>
        ))}
      </div>

      <div className="sx-plan-grid" key={segment}>
        {active.plans.map((planId, index) => {
          const plan = planById[planId];
          const card = SETTINGS_PLAN_CARDS[planId];
          const Icon = plan.icon;
          const isPaid = plan.priceMonthly !== null && plan.priceMonthly > 0;
          const pricing = planPricing(plan, billing);
          const features = plan.features.filter((feature) => !/^everything in /i.test(feature));
          return (
            <article
              key={planId}
              className={`sx-plan-card${card.current ? " current" : ""}`}
              style={{ "--i": index } as CSSProperties}
            >
              <div className="sx-plan-top">
                <span className={`sx-plan-icon tone-${plan.tone}`} aria-hidden="true"><Icon size={22} /></span>
                {card.toggle && isPaid && (
                  <BillingToggle value={billing} onChange={setBilling} className="sx-plan-toggle" />
                )}
              </div>
              <h3 className="sx-plan-name">{plan.name}</h3>
              <p className="sx-plan-tag">{card.tagline}</p>
              <div className="sx-plan-price">
                <strong>
                  {card.toggle ? <AnimatedPlanPrice plan={plan} period={billing} /> : isPaid ? `From ${plan.price}` : plan.price}
                </strong>
                <span className="sx-plan-unit">
                  {card.toggle ? pricing.note : isPaid ? "USD / user · billed monthly" : "Custom pricing"}
                </span>
              </div>
              <button type="button" className={`sx-plan-cta${card.current ? " primary" : ""}`}>{card.cta}</button>
              {card.note && <span className="sx-plan-note">{card.note}</span>}
              <div className="sx-plan-sep" aria-hidden="true" />
              <div className="sx-plan-feat">
                <span className="sx-plan-feat-head">{card.featureHead}</span>
                <ul>
                  {features.map((feature) => (
                    <li key={feature}><Check size={16} /> <span>{feature}</span></li>
                  ))}
                </ul>
              </div>
            </article>
          );
        })}
      </div>

      <p className="sx-plans-foot">
        <a href="#usage-limits" onClick={(event) => event.preventDefault()}>*Usage limits apply.</a> Prices and plans are subject to change at BuildFlow's discretion.
      </p>
    </div>
  );
}

