function SettingsToggle({
  checked,
  label,
  onChange
}: {
  checked: boolean;
  label: string;
  onChange: (nextValue: boolean) => void;
}) {
  return (
    <button
      className={checked ? "settings-toggle active" : "settings-toggle"}
      type="button"
      aria-label={label}
      aria-pressed={checked}
      onClick={() => onChange(!checked)}
    >
      <span />
    </button>
  );
}

type SupportChatMessage = {
  id: string;
  author: "agent" | "team" | "user";
  text: string;
  timestamp: string;
};

const initialSupportMessages: SupportChatMessage[] = [
  {
    id: "agent-welcome",
    author: "agent",
    text: "Hi, I am BuildFlow AI Agent. I can help with schedules, crews, projects, materials, delayIQs, reports, and where to click next.",
    timestamp: "Now"
  },
  {
    id: "agent-tip",
    author: "agent",
    text: "If I miss the mark, type Support Team Member and I will route this chat to a person.",
    timestamp: "Now"
  }
];

function userRequestedSupportTeam(message: string) {
  return /\b(support team member|human support|real person|actual support|support rep|representative|live agent|talk to (a )?(person|human|support)|speak to (a )?(person|human|support)|connect me (to|with)|escalate)\b/i.test(message);
}

function createSupportTeamHandoff(reason: "requested" | "agent-limit"): SupportChatMessage {
  const text =
    reason === "requested"
      ? "Support Team Member requested. Your note was added for the support team. A Support Team Member will review this conversation from here."
      : "I do not want to guess on that one. I am routing this conversation to a Support Team Member so a person can review the details.";

  return {
    id: `team-${Date.now()}`,
    author: "team",
    text: `${text} Add the page you are on, what you tried, and any error text so they can pick it up quickly.`,
    timestamp: "Just now"
  };
}

function getSupportAgentReply(message: string): SupportChatMessage {
  const normalizedMessage = message.toLowerCase();
  const id = `agent-${Date.now()}`;
  const baseReply = {
    id,
    author: "agent" as const,
    timestamp: "Just now"
  };

  if (/\b(hi|hello|hey|start|help)\b/.test(normalizedMessage) && message.trim().split(/\s+/).length <= 5) {
    return {
      ...baseReply,
      text:
        "I can help you find the right page, explain a workflow, troubleshoot a scheduling issue, or connect you with a Support Team Member. What are you trying to do in BuildFlow?"
    };
  }

  if (/\b(schedule|scheduling|crew conflict|conflict|overbook|overbooked|assign|dispatch|drag|board)\b/.test(normalizedMessage)) {
    return {
      ...baseReply,
      text:
        "For scheduling help, open Schedule, check Scheduling Alerts on the right, then use the board to move work by crew and day. If a card shows a conflict, open the alert first, confirm crew availability, materials, and equipment, then drag the job to a ready slot."
    };
  }

  if (/\b(crew|crews|labor|superintendent|foreman|capacity)\b/.test(normalizedMessage)) {
    return {
      ...baseReply,
      text:
        "For crew questions, open Crews to compare capacity, current work, labor mix, and utilization. On the Schedule page, the crew rows show where capacity is tight so you can rebalance work before dispatch."
    };
  }

  if (/\b(project|projects|timeline|milestone|phase|percent|completion)\b/.test(normalizedMessage)) {
    return {
      ...baseReply,
      text:
        "For project help, open Projects, pick the project card, and review status, schedule health, completion, location, dates, and milestones. Use the edit dialog when the project status or timeline needs to change."
    };
  }

  if (/\b(material|materials|delivery|deliveries|missing|readiness|stock)\b/.test(normalizedMessage)) {
    return {
      ...baseReply,
      text:
        "For material issues, open Materials and filter by missing, waiting on delivery, ordered, or ready items. If a scheduled job depends on missing material, resolve that readiness blocker before assigning the crew."
    };
  }

  if (/\b(equipment|truck|vehicle|crane|pump|maintenance|fleet)\b/.test(normalizedMessage)) {
    return {
      ...baseReply,
      text:
        "For equipment questions, open Equipment to check status, assignment, maintenance, and conflicts. If equipment is unavailable, update the assignment or move the job to a slot where the required equipment is ready."
    };
  }

  if (/\b(delayIQ|delayIQs|late|blocked|weather|rain|risk|issue)\b/.test(normalizedMessage)) {
    return {
      ...baseReply,
      text:
        "For delayIQs, open DelayIQs to log the cause, severity, owner, and impact days. Weather and field updates can also create schedule risk, so check the affected job and update the recovery plan before moving crews."
    };
  }

  if (/\b(field update|field updates|jobsite|site update|daily log|progress note|photo)\b/.test(normalizedMessage)) {
    return {
      ...baseReply,
      text:
        "For field updates, open Field Updates, choose the status, add the site note, and submit it. Superintendents and crew leads can post updates while project managers can review incoming field notes."
    };
  }

  if (/\b(map|route|routes|location|travel|drive|field ops|dispatch route)\b/.test(normalizedMessage)) {
    return {
      ...baseReply,
      text:
        "For map and route help, open Map & Field Ops to compare job locations, crew movement, travel windows, and route context before dispatching the daily plan."
    };
  }

  if (/\b(report|reports|export|dashboard|analytics|trend|variance|kpi)\b/.test(normalizedMessage)) {
    return {
      ...baseReply,
      text:
        "For reporting, open Reports to review schedule variance, backlog, crew demand, project health, and production trends. Use exports when you need to share the current schedule or report view."
    };
  }

  if (/\b(login|password|account|billing|invoice|payment|plan|subscription|security|permission|admin|user access)\b/.test(normalizedMessage)) {
    return createSupportTeamHandoff("agent-limit");
  }

  if (/\b(error|bug|broken|crash|not working|wrong|incorrect|bad response|not right|doesn't work|does not work)\b/.test(normalizedMessage)) {
    return createSupportTeamHandoff("agent-limit");
  }

  return createSupportTeamHandoff("agent-limit");
}

function SupportChat() {
  const [isOpen, setIsOpen] = useState(false);
  const [draft, setDraft] = useState("");
  const [messages, setMessages] = useState<SupportChatMessage[]>(initialSupportMessages);
  const [supportMode, setSupportMode] = useState<"ai" | "team">("ai");
  const panelId = "support-chat-panel";

  function requestSupportTeam() {
    setSupportMode("team");
    setMessages((currentMessages) => [...currentMessages, createSupportTeamHandoff("requested")]);
  }

  function submitMessage(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const trimmedDraft = draft.trim();
    if (!trimmedDraft) return;

    const timestamp = Date.now();
    const userMessage: SupportChatMessage = {
      id: `user-${timestamp}`,
      author: "user",
      text: trimmedDraft,
      timestamp: "Just now"
    };

    if (supportMode === "team") {
      const nextMessages = userRequestedSupportTeam(trimmedDraft)
        ? [userMessage, createSupportTeamHandoff("requested")]
        : [userMessage];

      setMessages((currentMessages) => [...currentMessages, ...nextMessages]);
      setDraft("");
      return;
    }

    const reply = userRequestedSupportTeam(trimmedDraft)
      ? createSupportTeamHandoff("requested")
      : getSupportAgentReply(trimmedDraft);

    if (reply.author === "team") {
      setSupportMode("team");
    }

    setMessages((currentMessages) => [...currentMessages, userMessage, reply]);
    setDraft("");
  }

  return (
    <aside className="support-chat" aria-label="BuildFlow support chat">
      {isOpen && (
        <section className="support-chat-panel" id={panelId} aria-label="Support chat">
          <header className="support-chat-header">
            <span>
              <MessageCircle size={18} />
            </span>
            <div>
              <strong>Support Chat</strong>
              <em>{supportMode === "ai" ? "AI Agent active" : "Support team requested"}</em>
            </div>
            <button type="button" aria-label="Close support chat" title="Close support chat" onClick={() => setIsOpen(false)}>
              <X size={18} />
            </button>
          </header>
          <div className={supportMode === "ai" ? "support-chat-mode" : "support-chat-mode team"}>
            <Sparkles size={15} />
            <span>{supportMode === "ai" ? "AI Agent is answering first." : "A Support Team Member handoff is queued."}</span>
          </div>
          <div className="support-chat-messages" role="log" aria-live="polite" aria-relevant="additions">
            {messages.map((message) => (
              <article key={message.id} className={`support-chat-message ${message.author}`}>
                <p>{message.text}</p>
                <time>{message.timestamp}</time>
              </article>
            ))}
          </div>
          {supportMode === "ai" && (
            <div className="support-chat-actions" aria-label="Support chat actions">
              <button type="button" onClick={requestSupportTeam}>
                Support Team Member
              </button>
            </div>
          )}
          <form className="support-chat-form" onSubmit={submitMessage}>
            <label>
              <span>{supportMode === "ai" ? "Message AI Agent" : "Message support team"}</span>
              <textarea
                value={draft}
                onChange={(event) => setDraft(event.target.value)}
                placeholder={supportMode === "ai" ? "Ask the AI Agent..." : "Add details for the support team..."}
                rows={2}
              />
            </label>
            <button type="submit" aria-label="Send support message" title="Send support message" disabled={!draft.trim()}>
              <Send size={18} />
            </button>
          </form>
        </section>
      )}
      <button
        className="support-chat-toggle"
        type="button"
        aria-label={isOpen ? "Close support chat" : "Open support chat"}
        aria-expanded={isOpen}
        aria-controls={panelId}
        title="Support chat"
        onClick={() => setIsOpen((current) => !current)}
      >
        <MessageCircle size={23} />
        {!isOpen && <span className="support-chat-status" aria-hidden="true" />}
      </button>
    </aside>
  );
}

