// Subtle cursor-driven 3D tilt, mirroring the welcome page's floating windows.
function DxTilt({ children, max = 7 }: { children: ReactNode; max?: number }) {
  const ref = useRef<HTMLDivElement>(null);
  const handleMove = (event: { clientX: number; clientY: number }) => {
    const el = ref.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const px = (event.clientX - rect.left) / rect.width;
    const py = (event.clientY - rect.top) / rect.height;
    el.style.setProperty("--rx", `${(px - 0.5) * 2 * max}deg`);
    el.style.setProperty("--ry", `${(0.5 - py) * 2 * max}deg`);
  };
  const handleLeave = () => {
    const el = ref.current;
    if (!el) return;
    el.style.setProperty("--rx", "0deg");
    el.style.setProperty("--ry", "0deg");
  };
  return (
    <div className="dx-tilt" ref={ref} onPointerMove={handleMove} onPointerLeave={handleLeave}>
      {children}
    </div>
  );
}

// Shared "Antigravity" HUD motion: cursor parallax (aurora + tint) and scroll
// reveals. Progressive enhancement — `dx-ready` turns on the hidden start state
// only once JS runs, so content is never stuck invisible without JS.
function useHudMotion(rootRef: React.RefObject<HTMLElement | null>) {
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    let raf = 0;
    const handleMove = (event: PointerEvent) => {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => {
        const nx = event.clientX / window.innerWidth;
        const ny = event.clientY / window.innerHeight;
        root.style.setProperty("--mx", `${event.clientX}px`);
        root.style.setProperty("--my", `${event.clientY}px`);
        root.style.setProperty("--px", `${(nx - 0.5) * 2}`);
        root.style.setProperty("--py", `${(ny - 0.5) * 2}`);
      });
    };
    window.addEventListener("pointermove", handleMove);
    return () => {
      window.removeEventListener("pointermove", handleMove);
      cancelAnimationFrame(raf);
    };
  }, [rootRef]);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    root.classList.add("dx-ready");
    const targets = root.querySelectorAll("[data-reveal], [data-reveal-stagger]");
    const reduce = typeof window.matchMedia === "function" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduce || typeof IntersectionObserver === "undefined") {
      targets.forEach((el) => el.classList.add("in"));
      return;
    }
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add("in");
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.12, rootMargin: "0px 0px -5% 0px" }
    );
    targets.forEach((el) => observer.observe(el));
    return () => observer.disconnect();
  }, [rootRef]);
}

type CcTone = "blue" | "green" | "amber" | "red" | "violet" | "orange";

// Lightweight inline SVG sparkline — colored via a `tone-*` class (currentColor).
function Sparkline({ data, tone = "blue" }: { data: number[]; tone?: CcTone }) {
  const w = 100;
  const h = 30;
  const max = Math.max(...data);
  const min = Math.min(...data);
  const span = max - min || 1;
  const step = w / (data.length - 1);
  const points = data.map((value, index) => {
    const x = index * step;
    const y = h - ((value - min) / span) * (h - 6) - 3;
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  });
  const line = `M${points.join(" L")}`;
  const area = `${line} L${w},${h} L0,${h} Z`;
  return (
    <svg className={`cc-spark tone-${tone}`} viewBox={`0 0 ${w} ${h}`} preserveAspectRatio="none" aria-hidden="true">
      <path className="cc-spark-fill" d={area} />
      <path className="cc-spark-line" d={line} />
    </svg>
  );
}

// Circular progress ring — colored via a `tone-*` class (currentColor).
function ProgressRing({ value, tone = "blue", size = 46 }: { value: number; tone?: CcTone; size?: number }) {
  const stroke = 4;
  const radius = (size - stroke) / 2;
  const circumference = 2 * Math.PI * radius;
  const clamped = Math.max(0, Math.min(100, value));
  const offset = circumference * (1 - clamped / 100);
  const center = size / 2;
  return (
    <span className={`cc-ring tone-${tone}`} style={{ width: size, height: size }}>
      <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} aria-hidden="true">
        <circle className="cc-ring-track" cx={center} cy={center} r={radius} strokeWidth={stroke} fill="none" />
        <circle
          className="cc-ring-bar"
          cx={center}
          cy={center}
          r={radius}
          strokeWidth={stroke}
          fill="none"
          strokeLinecap="round"
          strokeDasharray={circumference}
          strokeDashoffset={offset}
          transform={`rotate(-90 ${center} ${center})`}
        />
      </svg>
      <b>{Math.round(clamped)}%</b>
    </span>
  );
}

// ============================================================================
// Draggable dashboard layout — per-user, client-only persistence.
//
// Each user can rearrange their Command Center: reorder the main sections
// (Ask AI → Quick Actions → Performance → KPIs → Apps → Workflows) vertically,
// and reorder the individual metric cards within the Performance and KPI rows
// (side to side). The chosen order is saved to localStorage keyed by the active
// user's id, so it lives only on that person's device and is NEVER written to
// the shared company backend — one user's layout can't affect anyone else's.
// ============================================================================
type DashScope = "section" | "stats" | "kpis" | "rail";

const DASH_SECTION_DEFAULT = ["ai", "quick", "stats", "kpis", "apps", "workflows"];
const DASH_SECTION_TITLES: Record<string, string> = {
  ai: "Ask BuildFlow AI",
  quick: "Quick Actions",
  stats: "Performance",
  kpis: "Operational KPIs",
  apps: "BuildFlow Apps",
  workflows: "Active AI Workflows"
};
const DASH_STAT_DEFAULT = ["st-sched", "st-ontrack", "st-workflows", "st-labor", "st-cost"];
const DASH_KPI_DEFAULT = ["kpi-jobs", "kpi-crews", "kpi-equip", "kpi-delayIQs"];
const DASH_RAIL_DEFAULT = ["approvals", "alerts", "recommendations"];
const DASH_RAIL_TITLES: Record<string, string> = {
  approvals: "Pending Approvals",
  alerts: "Project Alerts",
  recommendations: "AI Recommendations"
};

function readStoredOrder(key: string): string[] | null {
  try {
    const raw = localStorage.getItem(key);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) && parsed.every((entry) => typeof entry === "string") ? parsed : null;
  } catch {
    return null;
  }
}
function writeStoredOrder(key: string, ids: string[]) {
  try {
    localStorage.setItem(key, JSON.stringify(ids));
  } catch {
    /* ignore quota / private-mode write failures — layout just won't persist */
  }
}
// Merge a saved order with the current default set: keep saved positions for ids
// that still exist, drop any that no longer exist, and append new defaults at the
// end. This keeps a saved layout stable even as the dashboard's contents evolve.
function reconcileOrder(saved: string[] | null, defaults: string[]): string[] {
  if (!saved) return defaults.slice();
  const valid = saved.filter((id) => defaults.includes(id));
  const missing = defaults.filter((id) => !valid.includes(id));
  return [...valid, ...missing];
}
function moveId(ids: string[], dragId: string, overId: string): string[] {
  if (dragId === overId) return ids;
  const from = ids.indexOf(dragId);
  const to = ids.indexOf(overId);
  if (from === -1 || to === -1) return ids;
  const next = ids.slice();
  next.splice(from, 1);
  next.splice(to, 0, dragId);
  return next;
}

function usePersistentOrder(storageKey: string, defaults: string[]) {
  const [order, setOrder] = useState<string[]>(() => reconcileOrder(readStoredOrder(storageKey), defaults));
  // Re-read when the active user (storageKey) changes so each user sees their own layout.
  useEffect(() => {
    setOrder(reconcileOrder(readStoredOrder(storageKey), defaults));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [storageKey]);
  const update = useCallback(
    (next: string[]) => {
      setOrder(next);
      writeStoredOrder(storageKey, next);
    },
    [storageKey]
  );
  const reset = useCallback(() => {
    setOrder(defaults.slice());
    try {
      localStorage.removeItem(storageKey);
    } catch {
      /* ignore */
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [storageKey]);
  return { order, update, reset };
}

// Only let a drag collide with drop targets in the SAME scope, so dragging a
// metric card never reorders sections (and vice-versa) even though the card
// droppables are nested inside the section droppables.
const dashCollisionDetection: CollisionDetection = (args) => {
  const scope = args.active?.data?.current?.scope as DashScope | undefined;
  const containers = scope
    ? args.droppableContainers.filter((container) => container.data.current?.scope === scope)
    : args.droppableContainers;
  return closestCenter({ ...args, droppableContainers: containers });
};

type CcStatItem = {
  id: string;
  icon: typeof Gauge;
  tone: CcTone;
  label: string;
  value: string;
  small: string;
  trend: "up" | "down" | "flag";
  delta: string;
  note: string;
  spark: number[];
};
type CcKpiItem = {
  id: string;
  icon: typeof HardHat;
  tone: string;
  label: string;
  value: number;
  delta: string;
  feed: DashboardFeedKey;
};

// A whole dashboard section (full-width block). Draggable only from its grip
// handle so the interactive content inside stays clickable; droppable anywhere.
// Smooth reorder motion shared by every draggable dashboard element: neighbours
// glide out of the way and dropped items settle with the same easeOut curve.
const DASH_SORT_TRANSITION = { duration: 260, easing: "cubic-bezier(0.22, 1, 0.36, 1)" };

// Inline style from a useSortable result. The lifted item follows the pointer
// instantly (transition off) and sits above the grid; neighbours keep the
// transition so they animate into their new slots.
function dashSortableStyle(transform: Transform | null, transition: string | undefined, isDragging: boolean): CSSProperties {
  return {
    transform: transform ? CSS.Transform.toString(transform) : undefined,
    transition: isDragging ? "none" : transition,
    zIndex: isDragging ? 60 : undefined
  };
}

// A whole dashboard block (a full-width main section, or a side-rail panel).
// Sortable via its grip handle so the interactive content inside stays clickable.
function DashSection({ id, title, children, scope = "section" }: { id: string; title: string; children: ReactNode; scope?: DashScope }) {
  const { setNodeRef, setActivatorNodeRef, attributes, listeners, transform, transition, isDragging } = useSortable({
    id,
    data: { scope },
    transition: DASH_SORT_TRANSITION
  });
  return (
    <div ref={setNodeRef} style={dashSortableStyle(transform, transition, isDragging)} className={`dash-block${isDragging ? " is-dragging" : ""}`}>
      <button
        type="button"
        ref={setActivatorNodeRef}
        className="dash-drag-handle"
        aria-label={`Drag to reorder ${title}`}
        title="Drag to reorder"
        {...attributes}
        {...listeners}
      >
        <GripVertical size={16} />
      </button>
      {children}
    </div>
  );
}

// A single Performance stat card — the whole card is draggable (side to side).
function DashStatCard({ stat }: { stat: CcStatItem }) {
  const { setNodeRef, listeners, transform, transition, isDragging } = useSortable({
    id: stat.id,
    data: { scope: "stats" },
    transition: DASH_SORT_TRANSITION
  });
  const Icon = stat.icon;
  const TrendIcon = stat.trend === "down" ? TrendingDown : stat.trend === "flag" ? AlertTriangle : TrendingUp;
  return (
    <article
      ref={setNodeRef}
      style={dashSortableStyle(transform, transition, isDragging)}
      className={`cc-stat dash-card${isDragging ? " is-dragging" : ""}`}
      {...listeners}
    >
      <div className="cc-stat-top">
        <span className={`cc-stat-ico tone-${stat.tone}`}>
          <Icon />
        </span>
        <span className="cc-stat-label">{stat.label}</span>
      </div>
      <div className="cc-stat-mid">
        <span className="cc-stat-value">
          {stat.value}
          {stat.small && <small> {stat.small}</small>}
        </span>
        <Sparkline data={stat.spark} tone={stat.tone} />
      </div>
      <div className="cc-stat-foot">
        <span className={`cc-trend ${stat.trend}`}>
          <TrendIcon />
          {stat.delta}
        </span>
        <span className="cc-stat-note">{stat.note}</span>
      </div>
    </article>
  );
}

// A single Operational KPI card — the whole card is draggable (side to side);
// a click (no drag) still opens its detail feed.
function DashKpiCard({ kpi, active, onOpen }: { kpi: CcKpiItem; active: boolean; onOpen: () => void }) {
  const { setNodeRef, listeners, transform, transition, isDragging } = useSortable({
    id: kpi.id,
    data: { scope: "kpis" },
    transition: DASH_SORT_TRANSITION
  });
  return (
    <div
      ref={setNodeRef}
      style={dashSortableStyle(transform, transition, isDragging)}
      className={`dash-card dash-kpi${isDragging ? " is-dragging" : ""}`}
      {...listeners}
    >
      <DxTilt>
        <KpiCard
          icon={kpi.icon}
          tone={kpi.tone}
          label={kpi.label}
          value={kpi.value}
          delta={kpi.delta}
          active={active}
          controlsId="dashboard-kpi-feed"
          onClick={onOpen}
        />
      </DxTilt>
    </div>
  );
}

