// Detects "I want to move my schedule over from another app" phrasing.
function isScheduleImportIntent(question: string): boolean {
  const text = question.toLowerCase();
  if (/\b(import|migrate)\b/.test(text)) return true;
  if (/\bswitch(ing|ed)?\b/.test(text) && /(schedul|app|program|buildflow|over|from|another|tool)/.test(text)) return true;
  if (/another (app|scheduler|program|tool)/.test(text)) return true;
  if (/(old|current|existing|previous) schedul|move (over|from)|coming from|read (my|this|the) schedul/.test(text)) return true;
  return false;
}

function CommandCenterAiPrompt({ data, reload }: { data: BootstrapPayload; reload: () => Promise<void> }) {
  const [attachments, setAttachments] = useState<AiAttachment[]>([]);
  const [dragging, setDragging] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  // Depth counter so nested dragenter/dragleave (over children) doesn't flicker.
  const dragDepth = useRef(0);
  // Mirror of state so the unmount cleanup can revoke the latest object URLs.
  const attachmentsRef = useRef<AiAttachment[]>([]);
  attachmentsRef.current = attachments;

  const [input, setInput] = useState("");
  const [messages, setMessages] = useState<AiMessage[]>([]);
  const [thinking, setThinking] = useState(false);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const threadRef = useRef<HTMLDivElement>(null);
  const thinkTimer = useRef<number | null>(null);

  const [toolsOpen, setToolsOpen] = useState(false);
  const [enabledTools, setEnabledTools] = useState<string[]>(() => AI_TOOLS.map((tool) => tool.id));
  const toolsRef = useRef<HTMLDivElement>(null);
  const toggleTool = (id: string) =>
    setEnabledTools((prev) => (prev.includes(id) ? prev.filter((tool) => tool !== id) : [...prev, id]));

  const [listening, setListening] = useState(false);
  const [voiceHint, setVoiceHint] = useState<string | null>(null);
  const recognitionRef = useRef<SpeechRecognitionLike | null>(null);
  const voiceSupported = useMemo(() => {
    if (typeof window === "undefined") return false;
    const speech = window as unknown as { SpeechRecognition?: unknown; webkitSpeechRecognition?: unknown };
    return Boolean(speech.SpeechRecognition || speech.webkitSpeechRecognition);
  }, []);

  // Schedule migration: read an uploaded photo/video of another scheduler and
  // build real jobs/projects on the BuildFlow schedule. `importStep` labels the
  // shimmering progress indicator while it runs.
  const [importing, setImporting] = useState(false);
  const [importStep, setImportStep] = useState("");

  useEffect(() => () => {
    attachmentsRef.current.forEach((item) => URL.revokeObjectURL(item.url));
    if (thinkTimer.current) window.clearTimeout(thinkTimer.current);
    if (recognitionRef.current) { recognitionRef.current.onend = null; recognitionRef.current.abort?.(); }
  }, []);

  // Close the Tools menu on an outside click or Escape.
  useEffect(() => {
    if (!toolsOpen) return;
    const onPointer = (event: globalThis.MouseEvent) => {
      if (toolsRef.current && !toolsRef.current.contains(event.target as Node)) setToolsOpen(false);
    };
    const onKey = (event: globalThis.KeyboardEvent) => { if (event.key === "Escape") setToolsOpen(false); };
    document.addEventListener("mousedown", onPointer);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("mousedown", onPointer);
      document.removeEventListener("keydown", onKey);
    };
  }, [toolsOpen]);

  // Pin the thread to the newest message; auto-size the input to its content.
  useEffect(() => {
    threadRef.current?.scrollTo({ top: threadRef.current.scrollHeight, behavior: "smooth" });
  }, [messages, thinking]);
  useEffect(() => {
    const el = inputRef.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = `${Math.min(el.scrollHeight, 120)}px`;
  }, [input]);

  const ask = (raw: string) => {
    const question = raw.trim();
    if (!question || thinking || importing) return;
    if (isScheduleImportIntent(question)) { void runImport(question); return; }
    const attachNote = attachments.length
      ? ` (I see ${attachments.length} attached file${attachments.length > 1 ? "s" : ""} — I can't read their contents yet, but here's what your data shows. To pull a schedule out of them, say “import my schedule”.)`
      : "";
    setMessages((prev) => [...prev, { id: `m-${Date.now()}-u`, role: "user", text: question }]);
    setInput("");
    setAttachments((prev) => { prev.forEach((item) => URL.revokeObjectURL(item.url)); return []; });
    setThinking(true);
    // Ask real Claude first (BuildFlow AI). Falls back to the built-in simulated
    // answer when Claude isn't configured on the server (DEMO MODE) or on error,
    // so the prompt always responds — see server/src/ai.ts.
    void (async () => {
      let liveAnswer: string | null = null;
      try {
        const res = await apiAskAi(question);
        if (res.mode === "live" && res.answer) liveAnswer = res.answer.trim() || null;
      } catch {
        /* fall through to the simulated answer */
      }
      if (liveAnswer) {
        setMessages((prev) => [
          ...prev,
          { id: `m-${Date.now()}-a`, role: "assistant", text: liveAnswer + attachNote }
        ]);
      } else {
        // Demo mode: take a deliberate beat so the answer reads as considered.
        await new Promise((resolve) => window.setTimeout(resolve, 1100 + Math.random() * 700));
        const answer = buildAiAnswer(question, data);
        setMessages((prev) => [
          ...prev,
          { id: `m-${Date.now()}-a`, role: "assistant", text: answer.text + attachNote, bullets: answer.bullets, suggestions: answer.suggestions }
        ]);
      }
      setThinking(false);
    })();
  };

  const handleSubmit = (event: FormEvent) => { event.preventDefault(); ask(input); };
  const handleKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
    if (event.key === "Enter" && !event.shiftKey) { event.preventDefault(); ask(input); }
  };

  // Expose ask() to dashboard quick actions (e.g. "Check Weather") via a stable
  // registration that always calls the latest closure through a ref.
  const askRef = useRef(ask);
  askRef.current = ask;
  useEffect(() => {
    dashboardAiAsk = (question: string) => askRef.current(question);
    return () => { dashboardAiAsk = null; };
  }, []);

  // Import the user's schedule from an uploaded photo/video of another scheduler:
  // generate projects + jobs, create them through the backend so they land on the
  // live schedule, then present how the plan was optimized.
  const runImport = async (question: string) => {
    if (thinking || importing) return;
    const fileCount = attachments.length;
    setMessages((prev) => [...prev, { id: `m-${Date.now()}-u`, role: "user", text: question }]);
    setInput("");

    if (fileCount === 0) {
      setThinking(true);
      await new Promise((resolve) => window.setTimeout(resolve, 850));
      setThinking(false);
      setMessages((prev) => [
        ...prev,
        {
          id: `m-${Date.now()}-a`,
          role: "assistant",
          text: "Happy to move you over from another scheduler. Attach a photo or a short video of your current schedule — Excel, Procore, a whiteboard, anything — with the + button (or drag it in), then send. I'll read it and build the jobs, projects, and schedule for you."
        }
      ]);
      return;
    }

    // Capture the uploaded images as base64 BEFORE revoking their object URLs,
    // so Claude vision can read them (videos are skipped — vision reads images).
    const imageUrls = (
      await Promise.all(
        attachments
          .filter((item) => item.kind === "image")
          .map(async (item) => {
            try {
              return await blobToDataUrl(await fetch(item.url).then((r) => r.blob()));
            } catch {
              return null;
            }
          })
      )
    ).filter((url): url is string => Boolean(url));
    setAttachments((prev) => { prev.forEach((item) => URL.revokeObjectURL(item.url)); return []; });
    setImporting(true);
    const wait = (ms: number) => new Promise((resolve) => window.setTimeout(resolve, ms));
    setImportStep(`Reading your schedule from ${fileCount} file${fileCount > 1 ? "s" : ""}…`);
    await wait(950);
    setImportStep("Detecting jobs, phases, and projects…");
    await wait(950);
    setImportStep("Adding jobs and projects to your BuildFlow schedule…");

    // Read the real uploaded schedule with Claude vision; fall back to a sample
    // plan when Claude isn't configured (DEMO MODE) or the image can't be read.
    let plan: ImportProjectSpec[] | null = null;
    if (imageUrls.length) {
      try {
        const res = await apiImportSchedule(imageUrls);
        if (res.mode === "live" && Array.isArray(res.plan) && res.plan.length) {
          plan = res.plan as ImportProjectSpec[];
        }
      } catch {
        /* fall back to the sample plan below */
      }
    }
    if (!plan) plan = buildScheduleImportPlan(data);
    const importedNames: string[] = [];
    let createdProjects = 0;
    let createdJobs = 0;
    let assigned = 0;
    try {
      for (const spec of plan) {
        const project = await createProject(spec.input);
        createdProjects += 1;
        for (const jobSpec of spec.jobs) {
          const { crewId, ...jobInput } = jobSpec;
          const job = await createJob({ ...jobInput, projectId: project.id });
          createdJobs += 1;
          if (crewId) {
            try { await assignJob({ jobId: job.id, crewId, date: jobInput.startDate, status: "Planned" }); assigned += 1; } catch { /* skip on crew conflict */ }
          }
        }
        importedNames.push(`${project.name} — ${spec.jobs.length} job${spec.jobs.length > 1 ? "s" : ""}`);
      }
      await reload();
    } catch {
      if (createdJobs === 0) {
        setImporting(false);
        setMessages((prev) => [
          ...prev,
          { id: `m-${Date.now()}-a`, role: "assistant", text: "I couldn't reach the schedule service to finish the import. Make sure BuildFlow's backend is running, then try again." }
        ]);
        return;
      }
    }

    setImportStep("Optimizing the imported schedule…");
    await wait(850);
    setImporting(false);
    setMessages((prev) => [
      ...prev,
      {
        id: `m-${Date.now()}-a`,
        role: "assistant",
        text: `Done — I read your old schedule and built ${createdJobs} jobs across ${createdProjects} projects, then placed them on your BuildFlow schedule (open the Schedule tab to see them). Here's what came over:`,
        bullets: importedNames
      },
      {
        id: `m-${Date.now()}-opt`,
        role: "assistant",
        text: "And here's how I optimized the imported plan:",
        bullets: [
          "Sequenced sitework and pours before framing and MEP to protect each project's critical path.",
          "Balanced the imported jobs across your available crews so no single team is overbooked.",
          "Front-loaded the high-priority concrete pours to early-week slots for better weather windows.",
          "Flagged jobs waiting on materials so you can expedite deliveries before their start dates."
        ],
        suggestions: ["What's at risk?", "Suggestions to optimize my week"]
      }
    ]);
  };

  const stopListening = () => {
    recognitionRef.current?.stop();
    setListening(false);
  };
  // Voice input: transcribe the user's speech into the prompt, then send it to
  // the assistant when they finish speaking (Web Speech API, no network needed).
  const startListening = () => {
    const speech = window as unknown as {
      SpeechRecognition?: new () => SpeechRecognitionLike;
      webkitSpeechRecognition?: new () => SpeechRecognitionLike;
    };
    const Recognition = speech.SpeechRecognition ?? speech.webkitSpeechRecognition;
    if (!Recognition) { setVoiceHint("Voice input isn't supported in this browser."); return; }
    const recognition = new Recognition();
    recognition.lang = "en-US";
    recognition.interimResults = true;
    recognition.continuous = false;
    recognition.maxAlternatives = 1;
    recognition.onresult = (event: any) => {
      let transcript = "";
      for (let i = 0; i < event.results.length; i += 1) transcript += event.results[i][0].transcript;
      setInput(transcript);
      const last = event.results[event.results.length - 1];
      if (last && last.isFinal) {
        const finalText = transcript.trim();
        recognition.stop();
        if (finalText) ask(finalText);
      }
    };
    recognition.onerror = (event: any) => {
      if (event.error === "not-allowed" || event.error === "service-not-allowed") setVoiceHint("Microphone access was blocked — allow it to talk to BuildFlow AI.");
      else if (event.error === "no-speech") setVoiceHint("Didn't catch that — tap the mic and try again.");
      setListening(false);
    };
    recognition.onend = () => { setListening(false); recognitionRef.current = null; };
    recognitionRef.current = recognition;
    setVoiceHint(null);
    setListening(true);
    try { recognition.start(); } catch { setListening(false); }
  };
  const toggleVoice = () => { if (listening) stopListening(); else startListening(); };

  const addFiles = (files: FileList | null) => {
    if (!files) return;
    const media = Array.from(files).filter((file) => file.type.startsWith("image/") || file.type.startsWith("video/"));
    if (!media.length) return;
    setAttachments((prev) => [
      ...prev,
      ...media.map((file) => ({
        id: `media-${Date.now()}-${Math.random().toString(36).slice(2)}`,
        name: file.name,
        url: URL.createObjectURL(file),
        kind: file.type.startsWith("video/") ? ("video" as const) : ("image" as const)
      }))
    ]);
  };

  const removeAttachment = (id: string) => {
    setAttachments((prev) => {
      const match = prev.find((item) => item.id === id);
      if (match) URL.revokeObjectURL(match.url);
      return prev.filter((item) => item.id !== id);
    });
  };

  const isFileDrag = (event: DragEvent<HTMLElement>) =>
    Array.from(event.dataTransfer?.types ?? []).includes("Files");

  const handleDragEnter = (event: DragEvent<HTMLElement>) => {
    if (!isFileDrag(event)) return;
    dragDepth.current += 1;
    setDragging(true);
  };
  const handleDragOver = (event: DragEvent<HTMLElement>) => {
    if (!isFileDrag(event)) return;
    event.preventDefault(); // allow the drop
  };
  const handleDragLeave = () => {
    dragDepth.current = Math.max(0, dragDepth.current - 1);
    if (dragDepth.current === 0) setDragging(false);
  };
  const handleDrop = (event: DragEvent<HTMLElement>) => {
    event.preventDefault();
    dragDepth.current = 0;
    setDragging(false);
    addFiles(event.dataTransfer?.files ?? null);
  };

  const handleFileChange = (event: ChangeEvent<HTMLInputElement>) => {
    addFiles(event.target.files);
    event.target.value = ""; // let the same file be re-picked later
  };

  return (
    <section
      // Keep className static: the reveal-on-scroll ".in" class is added
      // imperatively by an IntersectionObserver, so a dynamic className would
      // overwrite it and make the prompt disappear. Drag state rides on a
      // data-attribute instead.
      className="cc-ai"
      data-reveal
      data-dragging={dragging ? "true" : undefined}
      aria-label="Ask BuildFlow AI"
      onDragEnter={handleDragEnter}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      <div className="cc-ai-inner">
        {messages.length > 0 && (
          <div className="cc-ai-thread" ref={threadRef}>
            {messages.map((message) => (
              <div key={message.id} className={`cc-ai-msg cc-ai-msg-${message.role}`}>
                {message.text && <p className="cc-ai-msg-text">{message.text}</p>}
                {message.bullets && message.bullets.length > 0 && (
                  <ul className="cc-ai-msg-list">
                    {message.bullets.map((line, index) => <li key={index}>{line}</li>)}
                  </ul>
                )}
                {message.suggestions && message.suggestions.length > 0 && (
                  <div className="cc-ai-chiprow">
                    {message.suggestions.map((suggestion) => (
                      <button type="button" key={suggestion} className="cc-ai-sugg" onClick={() => ask(suggestion)}>{suggestion}</button>
                    ))}
                  </div>
                )}
              </div>
            ))}
            {(thinking || importing) && (
              <div className="cc-ai-msg cc-ai-msg-assistant">
                <TextShimmer as="span" className="cc-ai-generating" duration={1.3} spread={1.4}>
                  {importing ? importStep : "Generating prompt…"}
                </TextShimmer>
              </div>
            )}
          </div>
        )}

        <form className="cc-ai-form" onSubmit={handleSubmit}>
          <textarea
            ref={inputRef}
            className="cc-ai-input"
            value={input}
            onChange={(event) => setInput(event.target.value)}
            onKeyDown={handleKeyDown}
            placeholder={'Ask BuildFlow AI anything… e.g., "What\'s at risk this week?"'}
            rows={1}
            aria-label="Ask BuildFlow AI"
          />

          {listening && (
            <div className="cc-ai-voice" aria-live="polite">
              <span className="cc-ai-voice-dot" aria-hidden="true" />
              <span className="cc-ai-voice-wave" aria-hidden="true"><i /><i /><i /><i /><i /></span>
              Listening… speak your question
            </div>
          )}
          {voiceHint && !listening && (
            <div className="cc-ai-voice-hint" role="status">{voiceHint}</div>
          )}

          {attachments.length > 0 && (
            <div className="cc-ai-attach" aria-label="Attached media">
              {attachments.map((item) => (
                <div className={`cc-ai-thumb${item.kind === "video" ? " is-video" : ""}`} key={item.id}>
                  {item.kind === "video" ? (
                    <video src={item.url} muted playsInline aria-label={item.name} />
                  ) : (
                    <img src={item.url} alt={item.name} />
                  )}
                  {item.kind === "video" && (
                    <span className="cc-ai-thumb-play" aria-hidden="true"><PlayCircle size={16} /></span>
                  )}
                  <button
                    type="button"
                    className="cc-ai-thumb-remove"
                    aria-label={`Remove ${item.name}`}
                    onClick={() => removeAttachment(item.id)}
                  >
                    <X size={12} />
                  </button>
                </div>
              ))}
            </div>
          )}

          {messages.length === 0 && (
            <div className="cc-ai-chiprow cc-ai-starters">
              {AI_STARTERS.map((starter) => (
                <button type="button" key={starter} className="cc-ai-sugg" onClick={() => ask(starter)}>{starter}</button>
              ))}
            </div>
          )}

          <div className="cc-ai-row">
            <button
              type="button"
              className="cc-ai-chip icon-only"
              aria-label="Add photo or video"
              onClick={() => fileInputRef.current?.click()}
            >
              <Plus size={17} />
            </button>
            <div className="cc-ai-tools" ref={toolsRef}>
              <button
                type="button"
                className={`cc-ai-chip${toolsOpen ? " open" : ""}`}
                aria-haspopup="menu"
                aria-expanded={toolsOpen}
                onClick={() => setToolsOpen((value) => !value)}
              >
                Tools <ChevronDown size={15} className="cc-ai-chip-chev" />
              </button>
              {toolsOpen && (
                <div className="cc-ai-tools-menu" role="menu" aria-label="AI models by capability">
                  <div className="cc-ai-tools-head">
                    <Sparkles size={13} /> AI models by capability
                  </div>
                  {AI_TOOLS.map((tool) => {
                    const Icon = tool.icon;
                    const on = enabledTools.includes(tool.id);
                    return (
                      <button
                        type="button"
                        key={tool.id}
                        role="menuitemcheckbox"
                        aria-checked={on}
                        className={`cc-ai-tool${on ? " on" : ""}`}
                        onClick={() => toggleTool(tool.id)}
                      >
                        <span className="cc-ai-tool-icon"><Icon size={16} /></span>
                        <span className="cc-ai-tool-body">
                          <span className="cc-ai-tool-name">{tool.label}</span>
                          <span className="cc-ai-tool-sub">{tool.desc} · <em className="cc-ai-tool-model">{tool.model}</em></span>
                        </span>
                        <span className="cc-ai-tool-check" aria-hidden="true">{on && <Check size={15} />}</span>
                      </button>
                    );
                  })}
                  <div className="cc-ai-tools-foot">Tap a capability to toggle its model.</div>
                </div>
              )}
            </div>
            {voiceSupported && (
              <button
                type="button"
                className={`cc-ai-chip icon-only cc-ai-mic${listening ? " listening" : ""}`}
                aria-label={listening ? "Stop voice input" : "Talk to BuildFlow AI"}
                aria-pressed={listening}
                onClick={toggleVoice}
              >
                <Mic size={17} />
              </button>
            )}
            <button type="submit" className="cc-ai-send" aria-label="Send question" disabled={thinking || !input.trim()}>
              <ArrowRight size={18} />
            </button>
          </div>
        </form>
      </div>

      <input
        ref={fileInputRef}
        type="file"
        accept="image/*,video/*"
        multiple
        className="cc-ai-file"
        onChange={handleFileChange}
      />

      <div className="cc-ai-drop" aria-hidden="true">
        <span><ImagePlus size={18} /> Drop a photo or video to attach</span>
      </div>
    </section>
  );
}

function Dashboard({
  data,
  activeUser,
  setPage,
  reload,
  selectedBusinessType,
  selectedPlanId,
  selectedProductIds
}: {
  data: BootstrapPayload;
  activeUser: { id: string };
  setPage: (page: Page) => void;
  reload: () => Promise<void>;
  selectedBusinessType: BusinessTypeId | "";
  selectedPlanId: ProductPlanId | "";
  selectedProductIds: OnboardingProductId[];
}) {
  const [activeFeed, setActiveFeed] = useState<DashboardFeedKey | null>(null);
  const [resolvedApprovals, setResolvedApprovals] = useState<Set<string>>(() => new Set());
  const rootRef = useRef<HTMLDivElement>(null);

  // Per-user, drag-to-rearrange layout. Keyed by the active user's id so the
  // arrangement is saved only on this user's device (localStorage), never to the
  // shared company data.
  const sectionLayout = usePersistentOrder(`bf:dash:sections:${activeUser.id}`, DASH_SECTION_DEFAULT);
  const statLayout = usePersistentOrder(`bf:dash:stats:${activeUser.id}`, DASH_STAT_DEFAULT);
  const kpiLayout = usePersistentOrder(`bf:dash:kpis:${activeUser.id}`, DASH_KPI_DEFAULT);
  const railLayout = usePersistentOrder(`bf:dash:rail:${activeUser.id}`, DASH_RAIL_DEFAULT);
  const dragSensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 6 } }));

  // Arrived from an "Ask AI" launcher: bring the full "Ask BuildFlow AI" prompt
  // into view and pulse it so the redirect clearly lands on the AI field.
  useEffect(() => {
    if (!pendingDashboardAiFocus) return;
    pendingDashboardAiFocus = false;
    const timer = window.setTimeout(() => focusDashboardAiPrompt(), 180);
    return () => window.clearTimeout(timer);
  }, []);

  // Cursor parallax for the aurora background + cursor tint (matches welcome page).
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    let raf = 0;
    const handleMove = (event: PointerEvent) => {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => {
        const nx = event.clientX / window.innerWidth;
        const ny = event.clientY / window.innerHeight;
        root.style.setProperty("--mx", `${event.clientX}px`);
        root.style.setProperty("--my", `${event.clientY}px`);
        root.style.setProperty("--px", `${(nx - 0.5) * 2}`);
        root.style.setProperty("--py", `${(ny - 0.5) * 2}`);
      });
    };
    window.addEventListener("pointermove", handleMove);
    return () => {
      window.removeEventListener("pointermove", handleMove);
      cancelAnimationFrame(raf);
    };
  }, []);

  // Scroll reveals. Progressive enhancement: `dx-ready` turns on the hidden
  // start state only once JS runs, so content is never stuck invisible.
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    root.classList.add("dx-ready");
    const targets = root.querySelectorAll("[data-reveal], [data-reveal-stagger]");
    const reduce = typeof window.matchMedia === "function" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduce || typeof IntersectionObserver === "undefined") {
      targets.forEach((el) => el.classList.add("in"));
      return;
    }
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add("in");
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.12, rootMargin: "0px 0px -5% 0px" }
    );
    targets.forEach((el) => observer.observe(el));
    return () => observer.disconnect();
  }, []);

  const todaysJobs = jobsActiveOnDate(data.jobs, dashboardToday);
  const lastWeekJobs = jobsActiveOnDate(data.jobs, dashboardLastWeekSameDay);
  const todaysAssignments = data.assignments.filter((assignment) => assignment.date === dashboardToday);
  const lastWeekAssignments = data.assignments.filter((assignment) => assignment.date === dashboardLastWeekSameDay);
  const todaysCrewIds = new Set(todaysAssignments.map((assignment) => assignment.crewId));
  const lastWeekCrewIds = new Set(lastWeekAssignments.map((assignment) => assignment.crewId));
  const todaysCrews = data.crews.filter((crew) => todaysCrewIds.has(crew.id));
  const todaysCrewNames = todaysCrews.map((crew) => crew.name);
  const equipmentInUse = data.equipment.filter((item) => item.status === "In Use");
  const delayIQedProjects = data.projects.filter((project) => project.status === "DelayIQed");
  const lastWeekDelayIQedProjectIds = new Set(
    data.delayIQs
      .filter(
        (delayIQ) =>
          delayIQ.status !== "Resolved" &&
          delayIQ.reportedAt >= shiftDate(weekDays[0].date, -7) &&
          delayIQ.reportedAt < weekDays[0].date
      )
      .map((delayIQ) => delayIQ.projectId)
  );
  const materialCounts = materialReadiness(data);
  const weatherJobImpacts = weatherImpactsForActiveJobs(data.weatherAlerts, todaysJobs, dashboardToday);
  const activeWeatherImpact = weatherJobImpacts[0];
  const weatherImpactedJobNames = Array.from(new Set(weatherJobImpacts.map((impact) => impact.job.name)));
  const selectedPlanName = selectedPlanId ? planById[selectedPlanId].name : "";
  const selectedProductsText = selectedProductLabels(selectedProductIds).join(", ");
  const hasProductionData = data.projects.length > 0 || data.jobs.length > 0 || data.assignments.length > 0;
  const dashboardFeeds: Record<DashboardFeedKey, DashboardFeed> = {
    jobs: {
      title: "Today's Jobs",
      summary: `${todaysJobs.length} ${pluralizeDashboardLabel(todaysJobs.length, "job")} active on ${formatScheduleDate(dashboardToday)}. ${compareDashboardCounts(todaysJobs.length, lastWeekJobs.length, "last week")}.`,
      items: todaysJobs.map((job) => ({
        id: job.id,
        title: job.name,
        detail: [job.phase, `${job.startTime} - ${job.endTime}`, job.location].filter(isText).join(" · "),
        badge: job.status
      }))
    },
    crews: {
      title: "Crews Scheduled Today",
      summary: `${todaysCrewIds.size} ${pluralizeDashboardLabel(todaysCrewIds.size, "crew", "crews")} assigned today. ${compareDashboardCounts(todaysCrewIds.size, lastWeekCrewIds.size, "last week")}.`,
      items: todaysCrews.map((crew) => {
        const assignedJobNames = todaysAssignments
          .filter((assignment) => assignment.crewId === crew.id)
          .map((assignment) => data.jobs.find((job) => job.id === assignment.jobId)?.name)
          .filter(isText);

        return {
          id: crew.id,
          title: crew.name,
          detail: `${crew.lead} · ${summarizeDashboardFeed(assignedJobNames, "No assigned jobs listed")}`,
          badge: crew.status
        };
      })
    },
    equipment: {
      title: "Equipment In Use",
      summary: `${equipmentInUse.length} ${pluralizeDashboardLabel(equipmentInUse.length, "asset")} in use. ${fleetPercent(equipmentInUse.length, data.equipment.length)} of fleet committed.`,
      items: equipmentInUse.map((item) => {
        const assignedProject = item.assignedTo ? projectName(data, item.assignedTo) : "Unassigned";
        const currentJob = item.assignedTo ? activeJobForProject(data, item.assignedTo) : undefined;

        return {
          id: item.id,
          title: item.name,
          detail: [item.type, assignedProject, currentJob?.phase].filter(isText).join(" · "),
          badge: item.status
        };
      })
    },
    delayIQs: {
      title: "DelayIQed Projects",
      summary: `${delayIQedProjects.length} ${pluralizeDashboardLabel(delayIQedProjects.length, "project")} delayIQed. ${compareDashboardCounts(delayIQedProjects.length, lastWeekDelayIQedProjectIds.size, "last week")}.`,
      items: delayIQedProjects.map((project) => {
        const activeDelayIQ = data.delayIQs.find((delayIQ) => delayIQ.projectId === project.id && delayIQ.status !== "Resolved");
        const delayIQDetail = activeDelayIQ ? `${activeDelayIQ.title} · ${activeDelayIQ.impactDays} day impact` : project.scheduleHealth;

        return {
          id: project.id,
          title: project.name,
          detail: `${project.location} · ${delayIQDetail}`,
          badge: project.status
        };
      })
    }
  };
  const selectedFeed = activeFeed ? dashboardFeeds[activeFeed] : undefined;
  const backlogData = [
    { week: "May 11", planned: 620, backlog: 920 },
    { week: "May 18", planned: 780, backlog: 1080 },
    { week: "May 25", planned: 860, backlog: 1010 },
    { week: "Jun 1", planned: 1040, backlog: 1280 },
    { week: "Jun 8", planned: 1130, backlog: 1390 },
    { week: "Jun 15", planned: 1440, backlog: 1660 }
  ];

  // ---- BuildFlow AI Command Center — reference-style panels, derived from live data ----
  const projectsTotal = data.projects.length;
  const onTrackCount = data.projects.filter(
    (project) => project.scheduleHealth === "On Track" || project.scheduleHealth === "Complete"
  ).length;
  const schedulePerf = projectsTotal ? Math.round((onTrackCount / projectsTotal) * 100) : 0;
  const avgUtilization = data.crews.length
    ? Math.round(data.crews.reduce((sum, crew) => sum + crew.utilization, 0) / data.crews.length)
    : 0;
  const openDelayIQs = data.delayIQs.filter((delayIQ) => delayIQ.status !== "Resolved");
  const delayIQImpactDays = openDelayIQs.reduce((sum, delayIQ) => sum + delayIQ.impactDays, 0);
  const costPerf = Math.max(80, 100 - delayIQImpactDays);
  const shortMaterials = data.materials.filter(
    (material) => material.status === "Missing" || material.status === "Waiting on Delivery"
  );
  const firstProject = data.projects[0];
  const secondProject = data.projects[1] ?? data.projects[0];

  const ccStats: CcStatItem[] = [
    { id: "st-sched", icon: Gauge, tone: "blue" as CcTone, label: "Schedule Performance", value: `${schedulePerf}%`, small: "", trend: "up" as const, delta: "+3%", note: "vs last 7 days", spark: [58, 62, 60, 66, 63, 70, 68, Math.max(schedulePerf, 40)] },
    { id: "st-ontrack", icon: CheckCircle2, tone: "green" as CcTone, label: "Projects On Track", value: `${onTrackCount}`, small: `of ${projectsTotal}`, trend: "up" as const, delta: "+2", note: "vs last 7 days", spark: [8, 9, 9, 10, 11, 10, 11, onTrackCount + 1] },
    { id: "st-workflows", icon: Sparkles, tone: "violet" as CcTone, label: "Active Workflows", value: "3", small: "", trend: "flag" as const, delta: `${openDelayIQs.length}`, note: "require attention", spark: [3, 4, 5, 4, 6, 5, 6, 5] },
    { id: "st-labor", icon: HardHat, tone: "amber" as CcTone, label: "Labor Utilization", value: `${avgUtilization}%`, small: "", trend: "up" as const, delta: "+5%", note: "vs last 7 days", spark: [64, 66, 70, 68, 72, 74, 76, Math.max(avgUtilization, 50)] },
    { id: "st-cost", icon: DollarSign, tone: "green" as CcTone, label: "Cost Performance", value: `${costPerf}%`, small: "", trend: "down" as const, delta: "-2%", note: "vs last 7 days", spark: [98, 97, 99, 96, 97, 95, 96, Math.max(costPerf, 80)] }
  ];

  const ccWorkflows = [
    { id: "wf-lookahead", icon: Route, tone: "green" as CcTone, title: `Lookahead Risk Scan${firstProject ? ` — ${firstProject.name}` : ""}`, sub: "Scanning activities 2–6 weeks ahead", progress: 76, ago: "2 mins ago", page: "schedule" as Page },
    { id: "wf-crew", icon: Users, tone: "amber" as CcTone, title: `Crew Rebalance${secondProject ? ` — ${secondProject.name}` : ""}`, sub: "Reallocating crews based on productivity", progress: 58, ago: "5 mins ago", page: "crews" as Page },
    { id: "wf-material", icon: Boxes, tone: "blue" as CcTone, title: "Material ForecastIQ — MEP Package", sub: "Analyzing delivery timelines and constraints", progress: 42, ago: "8 mins ago", page: "materials" as Page }
  ];

  const ccApps: Array<{ id: string; icon: typeof Gauge; tone: CcTone; name: string; desc: string; page: Page }> = [
    { id: "app-schedule", icon: Gauge, tone: "blue", name: "Schedule Intelligence", desc: "AI-powered lookahead and risk detection.", page: "schedule" },
    { id: "app-crew", icon: Users, tone: "green", name: "Crew Planner", desc: "Optimize crew allocation and demand.", page: "crews" },
    { id: "app-material", icon: Boxes, tone: "amber", name: "Material Navigator", desc: "Track, forecastIQ, and align material needs.", page: "materials" },
    { id: "app-field", icon: ImagePlus, tone: "violet", name: "Field Insights", desc: "Daily logs, photos, and field summaries.", page: "field" },
    { id: "app-cost", icon: DollarSign, tone: "orange", name: "Cost Analyzer", desc: "Monitor budgets and cost trends.", page: "reports" }
  ];

  const ccKpis: CcKpiItem[] = [
    {
      id: "kpi-jobs",
      icon: HardHat,
      tone: "orange",
      label: "Today's Jobs",
      value: todaysJobs.length,
      delta: `${summarizeDashboardFeed(todaysJobs.map((job) => job.name), "No jobs scheduled today")} · ${compareDashboardCounts(todaysJobs.length, lastWeekJobs.length, "last week")}`,
      feed: "jobs"
    },
    {
      id: "kpi-crews",
      icon: Users,
      tone: "blue",
      label: "Crews Scheduled Today",
      value: todaysCrewIds.size,
      delta: `${summarizeDashboardFeed(todaysCrewNames, "No crews scheduled today")} · ${compareDashboardCounts(todaysCrewIds.size, lastWeekCrewIds.size, "last week")}`,
      feed: "crews"
    },
    {
      id: "kpi-equip",
      icon: Wrench,
      tone: "yellow",
      label: "Equipment In Use",
      value: equipmentInUse.length,
      delta: `${summarizeDashboardFeed(equipmentInUse.map((item) => item.name), "No equipment currently in use")} · ${fleetPercent(equipmentInUse.length, data.equipment.length)} of fleet`,
      feed: "equipment"
    },
    {
      id: "kpi-delayIQs",
      icon: AlertTriangle,
      tone: "red",
      label: "DelayIQed Projects",
      value: delayIQedProjects.length,
      delta: `${summarizeDashboardFeed(delayIQedProjects.map((project) => project.name), "No delayIQed projects")} · ${compareDashboardCounts(delayIQedProjects.length, lastWeekDelayIQedProjectIds.size, "last week")}`,
      feed: "delayIQs"
    }
  ];

  const ccApprovals = [
    { id: "appr-co", title: "Change Order #CO-129", meta: `${firstProject ? firstProject.name : "Summit Tower"} · ${data.activeUser.name}`, side: "$24,850", ago: "15m ago", primary: "Approve", ghost: "Reject" },
    { id: "appr-timecard", title: "Timecard Exception", meta: `${todaysCrewNames[0] ?? "Field crew"} · Overtime flagged`, side: "1h ago", ago: "", primary: "Review", ghost: "" },
    { id: "appr-material", title: "Material Substitution", meta: shortMaterials[0] ? `${shortMaterials[0].name} · alternate source` : "PVC → PEX for Plumbing", side: "RFI-045", ago: "2h ago", primary: "Review", ghost: "" }
  ].filter((item) => !resolvedApprovals.has(item.id));

  const ccAlerts: Array<{ id: string; icon: typeof AlertTriangle; tone: CcTone; title: string; meta: string; ago: string }> = [];
  openDelayIQs.slice(0, 1).forEach((delayIQ) =>
    ccAlerts.push({ id: `al-${delayIQ.id}`, icon: AlertTriangle, tone: "red", title: delayIQ.title, meta: `${projectName(data, delayIQ.projectId)} · ${delayIQ.impactDays} day impact`, ago: "10m ago" })
  );
  data.weatherAlerts.slice(0, 1).forEach((alert) =>
    ccAlerts.push({ id: `al-${alert.id}`, icon: CloudSun, tone: "amber", title: "Weather delayIQ expected", meta: `${alert.projectId ? projectName(data, alert.projectId) : "All sites"} · ${alert.title}`, ago: "45m ago" })
  );
  shortMaterials.slice(0, 1).forEach((material) =>
    ccAlerts.push({ id: `al-${material.id}`, icon: Truck, tone: "blue", title: "Material delivery delayIQed", meta: `${material.name} · ${projectName(data, material.projectId)}`, ago: "2h ago" })
  );

  const ccRecommendations = [
    { id: "rec-drywall", icon: TrendingUp, title: "Re-sequence drywall activities", meta: "Improve finish package flow by 4 days", page: "schedule" as Page },
    { id: "rec-crew", icon: Users, title: "Add 1 carpentry crew next week", meta: "Demand spike detected on Level 14", page: "crews" as Page },
    { id: "rec-rebar", icon: Boxes, title: "Expedite rebar for Core Walls", meta: "At risk of slipping critical path", page: "materials" as Page }
  ];

  const ccQuickActions: Array<{ id: string; icon: typeof RefreshCcw; label: string; page?: Page }> = [
    { id: "qa-progress", icon: RefreshCcw, label: "Update Progress", page: "field" },
    { id: "qa-lookahead", icon: TrendingUp, label: "Look Ahead", page: "schedule" },
    { id: "qa-rebalance", icon: Users, label: "Rebalance Crew", page: "crews" },
    { id: "qa-weather", icon: CloudSun, label: "Check Weather" },
    { id: "qa-report", icon: FileText, label: "Create Report", page: "reports" }
  ];

  const ccStatsById = Object.fromEntries(ccStats.map((stat) => [stat.id, stat])) as Record<string, CcStatItem>;
  const ccKpisById = Object.fromEntries(ccKpis.map((kpi) => [kpi.id, kpi])) as Record<string, CcKpiItem>;

  // Commit a reorder when a drag settles. Only reorders within the dragged item's
  // own scope (main section, stat card, kpi card, or side-rail panel); per-user.
  const handleDashDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over || active.id === over.id) return;
    const scope = active.data.current?.scope as DashScope | undefined;
    if (!scope || over.data.current?.scope !== scope) return;
    const activeId = String(active.id);
    const overId = String(over.id);
    if (scope === "section") sectionLayout.update(moveId(sectionLayout.order, activeId, overId));
    else if (scope === "stats") statLayout.update(moveId(statLayout.order, activeId, overId));
    else if (scope === "kpis") kpiLayout.update(moveId(kpiLayout.order, activeId, overId));
    else if (scope === "rail") railLayout.update(moveId(railLayout.order, activeId, overId));
  };
  const layoutCustomized =
    sectionLayout.order.join() !== DASH_SECTION_DEFAULT.join() ||
    statLayout.order.join() !== DASH_STAT_DEFAULT.join() ||
    kpiLayout.order.join() !== DASH_KPI_DEFAULT.join() ||
    railLayout.order.join() !== DASH_RAIL_DEFAULT.join();
  const resetDashLayout = () => {
    sectionLayout.reset();
    statLayout.reset();
    kpiLayout.reset();
    railLayout.reset();
  };

  // Body JSX for each reorderable section, looked up by id when rendering the
  // (user-ordered) section list.
  const sectionBodies: Record<string, ReactNode> = {
    ai: <CommandCenterAiPrompt data={data} reload={reload} />,
    quick: (
      <div className="cc-quick" data-reveal>
        {ccQuickActions.map((action) => {
          const Icon = action.icon;
          return (
            <button
              key={action.id}
              type="button"
              className="cc-quick-btn"
              onClick={() => {
                if (action.page) { setPage(action.page); return; }
                if (action.id === "qa-weather") {
                  requestDashboardAiAsk(
                    "Check the weather outlook for my active jobsites this week and tell me which scheduled jobs are at risk from it. Recommend what to move or protect."
                  );
                }
              }}
            >
              <Icon size={16} />
              {action.label}
            </button>
          );
        })}
        <button type="button" className="cc-quick-btn">
          <SlidersHorizontal size={16} />
          More
        </button>
      </div>
    ),
    stats: (
      <SortableContext items={statLayout.order} strategy={rectSortingStrategy}>
        <div className="cc-stat-grid" data-reveal-stagger>
          {statLayout.order.map((id) => {
            const stat = ccStatsById[id];
            return stat ? <DashStatCard key={id} stat={stat} /> : null;
          })}
        </div>
      </SortableContext>
    ),
    kpis: (
      <>
        <SortableContext items={kpiLayout.order} strategy={rectSortingStrategy}>
          <div className="kpi-grid" data-reveal-stagger>
            {kpiLayout.order.map((id) => {
              const kpi = ccKpisById[id];
              return kpi ? (
                <DashKpiCard
                  key={id}
                  kpi={kpi}
                  active={activeFeed === kpi.feed}
                  onOpen={() => setActiveFeed((current) => (current === kpi.feed ? null : kpi.feed))}
                />
              ) : null;
            })}
          </div>
        </SortableContext>
        {selectedFeed && <DashboardFeedPanel feed={selectedFeed} onClose={() => setActiveFeed(null)} />}
      </>
    ),
    apps: (
      <section data-reveal>
        <div className="cc-sec-head">
          <h2>BuildFlow Apps</h2>
          <button type="button" className="cc-link" onClick={() => setPage("reports")}>
            Manage
          </button>
        </div>
        <div className="cc-apps-grid">
          {ccApps.map((app) => {
            const Icon = app.icon;
            return (
              <button key={app.id} type="button" className="cc-app" onClick={() => setPage(app.page)}>
                <span className={`cc-app-ico tone-${app.tone}`}>
                  <Icon size={21} />
                </span>
                <h3>{app.name}</h3>
                <p>{app.desc}</p>
                <span className="cc-app-badge">Active</span>
              </button>
            );
          })}
          <button type="button" className="cc-app add">
            <Plus size={22} />
            <span>Add App</span>
          </button>
        </div>
      </section>
    ),
    workflows: (
      <section data-reveal>
        <div className="cc-sec-head">
          <h2>Active AI Workflows</h2>
          <button type="button" className="cc-link">
            View all
          </button>
        </div>
        <div className="cc-workflows">
          {ccWorkflows.map((workflow) => {
            const Icon = workflow.icon;
            return (
              <article key={workflow.id} className={`cc-wf tone-${workflow.tone}`}>
                <span className="cc-wf-ico">
                  <Icon size={19} />
                </span>
                <div className="cc-wf-body">
                  <strong>{workflow.title}</strong>
                  <span>{workflow.sub}</span>
                </div>
                <ProgressRing value={workflow.progress} tone={workflow.tone} size={44} />
                <span className="cc-status">Running</span>
                <span className="cc-wf-time">{workflow.ago}</span>
                <button type="button" className="cc-wf-view" onClick={() => setPage(workflow.page)}>
                  View
                </button>
              </article>
            );
          })}
        </div>
      </section>
    )
  };

  // Body JSX for each reorderable side-rail panel, looked up by id when rendering
  // the (user-ordered) rail.
  const railBodies: Record<string, ReactNode> = {
    approvals: (
      <section className="cc-panel" data-reveal>
        <div className="cc-panel-head">
          <h2>Pending Approvals</h2>
          <button type="button" className="cc-link">
            View all
          </button>
        </div>
        <div className="cc-list">
          {ccApprovals.length ? (
            ccApprovals.map((approval) => (
              <div key={approval.id} className="cc-approval">
                <div className="cc-appr-top">
                  <span className="cc-appr-dot" />
                  <div className="cc-appr-main">
                    <strong>{approval.title}</strong>
                    <span>{approval.meta}</span>
                  </div>
                  <div className="cc-appr-side">
                    <b>{approval.side}</b>
                    {approval.ago && <em>{approval.ago}</em>}
                  </div>
                </div>
                <div className="cc-appr-actions">
                  {approval.ghost && (
                    <button
                      type="button"
                      className="cc-btn ghost"
                      onClick={() => setResolvedApprovals((prev) => new Set(prev).add(approval.id))}
                    >
                      {approval.ghost}
                    </button>
                  )}
                  <button
                    type="button"
                    className="cc-btn primary"
                    onClick={() => setResolvedApprovals((prev) => new Set(prev).add(approval.id))}
                  >
                    {approval.primary}
                  </button>
                </div>
              </div>
            ))
          ) : (
            <p className="cc-empty-line">All caught up — nothing to approve.</p>
          )}
        </div>
      </section>
    ),
    alerts: (
      <section className="cc-panel" data-reveal>
        <div className="cc-panel-head">
          <h2>Project Alerts</h2>
          <button type="button" className="cc-link" onClick={() => setPage("delayIQs")}>
            View all
          </button>
        </div>
        <div className="cc-list">
          {ccAlerts.length ? (
            ccAlerts.map((alert) => {
              const Icon = alert.icon;
              return (
                <div key={alert.id} className="cc-alert">
                  <span className={`cc-alert-ico tone-${alert.tone}`}>
                    <Icon />
                  </span>
                  <div className="cc-alert-body">
                    <strong>{alert.title}</strong>
                    <span>{alert.meta}</span>
                  </div>
                  <span className="cc-alert-time">{alert.ago}</span>
                </div>
              );
            })
          ) : (
            <p className="cc-empty-line">No active alerts right now.</p>
          )}
        </div>
      </section>
    ),
    recommendations: (
      <section className="cc-panel" data-reveal>
        <div className="cc-panel-head">
          <h2>AI Recommendations</h2>
          <button type="button" className="cc-link">
            View all
          </button>
        </div>
        <div className="cc-list">
          {ccRecommendations.map((recommendation) => {
            const Icon = recommendation.icon;
            return (
              <div key={recommendation.id} className="cc-rec">
                <span className="cc-rec-ico">
                  <Icon />
                </span>
                <div className="cc-rec-body">
                  <strong>{recommendation.title}</strong>
                  <span>{recommendation.meta}</span>
                </div>
                <button type="button" className="cc-rec-btn" onClick={() => setPage(recommendation.page)}>
                  Review
                </button>
              </div>
            );
          })}
        </div>
      </section>
    )
  };

  return (
    <div className="dash-rx" ref={rootRef}>
      <div className="dx-bg" aria-hidden="true">
        <span className="dx-aurora dx-aurora-1" />
        <span className="dx-aurora dx-aurora-2" />
        <span className="dx-aurora dx-aurora-3" />
      </div>
      <div className="dx-cursor" aria-hidden="true" />

      <div className="dx-inner">
        {/* two-column command center: main flow (left) + approvals / alerts / recs rail (right).
            One DndContext wraps both columns so panels reorder within either one. */}
        <DndContext sensors={dragSensors} collisionDetection={dashCollisionDetection} onDragEnd={handleDashDragEnd}>
        <div className="cc-grid">
          <div className="cc-main">
        <header className="cc-hero" data-reveal>
          <span className="cc-eyebrow">
            <span className="dx-dot" />
            Production Control · {formatScheduleDate(dashboardToday)}
          </span>
          {layoutCustomized && (
            <button
              type="button"
              className="dash-reset"
              onClick={resetDashLayout}
              title="Restore the default dashboard layout"
            >
              <RotateCcw size={14} />
              Reset layout
            </button>
          )}
          <div className="cc-hero-head">
            <span className="cc-hero-icon">
              <Sparkles size={24} />
            </span>
            <div>
              <h1 className="cc-hero-title">BuildFlow AI Command Center</h1>
              <p className="cc-hero-sub">Your AI-powered hub for construction scheduling, insights, and execution.</p>
            </div>
          </div>
          {(selectedBusinessType || selectedPlanName || selectedProductsText) && (
            <section className="business-context-banner" aria-label="Selected BuildFlow setup" data-tutorial-id="dashboard-setup-banner">
              <span>{selectedBusinessType ? `${selectedBusinessType} workspace` : "BuildFlow workspace"}</span>
              <strong>
                {[
                  selectedPlanName ? `${selectedPlanName} plan` : "",
                  selectedProductsText ? `Selected products: ${selectedProductsText}` : "",
                  selectedBusinessType ? `Production scheduling tuned for ${selectedBusinessType.toLowerCase()} crews.` : ""
                ]
                  .filter(Boolean)
                  .join(" ")}
              </strong>
            </section>
          )}
        </header>

          <SortableContext items={sectionLayout.order} strategy={verticalListSortingStrategy}>
            {sectionLayout.order.map((sid) => (
              <DashSection key={sid} id={sid} title={DASH_SECTION_TITLES[sid]}>
                {sectionBodies[sid]}
              </DashSection>
            ))}
          </SortableContext>
          </div>

          <aside className="cc-rail">
            <SortableContext items={railLayout.order} strategy={verticalListSortingStrategy}>
              {railLayout.order.map((rid) => (
                <DashSection key={rid} id={rid} scope="rail" title={DASH_RAIL_TITLES[rid]}>
                  {railBodies[rid]}
                </DashSection>
              ))}
            </SortableContext>
          </aside>
        </div>
        </DndContext>

        <section data-reveal>
          <TimeCardDashboardCards data={data} onOpen={() => setPage("timecard")} />
        </section>

        <div className="dx-sec-head" data-reveal>
          <span className="dx-eyebrow-2">Production Context</span>
          <h2 className="dx-h2">
            This week <em>on site.</em>
          </h2>
        </div>

        <div className="dashboard-grid" data-tutorial-id="dashboard-production-context">
          <Panel className="span-2" title="Weekly Production Schedule" action="Jun 15 - Jun 21, 2026" reveal>
            <ProductionSchedule data={data} />
          </Panel>
          <Panel title="Jobs Scheduled This Week" action="View all" reveal>
            <CompactJobList data={data} onOpen={() => setPage("projects")} />
          </Panel>
          <Panel title="Material Readiness" action="View all" reveal>
            {materialCounts.length > 0 ? (
              <div className="chart-row">
                <ResponsiveContainer width="48%" height={190}>
                  <PieChart>
                    <Pie data={materialCounts} dataKey="value" innerRadius={42} outerRadius={78} paddingAngle={1}>
                      {materialCounts.map((entry) => (
                        <Cell key={entry.name} fill={entry.color} />
                      ))}
                    </Pie>
                  </PieChart>
                </ResponsiveContainer>
                <div className="legend-list">
                  {materialCounts.map((item) => (
                    <span key={item.name}>
                      <i style={{ backgroundColor: item.color }} />
                      {item.name}
                      <strong>{item.value}</strong>
                    </span>
                  ))}
                </div>
              </div>
            ) : (
              <InlineEmptyState icon={Boxes} title="No materials added yet" detail="Add materials after creating a project." />
            )}
          </Panel>
          {activeWeatherImpact && (
            <Panel title="Weather Impact Alerts" action="View forecastIQ" reveal>
              <div className="weather-alert">
                <CloudSun size={74} />
                <div>
                  <strong>{activeWeatherImpact.alert.title}</strong>
                  <p>{formatDate(activeWeatherImpact.alert.startsAt)}</p>
                  <span>{activeWeatherImpact.alert.details}</span>
                  <span>Affects {summarizeDashboardFeed(weatherImpactedJobNames, "active jobs")}</span>
                </div>
              </div>
              <div className="panel-note warning">
                <AlertTriangle size={18} />
                {weatherImpactedJobNames.length} active job(s) may be impacted
              </div>
            </Panel>
          )}
          <Panel title="Equipment Conflicts" action="View all" reveal>
            {data.equipment.filter((item) => item.status !== "Available").length > 0 ? (
              data.equipment
                .filter((item) => item.status !== "Available")
                .slice(0, 3)
                .map((item) => (
                  <ResourceRow key={item.id} icon={Wrench} title={item.name} detail={`${item.type} assigned`} badge={item.status} />
                ))
            ) : (
              <InlineEmptyState icon={Wrench} title="No equipment conflicts yet" detail="Equipment assignments will appear after assets are added." />
            )}
          </Panel>
          <Panel title="Upcoming Inspections" action="View all" reveal>
            {data.inspections.length > 0 ? (
              data.inspections.slice(0, 4).map((inspection) => (
                <ResourceRow
                  key={inspection.id}
                  icon={CalendarDays}
                  title={inspection.title}
                  detail={projectName(data, inspection.projectId)}
                  badge={inspection.status}
                />
              ))
            ) : (
              <InlineEmptyState icon={CalendarDays} title="No inspections scheduled yet" detail="Inspection dates will appear after projects are created." />
            )}
          </Panel>
          <Panel title="Production Trend (Backlog)" className="span-2" reveal>
            {hasProductionData ? (
              <ResponsiveContainer width="100%" height={230}>
                <AreaChart data={backlogData}>
                  <defs>
                    <linearGradient id="planned" x1="0" x2="0" y1="0" y2="1">
                      <stop offset="5%" stopColor="#1a73e8" stopOpacity={0.55} />
                      <stop offset="95%" stopColor="#1a73e8" stopOpacity={0.04} />
                    </linearGradient>
                  </defs>
                  <CartesianGrid stroke="rgba(28, 28, 26, 0.07)" />
                  <XAxis dataKey="week" tickLine={false} axisLine={false} />
                  <YAxis tickLine={false} axisLine={false} />
                  <Tooltip />
                  <Area dataKey="planned" stroke="#1a73e8" fill="url(#planned)" strokeWidth={2} />
                  <Area dataKey="backlog" stroke="#d96570" fill="transparent" strokeWidth={2} />
                </AreaChart>
              </ResponsiveContainer>
            ) : (
              <InlineEmptyState icon={TrendingUp} title="No production trend yet" detail="Backlog reporting starts after projects and jobs are entered." />
            )}
          </Panel>
          <Panel title="Active Projects" className="span-2" action="View all projects" reveal>
            <ProjectTable data={data} />
          </Panel>
        </div>
      </div>
    </div>
  );
}

