function ProductionSchedule({ data }: { data: BootstrapPayload }) {
  const rows = data.jobs.slice(0, 4).map((job) => {
    const jobAssignments = data.assignments.filter((assignment) => assignment.jobId === job.id);
    const assignedCrew = jobAssignments[0]
      ? data.crews.find((crew) => crew.id === jobAssignments[0].crewId)?.name
      : undefined;
    const spans = weekDays
      .map((day, index) => {
        const hasAssignment = jobAssignments.some((assignment) => assignment.date === day.date);
        const isInJobRange = job.startDate <= day.date && job.endDate >= day.date;
        return hasAssignment || isInJobRange ? index : -1;
      })
      .filter((index) => index >= 0);

    return {
      name: job.phase,
      crew: assignedCrew ?? job.requiredEquipment,
      spans
    };
  });

  if (rows.length === 0) {
    return <InlineEmptyState icon={CalendarDays} title="No jobs scheduled yet" detail="Create projects, crews, and jobs to build the weekly schedule." />;
  }

  return (
    <div className="mini-schedule">
      <div />
      {weekDays.map((day) => (
        <b key={day.date}>
          {day.day}
          <span>{day.label}</span>
        </b>
      ))}
      {rows.map((row) => (
        <div className="mini-row" key={row.name}>
          <div className="mini-label">
            <strong>{row.name}</strong>
            <span>{row.crew}</span>
          </div>
          {weekDays.map((day, index) => (
            <span key={day.date} className={row.spans.includes(index) ? "bar" : ""} />
          ))}
        </div>
      ))}
    </div>
  );
}

