function formatScheduleDate(date: string) {
  return new Date(`${date}T00:00:00`).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric"
  });
}

function shiftScheduleDate(date: string, days: number) {
  const next = new Date(`${date}T00:00:00`);
  next.setDate(next.getDate() + days);
  return next.toISOString().slice(0, 10);
}

function startOfScheduleWeek(date: string) {
  const day = new Date(`${date}T00:00:00`).getDay();
  const mondayOffset = day === 0 ? -6 : 1 - day;
  return shiftScheduleDate(date, mondayOffset);
}

function buildScheduleWeekDays(startDate: string) {
  return Array.from({ length: 7 }, (_, index) => {
    const date = shiftScheduleDate(startDate, index);
    return {
      date,
      day: new Date(`${date}T00:00:00`).toLocaleDateString("en-US", { weekday: "short" }).toUpperCase(),
      label: formatScheduleDate(date)
    };
  });
}

function formatScheduleWeekRange(days = weekDays) {
  const firstDay = days[0];
  const lastDay = days[days.length - 1];
  return `${formatScheduleDate(firstDay.date)} - ${formatScheduleDate(lastDay.date)}, ${firstDay.date.slice(0, 4)}`;
}

function formatJobDateRange(job: Job) {
  return job.startDate === job.endDate
    ? formatScheduleDate(job.startDate)
    : `${formatScheduleDate(job.startDate)} - ${formatScheduleDate(job.endDate)}`;
}

const scheduleStatusFilterOptions: Status[] = ["Confirmed", "Ready", "Ready to Start", "Planned", "On Site", "DelayIQed", "At Risk"];

type ScheduleViewMode = "Month" | "Week" | "List" | "Gantt" | "Kanban" | "Matrix";

// Kanban lanes group the raw job statuses into the five stages crews actually work in.
