// ---- Month calendar layout: trades, milestones, holidays -------------------
type TradeKey =
  | "concrete"
  | "framing"
  | "mep"
  | "finishes"
  | "sitework"
  | "inspections"
  | "milestone"
  | "holiday";

const TRADE_ORDER: { key: TradeKey; label: string }[] = [
  { key: "concrete", label: "Concrete" },
  { key: "framing", label: "Framing" },
  { key: "mep", label: "MEP" },
  { key: "finishes", label: "Finishes" },
  { key: "sitework", label: "Site Work" },
  { key: "inspections", label: "Inspections" },
  { key: "milestone", label: "Milestone" },
  { key: "holiday", label: "Holiday" }
];

function tradeForText(text: string): TradeKey {
  const value = text.toLowerCase();
  if (/concrete|pour|footing|slab|rebar|formwork|foundation|embed|cure/.test(value)) return "concrete";
  if (/fram|steel|panel|deck|shear|erection|structur|hardware|joist|truss/.test(value)) return "framing";
  if (/mep|electr|plumb|hvac|mechanical|rough-?in|duct|conduit|wiring/.test(value)) return "mep";
  if (/drywall|paint|finish|floor|trim|punch|closeout|window|door|cabinet|tile/.test(value)) return "finishes";
  if (/site|grad|utilit|excavat|earthwork|trench|mobiliz|patch|dewater|paving|layout/.test(value)) return "sitework";
  if (/inspect|permit|review|walk|test|probe|accept/.test(value)) return "inspections";
  return "concrete";
}

function tradeColorVar(key: TradeKey) {
  return `var(--sc-${key})`;
}

const scheduleHolidays: Record<string, string> = {
  "2026-01-01": "New Year's Day",
  "2026-05-25": "Memorial Day",
  "2026-06-19": "Juneteenth",
  "2026-07-03": "Independence Day",
  "2026-09-07": "Labor Day",
  "2026-11-26": "Thanksgiving",
  "2026-12-25": "Christmas Day"
};

function firstOfScheduleMonth(date: string) {
  return `${date.slice(0, 7)}-01`;
}

function shiftScheduleMonth(monthAnchor: string, delta: number) {
  const base = new Date(`${firstOfScheduleMonth(monthAnchor)}T00:00:00`);
  base.setMonth(base.getMonth() + delta);
  return `${base.getFullYear()}-${String(base.getMonth() + 1).padStart(2, "0")}-01`;
}

function formatScheduleMonth(monthAnchor: string) {
  return new Date(`${firstOfScheduleMonth(monthAnchor)}T00:00:00`).toLocaleDateString("en-US", {
    month: "long",
    year: "numeric"
  });
}

type ScheduleMonthCell = {
  date: string;
  dayNum: number;
  inMonth: boolean;
  weekend: boolean;
  weekIndex: number;
};

function buildScheduleMonthCells(monthAnchor: string): ScheduleMonthCell[] {
  const first = firstOfScheduleMonth(monthAnchor);
  const month = first.slice(0, 7);
  const firstDow = new Date(`${first}T00:00:00`).getDay();
  const gridStart = shiftScheduleDate(first, -firstDow);
  return Array.from({ length: 42 }, (_, index) => {
    const date = shiftScheduleDate(gridStart, index);
    const dateObj = new Date(`${date}T00:00:00`);
    const dow = dateObj.getDay();
    return {
      date,
      dayNum: dateObj.getDate(),
      inMonth: date.slice(0, 7) === month,
      weekend: dow === 0 || dow === 6,
      weekIndex: Math.floor(index / 7)
    };
  });
}

type ScheduleMilestone = {
  id: string;
  title: string;
  project: string;
  date: string;
  tone: TradeKey;
};

function deriveScheduleMilestones(data: BootstrapPayload): ScheduleMilestone[] {
  const projectName = (id: string) => data.projects.find((project) => project.id === id)?.name ?? "Project";
  const fromPhases = data.phases
    .filter((phase) => phase.endDate)
    .map((phase) => ({
      id: `ms-phase-${phase.id}`,
      title: `${phase.name} Complete`,
      project: projectName(phase.projectId),
      date: phase.endDate,
      tone: "milestone" as TradeKey
    }));
  const fromProjects = data.projects
    .filter((project) => project.targetCompletion)
    .map((project) => ({
      id: `ms-co-${project.id}`,
      title: "Certificate of Occupancy",
      project: project.name,
      date: project.targetCompletion,
      tone: "milestone" as TradeKey
    }));
  return [...fromPhases, ...fromProjects].sort((left, right) => left.date.localeCompare(right.date));
}

function crewAvailability(crew: Crew): { label: string; cls: string; ratio: string } {
  const ratio = `${crew.size}/${crew.capacity}`;
  if (crew.status === "Overbooked" || crew.utilization >= 88) return { label: "Busy", cls: "busy", ratio };
  if (crew.status === "Scheduled" || crew.utilization >= 62) return { label: "Limited", cls: "limited", ratio };
  return { label: "Available", cls: "available", ratio };
}

